var input=$('hash-input'),algo=$('hash-algo'),out=$('hash-output'),note=$('hash-note');
var subtleOK=!!(window.crypto&&crypto.subtle&&window.isSecureContext);
if(!subtleOK){
  note.textContent='Note: SHA-1/256/384/512 use WebCrypto and need a secure context (HTTPS or localhost). MD5, SHA-224, SHA3-256 and RIPEMD-160 work everywhere.';
}
function hexFromBuffer(buf){
  var b=new Uint8Array(buf),s='';
  for(var i=0;i<b.length;i++)s+=('0'+b[i].toString(16)).slice(-2);
  return s;
}
function compute(){
  var text=input.value||'';
  var a=algo.value;
  out.textContent='computing...';
  function done(h){out.textContent=h;}
  function fail(e){out.textContent='Error: '+(e&&e.message||e);}
  try{
    if(a==='md5')done(md5hex(text));
    else if(a==='sha224')done(sha224hex(text));
    else if(a==='sha3-256')done(sha3_256hex(text));
    else if(a==='ripemd160')done(ripemd160hex(text));
