      if(!subtleOK){fail(new Error('WebCrypto unavailable in this context.'));return;}
      var name={'sha1':'SHA-1','sha256':'SHA-256','sha384':'SHA-384','sha512':'SHA-512'}[a];
      var data=new TextEncoder().encode(text);
      crypto.subtle.digest(name,data).then(function(d){done(hexFromBuffer(d));}).catch(fail);
    }
  }catch(e){fail(e);}
}
