function mthPhpStr(s){ return "'" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'"; }
function mthPhpVal(v, ind){
  var pad = new Array(ind + 1).join('    ');
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'number') return isFinite(v) ? String(v) : 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (Array.isArray(v)){
    if (!v.length) return '[]';
    return '[\n' + v.map(function(x){ return pad + '    ' + mthPhpVal(x, ind + 1); }).join(',\n') + '\n' + pad + ']';
  }
  if (mthIsObj(v)){
    var ks = Object.keys(v);
    if (!ks.length) return '[]';
    return '[\n' + ks.map(function(k){ return pad + '    ' + mthPhpStr(k) + ' => ' + mthPhpVal(v[k], ind + 1); }).join(',\n') + '\n' + pad + ']';
  }
  return mthPhpStr(v);
}
function mthEmitPhp(data){ return '<?php\n\nreturn ' + mthPhpVal(data, 0) + ';\n'; }

function mthIniVal(v){
  if (v === null || v === undefined) return '';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'number') return isFinite(v) ? String(v) : '';
  if (Array.isArray(v)) return v.map(mthIniVal).join(', ');
  if (mthIsObj(v)) return JSON.stringify(v);
  var s = String(v);
  return /[\s=;#"\[\]]|^$/.test(s) ? '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"' : s;
}
function mthEmitIni(data){
  var lines = [];
  function section(o, name){
    var ks = Object.keys(o);
    var scalars = ks.filter(function(k){ return !mthIsObj(o[k]) || Array.isArray(o[k]); });
    var nested = ks.filter(function(k){ return mthIsObj(o[k]) && !Array.isArray(o[k]); });
    lines.push('[' + name + ']');
    scalars.forEach(function(k){ lines.push(String(k) + ' = ' + mthIniVal(o[k])); });
    nested.forEach(function(k){
      lines.push('');
      section(o[k], name + '.' + k);
    });
  }
  if (Array.isArray(data)){
    if (!data.length) return '';
    data.forEach(function(item, i){
      if (i) lines.push('');
      if (mthIsObj(item)) section(item, 'item_' + (i + 1));
      else { lines.push('[item_' + (i + 1) + ']'); lines.push('value = ' + mthIniVal(item)); }
    });
  } else if (mthIsObj(data)){
    var ks = Object.keys(data);
    var scalars = ks.filter(function(k){ return !mthIsObj(data[k]) || Array.isArray(data[k]); });
    var nested = ks.filter(function(k){ return mthIsObj(data[k]) && !Array.isArray(data[k]); });
    scalars.forEach(function(k){ lines.push(String(k) + ' = ' + mthIniVal(data[k])); });
    nested.forEach(function(k){
      if (lines.length) lines.push('');
      section(data[k], String(k));
    });
  } else lines.push('value = ' + mthIniVal(data));
  return lines.join('\n');
}

function mthYamlKey(k){
  var s = String(k);
  return /^[A-Za-z0-9_-]+$/.test(s) ? s : JSON.stringify(s);
}
function mthYamlScalar(v){
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'number') return isFinite(v) ? String(v) : 'null';
  if (Object.prototype.toString.call(v) === '[object Date]') return v.toISOString();
  var s = String(v);
  var need = s === '' || /^\s|\s$/.test(s) || /[\n\r]/.test(s) || /: /.test(s) || /:$/.test(s) || s.indexOf('#') !== -1 ||
    /^[-?:,\[\]{}#&*!|>'"%@`]/.test(s) || /^(true|false|null|~|yes|no|on|off)$/i.test(s) ||
    (/^-?[\d.]/.test(s) && !isNaN(Number(s)));
  return need ? JSON.stringify(s) : s;
}
function mthEmitYaml(data, ind){
  ind = ind || 0;
  var pad = new Array(ind + 1).join('  ');
  if (Array.isArray(data)){
    if (!data.length) return pad + '[]';
    return data.map(function(x){
      if (mthIsObj(x)){
        var ks = Object.keys(x);
        if (!ks.length) return pad + '- {}';
        var out = '';
        ks.forEach(function(k, ki){
          var v = x[k];
          var pre = ki === 0 ? pad + '- ' : pad + '  ';
          if (mthIsObj(v) || Array.isArray(v)) out += pre + mthYamlKey(k) + ':\n' + mthEmitYaml(v, ind + 2) + '\n';
          else out += pre + mthYamlKey(k) + ': ' + mthYamlScalar(v) + '\n';
        });
        return out.replace(/\n$/, '');
      }
      if (Array.isArray(x)) return pad + '-\n' + mthEmitYaml(x, ind + 1);
      return pad + '- ' + mthYamlScalar(x);
    }).join('\n');
  }
  if (mthIsObj(data)){
    var ks2 = Object.keys(data);
    if (!ks2.length) return pad + '{}';
    return ks2.map(function(k){
      var v = data[k];
      if (mthIsObj(v) || Array.isArray(v)) return pad + mthYamlKey(k) + ':\n' + mthEmitYaml(v, ind + 1);
      return pad + mthYamlKey(k) + ': ' + mthYamlScalar(v);
    }).join('\n');
  }
  return pad + mthYamlScalar(data);
}

var K = 'json-to-tsv';
var FROM_NAME = 'JSON';
var TO_NAME = 'TSV';
var PARSE = 'json';
var DELIM = null;
var EMIT = 'tsv';
var ROOT_NAME = null;
var SAMPLE = "[\n  {\n    \"name\": \"Ava\",\n    \"role\": \"Designer\",\n    \"active\": true,\n    \"contact\": { \"email\": \"ava@example.com\", \"city\": \"Jakarta\" },\n    \"tags\": [\"ui\", \"ux\"]\n  },\n  {\n    \"name\": \"Ben\",\n    \"role\": \"Developer\",\n    \"active\": false,\n    \"contact\": { \"email\": \"ben@example.com\", \"city\": \"Bandung\" },\n    \"tags\": [\"backend\"]\n  }\n]";
var DL_NAME = 'converted.tsv';
var DL_MIME = 'text/tab-separated-values';
var HAS_TABLE = false;
var __wb = null;
var __scripts = {};
function loadLib(url, cb){
  if (__scripts[url] === 2){ cb(null); return; }
  if (__scripts[url] === 1){ setTimeout(function(){ loadLib(url, cb); }, 120); return; }
  __scripts[url] = 1;
  var s = document.createElement('script');
  s.src = url; s.async = true;
  s.onload = function(){ __scripts[url] = 2; cb(null); };
  s.onerror = function(){ __scripts[url] = 0; cb(new Error('cdn')); };
  document.head.appendChild(s);
}
function gid(id){ return document.getElementById(id); }
function parseInput(src, cb){
  if (PARSE === 'json'){
    var d;
    try { d = JSON.parse(src); } catch(e){ cb(new Error('Invalid JSON: ' + e.message)); return; }
    cb(null, d); return;
  }
  if (PARSE === 'delim'){
    loadLib('https://cdn.jsdelivr.net/npm/papaparse@5.4.1/papaparse.min.js', function(err){
      if (err){ cb(new Error('Could not load the CSV parser from the CDN. Check your connection and try again.')); return; }
      var res;
      try { res = window.Papa.parse(src, { header: true, skipEmptyLines: 'greedy', delimiter: DELIM }); }
      catch(e){ cb(e); return; }
      var bad = (res.errors || []).filter(function(e){ return e.code !== 'TooFewFields' && e.code !== 'TooManyFields'; });
      if (bad.length){ cb(new Error(bad[0].message + (bad[0].row !== undefined ? ' (near row ' + (bad[0].row + 1) + ')' : ''))); return; }
      cb(null, res.data);
    });
    return;
  }
  if (PARSE === 'yaml'){
    loadLib('https://cdn.jsdelivr.net/npm/js-yaml@4/dist/js-yaml.min.js', function(err){
      if (err){ cb(new Error('Could not load the YAML parser from the CDN. Check your connection and try again.')); return; }
      var d2;
      try { d2 = window.jsyaml.load(src); } catch(e){ cb(e); return; }
      cb(null, d2);
    });
    return;
  }
  if (PARSE === 'toml'){
    var d3;
    try { d3 = mthParseToml(src); } catch(e){ cb(new Error('Invalid TOML: ' + e.message)); return; }
    cb(null, d3); return;
  }
  cb(new Error('Unknown parser'));
}
function emitOutput(data, table, cb){
  try {
    var rows, text, note;
    if (EMIT === 'xlsx'){
      rows = mthRowsOf(data);
      if (!rows.length) throw new Error('No rows found to convert.');
      loadLib('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js', function(err){
        if (err){ cb(new Error('Could not load the spreadsheet library from the CDN. Check your connection and try again.')); return; }
        try {
          var ws = window.XLSX.utils.json_to_sheet(rows.map(function(r){
            var o = {};
            Object.keys(r).forEach(function(k){ o[k] = mthCell(r[k]); });
            return o;
          }));
          var wb = window.XLSX.utils.book_new();
          window.XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
          __wb = wb;
          cb(null, { text: 'Spreadsheet ready: ' + rows.length + ' row(s) x ' + mthUnionKeys(rows).length + ' column(s).\nPress Download to save ' + DL_NAME + '.', note: 'Converted ' + rows.length + ' row(s) to XLSX.' });
        } catch(e){ cb(e); }
      });
      return;
    }
    switch (EMIT){
      case 'tsv': rows = mthRowsOf(data); text = mthEmitDelim(rows, '\t'); note = 'Converted ' + rows.length + ' row(s) to TSV.'; break;
      case 'csv': rows = mthRowsOf(data); text = mthEmitDelim(rows, ','); note = 'Converted ' + rows.length + ' row(s) to CSV.'; break;
      case 'jsonl': text = mthEmitJsonl(data); note = 'Converted to JSONL.'; break;
      case 'toml': text = mthEmitToml(data, ROOT_NAME); note = 'Converted to TOML.'; break;
      case 'xml': text = mthEmitXml(data, ROOT_NAME); note = 'Converted to XML.'; break;
      case 'htmltable': rows = mthRowsOf(data); text = mthEmitHtmlTable(rows); note = 'Converted ' + rows.length + ' row(s) to an HTML table.'; break;
      case 'mdtable': rows = mthRowsOf(data); text = mthEmitMdTable(rows); note = 'Converted ' + rows.length + ' row(s) to a Markdown table.'; break;
      case 'sql': rows = mthRowsOf(data); text = mthEmitSql(rows, table || 'my_table'); note = 'Generated an INSERT for ' + rows.length + ' row(s).'; break;
      case 'phparray': text = mthEmitPhp(data); note = 'Converted to a PHP array.'; break;
      case 'ini': text = mthEmitIni(data); note = 'Converted to INI.'; break;
      case 'yaml': text = mthEmitYaml(data); note = 'Converted to YAML.'; break;
      case 'json': text = mthEmitJson(data); note = 'Converted to JSON.'; break;
      default: throw new Error('Unknown emitter');
    }
    cb(null, { text: text, note: note });
  } catch(e){ cb(e); }
}
var inEl = gid(K + '-input');
if (inEl){
  var outEl = gid(K + '-output'), cBtn = gid(K + '-convert'), sBtn = gid(K + '-sample'),
      cpBtn = gid(K + '-copy'), dlBtn = gid(K + '-download'),
      errBox = gid(K + '-error'), errMsg = gid(K + '-error-msg'),
      statusEl = gid(K + '-status'), tableEl = HAS_TABLE ? gid(K + '-table') : null;
  var lastText = '';
  var deb = null;
  function showErr(t){ if (errMsg) errMsg.textContent = t; if (errBox) errBox.style.display = 'block'; }
  function hideErr(){ if (errBox) errBox.style.display = 'none'; if (errMsg) errMsg.textContent = ''; }
  function doConvert(){
    hideErr();
    var src = inEl.value;
    if (!src.trim()){
      outEl.value = ''; lastText = ''; __wb = null;
      if (statusEl) statusEl.textContent = 'Waiting for ' + FROM_NAME + ' input.';
      return;
    }
    if (statusEl) statusEl.textContent = 'Converting...';
    parseInput(src, function(perr, data){
      if (perr){
        lastText = ''; outEl.value = ''; __wb = null;
        if (statusEl) statusEl.textContent = 'Could not convert. See the error below.';
        showErr(perr.message || String(perr));
        return;
      }
      emitOutput(data, tableEl ? tableEl.value : 'my_table', function(eerr, res){
        if (eerr){
          lastText = ''; outEl.value = ''; __wb = null;
          if (statusEl) statusEl.textContent = 'Could not convert. See the error below.';
          showErr(eerr.message || String(eerr));
          return;
        }
        lastText = res.text;
        outEl.value = res.text;
        if (statusEl) statusEl.textContent = res.note;
      });
    });
  }
  inEl.addEventListener('input', function(){ if (deb) clearTimeout(deb); deb = setTimeout(doConvert, 350); });
  if (cBtn) cBtn.addEventListener('click', function(){ if (deb){ clearTimeout(deb); deb = null; } doConvert(); });
  if (sBtn) sBtn.addEventListener('click', function(){ inEl.value = SAMPLE; doConvert(); inEl.focus(); });
  if (cpBtn) cpBtn.addEventListener('click', function(){
    var t = lastText;
    if (!t) return;
    function done(ok){
      cpBtn.textContent = ok ? 'Copied' : 'Copy';
      setTimeout(function(){ cpBtn.textContent = 'Copy'; }, 1500);
    }
    if (navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(t).then(function(){ done(true); }, function(){ done(false); });
    } else {
      var tmp = document.createElement('textarea');
      tmp.value = t;
      tmp.style.position = 'fixed'; tmp.style.opacity = '0';
      document.body.appendChild(tmp);
      tmp.select();
      var ok = false;
      try { ok = document.execCommand('copy'); } catch(e){}
      tmp.remove();
      done(ok);
    }
  });
  if (dlBtn) dlBtn.addEventListener('click', function(){
    if (EMIT === 'xlsx'){
      if (!__wb || !window.XLSX) return;
      window.XLSX.writeFile(__wb, DL_NAME);
      return;
    }
    if (!lastText) return;
    var blob = new Blob([lastText], { type: DL_MIME + ';charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = DL_NAME;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function(){ URL.revokeObjectURL(url); }, 2000);
  });
}
})();

(function(){
'use strict';
/* Micro Tools Hub converter core: pure functions, no DOM. Shared by every data-format converter page. */
function mthIsObj(v){ return v !== null && typeof v === 'object' && !Array.isArray(v); }

function mthFlatten(o, pfx, out){
  out = out || {}; pfx = pfx || '';
  if (!mthIsObj(o)) return out;
  Object.keys(o).forEach(function(k){
    var v = o[k];
    var key = pfx ? pfx + '.' + k : k;
    if (mthIsObj(v)) mthFlatten(v, key, out);
    else if (Array.isArray(v)){
      if (v.length && v.every(function(x){ return x === null || typeof x !== 'object'; })) out[key] = v.join(', ');
      else out[key] = JSON.stringify(v);
    } else out[key] = (v === undefined ? '' : v);
  });
  return out;
}

function mthRowsOf(data, raw){
  var arr;
  if (Array.isArray(data)) arr = data;
  else if (mthIsObj(data)){
    var ks = Object.keys(data), ak = null, i, vv;
    for (i = 0; i < ks.length; i++){
      vv = data[ks[i]];
      if (Array.isArray(vv) && vv.length && vv.every(mthIsObj)){ ak = ks[i]; break; }
    }
    arr = ak ? data[ak] : [data];
  } else arr = [{ value: data }];
  if (raw) return arr;
  return arr.map(function(r){ return mthIsObj(r) ? mthFlatten(r) : { value: r }; });
}

function mthUnionKeys(rows){
  var keys = [], seen = {};
  rows.forEach(function(r){
    Object.keys(r).forEach(function(k){ if (!seen[k]){ seen[k] = 1; keys.push(k); } });
  });
  return keys;
}

function mthCell(v){ return (v === null || v === undefined) ? '' : String(v); }

/* ---------- TOML parser (tables, arrays of tables, dotted keys, inline tables, multiline arrays) ---------- */
function mthParseToml(src){
  var root = {};
  var cur = root;

  function assignPath(o, parts, val){
    for (var i = 0; i < parts.length - 1; i++){
      var k = parts[i];
      if (!mthIsObj(o[k])) o[k] = {};
      o = o[k];
    }
    o[parts[parts.length - 1]] = val;
  }

  function parseKeyStr(k){
    var parts = [], buf = '', q = null, i, c;
    for (i = 0; i < k.length; i++){
