    if (!ks2.length) return pad + '{}';
    return ks2.map(function(k){
      var v = data[k];
      if (mthIsObj(v) || Array.isArray(v)) return pad + mthYamlKey(k) + ':\n' + mthEmitYaml(v, ind + 1);
      return pad + mthYamlKey(k) + ': ' + mthYamlScalar(v);
    }).join('\n');
  }
