function mthIsObj(v){ return v !== null && typeof v === 'object' && !Array.isArray(v); }

function mthFlatten(o, pfx, out){
  out = out || {}; pfx = pfx || '';
  if (!mthIsObj(o)) return out;
  Object.keys(o).forEach(function(k){
    var v = o[k];
