          __wb = wb;
          cb(null, { text: 'Spreadsheet ready: ' + rows.length + ' row(s) x ' + mthUnionKeys(rows).length + ' column(s).\nPress Download to save ' + DL_NAME + '.', note: 'Converted ' + rows.length + ' row(s) to XLSX.' });
        } catch(e){ cb(e); }
