    var nested = ks.filter(function(k){ return mthIsObj(o[k]) && !Array.isArray(o[k]); });
    lines.push('[' + name + ']');
    scalars.forEach(function(k){ lines.push(String(k) + ' = ' + mthIniVal(o[k])); });
