          if (str[pos.i] === ']'){ pos.i++; break; }
          arr.push(val());
          while (pos.i < str.length && /\s/.test(str[pos.i])) pos.i++;
          if (str[pos.i] === ','){ pos.i++; continue; }
          if (str[pos.i] === ']'){ pos.i++; break; }
