var $=function(id){return document.getElementById(id);};
var cvInput=$('cv-in'),cvOutput=$('cv-out'),cvErr=$('cv-err'),cvStatus=$('cv-status');
function cvSetErr(m){cvErr.textContent=m;cvErr.style.display='block';}
function cvClearErr(){cvErr.textContent='';cvErr.style.display='none';}
function cvDoConvert(){
  cvClearErr();
  var text=cvInput.value;
  if(!text.trim()){cvSetErr('Paste some XML above, or press Sample to load an example.');cvOutput.value='';cvStatus.textContent='Waiting for input.';return;}
  var parsed;
  try{parsed=cvParseXML(text);}
  catch(e){cvSetErr('Could not parse as '+"XML"+': '+e.message);cvOutput.value='';cvStatus.textContent='Parse failed.';return;}
  var result;
  try{result=cvSqlDump(parsed,document.getElementById('cv-table').value);}
  catch(e){cvSetErr('Conversion failed: '+e.message);cvOutput.value='';cvStatus.textContent='Conversion failed.';return;}
  cvOutput.value=result;
  var n=(parsed&&parsed.cols&&parsed.rows)?parsed.rows.length:0;
  cvStatus.textContent='Done. '+(n?(n+' row'+(n===1?'.':'s')+' converted. '):'')+'Output is '+result.length+' characters.';
}
$('cv-convert').addEventListener('click',cvDoConvert);
$('cv-sample').addEventListener('click',function(){cvInput.value="<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<products>\n  <product sku=\"A100\" in_stock=\"true\">\n    <name>Wireless Mouse</name>\n    <price>24.99</price>\n    <category>Accessories</category>\n  </product>\n  <product sku=\"B205\" in_stock=\"false\">\n    <name>USB-C Hub</name>\n    <price>39.50</price>\n    <category>Accessories</category>\n  </product>\n</products>\n";cvDoConvert();});
$('cv-clear').addEventListener('click',function(){cvInput.value='';cvOutput.value='';cvClearErr();cvStatus.textContent='Waiting for input.';cvInput.focus();});
$('cv-copy').addEventListener('click',function(){
  if(!cvOutput.value){cvSetErr('Nothing to copy yet. Convert something first.');return;}
  function done(){cvStatus.textContent='Copied to clipboard.';}
  function manual(){cvOutput.select();try{document.execCommand('copy');done();}catch(e){cvSetErr('Copy failed. Select the output and press Ctrl+C.');}}
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(cvOutput.value).then(done,manual);}
  else{manual();}
});

})();

