  return '<?php\n\nreturn '+pval(data,0)+';\n';
}
function cvIniDump(v){
  function sval(x){
    if(x===null||x===undefined)return '';
    if(x===true)return 'true';if(x===false)return 'false';
    if(typeof x==='number')return isFinite(x)?String(x):'""';
    var s=String(x);
    if(s===''||/[\n\r"=;#]/.test(s)||/^\s/.test(s)||/\s$/.test(s))return '"'+s.replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"';
    return s;
  }
  var head=[],body=[];
  function section(name,o){
    body.push('['+String(name).replace(/[\[\]\r\n]/g,'')+']');
    Object.keys(o).forEach(function(k){
      var x=o[k];
      if(Array.isArray(x))x.forEach(function(e){body.push(k+'[] = '+sval(e));});
      else body.push(k+' = '+sval(cvIsObj(x)?JSON.stringify(x):x));
    });
    body.push('');
  }
  var data=v;
  if(data&&data.cols&&Array.isArray(data.rows)){
    data.rows.forEach(function(r,ix){var o={};data.cols.forEach(function(c){o[c]=r[c];});section('row_'+(ix+1),o);});
  }else if(cvIsObj(data)){
    Object.keys(data).forEach(function(k){
      var x=data[k];
      if(cvIsObj(x)&&!Array.isArray(x))section(k,x);
      else if(Array.isArray(x)&&x.length&&x.every(cvIsObj))x.forEach(function(it,ix){section(k+'_'+(ix+1),it);});
      else if(Array.isArray(x))x.forEach(function(e){head.push(k+'[] = '+sval(e));});
      else head.push(k+' = '+sval(x));
    });
