  var L=['| '+t.cols.map(cvMdCell).join(' | ')+' |','| '+t.cols.map(function(){return '---';}).join(' | ')+' |'];
  t.rows.forEach(function(r){L.push('| '+t.cols.map(function(c){return cvMdCell(r[c]);}).join(' | ')+' |');});
  return L.join('\n');
}
function cvSqlDump(v,table){
  var t=cvToTable(v);
  table=String(table||'data').replace(/[^A-Za-z0-9_.$-]/g,'');
  if(!table)table='data';
  function val(x){
    if(x===null||x===undefined||x==='')return 'NULL';
    if(x===true)return 'TRUE';if(x===false)return 'FALSE';
    if(typeof x==='number')return isFinite(x)?String(x):'NULL';
    var s=String(x);
    if(/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(s))return s;
    return "'"+s.replace(/\\/g,'\\\\').replace(/'/g,"\\'")+"'";
  }
  var cols=t.cols.map(function(c){return '`'+String(c).replace(/`/g,'``')+'`';}).join(', ');
  var L=['INSERT INTO `'+table+'` ('+cols+') VALUES'];
  t.rows.forEach(function(r,ix){
    L.push('  ('+t.cols.map(function(c){return val(r[c]);}).join(', ')+(ix<t.rows.length-1?'),':');'));
  });
