    body.push('['+String(name).replace(/[\[\]\r\n]/g,'')+']');
    Object.keys(o).forEach(function(k){
      var x=o[k];
      if(Array.isArray(x))x.forEach(function(e){body.push(k+'[] = '+sval(e));});
      else body.push(k+' = '+sval(cvIsObj(x)?JSON.stringify(x):x));
    });
