  if(!text.trim()){cvSetErr('Paste some SQL Insert above, or press Sample to load an example.');cvOutput.value='';cvStatus.textContent='Waiting for input.';return;}
  var parsed;
  try{parsed=cvParseSQL(text);}
  catch(e){cvSetErr('Could not parse as '+"SQL Insert"+': '+e.message);cvOutput.value='';cvStatus.textContent='Parse failed.';return;}
  var result;
  try{result=cvXmlDump(parsed);}
  catch(e){cvSetErr('Conversion failed: '+e.message);cvOutput.value='';cvStatus.textContent='Conversion failed.';return;}
  cvOutput.value=result;
  var n=(parsed&&parsed.cols&&parsed.rows)?parsed.rows.length:0;
  cvStatus.textContent='Done. '+(n?(n+' row'+(n===1?'.':'s')+' converted. '):'')+'Output is '+result.length+' characters.';
}
