  if(n.kind==="int")return"int";
  if(n.kind==="float")return"double";
  if(n.kind==="bool")return"bool";
  if(n.kind==="null"||n.kind==="any")return"nlohmann::json";
  if(n.kind==="array")return"std::vector<"+cppT(n.item,key+"Item",defs)+">";
  var cn=pascal(key||"item");cppStruct(n,cn,defs);return cn;
}
function cppStruct(n,cn,defs){
  var L=["struct "+cn+" {"];
  var any=false;
  for(var k in n.props){
    any=true;
    var p=n.props[k];
    var t=cppT(p,k,defs);
    if(p.optional)t="std::optional<"+t+">";
    L.push("    "+t+" "+sanitize(k)+";");
  }
  if(!any)L.push("    // no fields");
  L.push("};");
  defs.push(L.join("\n"));
}
function emit(node,name){
  var defs=[];
  var head="#include <string>\n#include <vector>\n#include <optional>\n#include <nlohmann/json.hpp>";
  if(node.kind==="object"){cppT(node,name,defs);return head+"\n\n"+defs.join("\n\n");}
  if(node.kind==="array"&&node.item.kind==="object"){
    var t=cppT(node.item,name+"Item",defs);
    return head+"\n\n"+defs.join("\n\n")+"\n\n// Root value type: std::vector<"+t+">";
  }
