function camel(s){var p=sanitize(s);return p.charAt(0).toLowerCase()+p.slice(1);}
function pascal(s){return cap(camel(s));}
function snake(s){return sanitize(s).replace(/([a-z0-9])([A-Z])/g,"$1_$2").toLowerCase();}
function safeKey(k){return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(k)?k:JSON.stringify(k);}
function merge(a,b){
  if(!a)return b; if(!b)return a;
  if(a.kind==="null")return b;
  if(b.kind==="null")return a;
  if(a.kind==="any")return b;
  if(b.kind==="any")return a;
  if(a.kind!==b.kind){
    if((a.kind==="int"&&b.kind==="float")||(a.kind==="float"&&b.kind==="int"))return{kind:"float"};
    return{kind:"any"};
  }
  if(a.kind==="array")return{kind:"array",item:merge(a.item,b.item)};
  if(a.kind==="object"){
    var p={},k;
    for(k in a.props)p[k]=a.props[k];
    for(k in b.props)p[k]=(k in p)?merge(p[k],b.props[k]):b.props[k];
    var o={kind:"object",props:p};
    return o;
  }
  return a;
}
function infer(v){
  if(v===null||v===undefined)return{kind:"null"};
  if(Array.isArray(v)){
    var it={kind:"any"},i,counts={},nObj=0;
    for(i=0;i<v.length;i++){
      var iv=infer(v[i]);
      if(iv.kind==="object"){nObj++;for(var k in iv.props)counts[k]=(counts[k]||0)+1;}
      it=merge(it,iv);
    }
    if(it.kind==="object"&&nObj>0){
      for(var k2 in it.props){if((counts[k2]||0)<nObj)it.props[k2].optional=true;}
    }
    if(v.length===0)return{kind:"array",item:{kind:"any"}};
    return{kind:"array",item:it};
  }
  var t=typeof v;
  if(t==="object"){
    var p={};
    for(var k in v)if(Object.prototype.hasOwnProperty.call(v,k))p[k]=infer(v[k]);
    return{kind:"object",props:p};
  }
  if(t==="number")return{kind:(isFinite(v)&&Math.floor(v)===v&&Math.abs(v)<9007199254740991)?"int":"float"};
  if(t==="boolean")return{kind:"bool"};
  return{kind:"string"};
}
function markNullOptional(n){
  if(!n)return;
  if(n.kind==="object"){for(var k in n.props){var p=n.props[k];if(p.kind==="null")p.optional=true;markNullOptional(p);}}
  else if(n.kind==="array")markNullOptional(n.item);
}
function rT(n){
  if(n.kind==="string")return"character()";
  if(n.kind==="int")return"integer()";
  if(n.kind==="float")return"numeric()";
  if(n.kind==="bool")return"logical()";
  return"I(list())";
}
function emit(node,name){
  if(node.kind!=="object")return"# Root is not an object; build the data.frame manually.";
  var L=["df <- data.frame("];
  var any=false;
  for(var k in node.props){
    any=true;
    L.push("  "+snake(k)+" = "+rT(node.props[k])+",");
  }
  if(any)L[L.length-1]=L[L.length-1].replace(/,$/,"");
  else L.push("  # no columns");
  L.push("  stringsAsFactors = FALSE");
  L.push(")");
  L.push("");
  L.push("# str(df)  # inspect the structure");
  return L.join("\n");
}
