function showErr(m){var e=$('err');e.textContent=m;e.style.display='block';}
function hideErr(){$('err').style.display='none';}
function run(fn){var src=$('input').value;hideErr();if(!src.trim()){$('output').value='';return;}
try{$('output').value=fn(src);}catch(ex){showErr('Conversion failed: '+ex.message);$('output').value='';}}

function fmtGraphQL(s){
  var toks=[],i=0,n=s.length,cur='';
  function pc(){if(cur.trim()){toks.push(cur.trim());cur='';}}
  while(i<n){var c=s[i];
    if(c==='"'){var j=i+1;while(j<n&&s[j]!=='"'){if(s[j]==='\\')j++;j++;}toks.push(s.slice(i,Math.min(j+1,n)));i=j+1;continue;}
    if(c==='{'||c==='}'||c==='('||c===')'||c===','){pc();toks.push(c);i++;continue;}
    if(c===':'){pc();toks.push(':');i++;continue;}
    if(c==='#'){var k=s.indexOf('\n',i);if(k<0)k=n;toks.push(s.slice(i,k));i=k;continue;}
    if(/\s/.test(c)){pc();i++;continue;}
    cur+=c;i++;}
  pc();
  function pad(d){return new Array(d+1).join('  ');}
  var out=[],ind=0,line='',prevWord=false;
  function fl(){if(line.trim()){out.push(pad(ind)+line.trim());line='';}}
  function isHeader(){return /^(query|mutation|subscription|fragment)\b/.test(line);}
  for(var t2=0;t2<toks.length;t2++){var t=toks[t2];
    var isW=(t!=='{'&&t!=='}'&&t!=='('&&t!==')'&&t!==','&&t!==':');
    if(t==='{'){line+=(line?' ':'')+'{';fl();ind++;}
    else if(t==='}'){fl();ind=Math.max(0,ind-1);out.push(pad(ind)+'}');}
    else if(t==='('){line+='(';}
    else if(t===')'){line+=')';}
    else if(t===','){line+=',';fl();}
    else if(t===':'){line+=': ';}
    else{if(isW&&prevWord&&!isHeader())fl();if(line&&!/(:\s?|\()$/.test(line))line+=' ';line+=t;}
    prevWord=isW;}
  fl();
  return out.join('\n');
}

