function fmtMarkdown(s){
  var lines=s.split('\n'),out=[],fence=false;
  lines.forEach(function(raw){
    var line=raw.replace(/[ \t]+$/,'');
    if(/^\s*```/.test(line)){fence=!fence;out.push(line.trim());return;}
    if(fence){out.push(line);return;}
    var t=line.trim(),m;
    if(!t){out.push('');return;}
    if((m=t.match(/^(#{1,6})\s*(.*)$/))){out.push(m[1]+' '+m[2].trim());return;}
    if((m=t.match(/^([*+-])\s+(.*)$/))){out.push('- '+m[2].trim());return;}
    if((m=t.match(/^(\d+)[.)]\s+(.*)$/))){out.push(m[1]+'. '+m[2].trim());return;}
    if((m=t.match(/^>\s?(.*)$/))){out.push('> '+m[1].trim());return;}
    if(/^(-{3,}|\*{3,}|_{3,})$/.test(t)){out.push('---');return;}
    out.push(t.replace(/[ \t]{2,}/g,' '));
  });
  var res=[];
  out.forEach(function(l,i){
    if(/^#{1,6} /.test(l)&&i>0&&res[res.length-1]!=='')res.push('');
    res.push(l);
  });
  return res.join('\n').replace(/\n{3,}/g,'\n\n').trim();
}

