function sqlFormatter(extra){
  var base=['SELECT','FROM','WHERE','GROUP BY','ORDER BY','HAVING','LIMIT','OFFSET','UNION ALL','UNION','INTERSECT','EXCEPT','JOIN','INNER JOIN','LEFT JOIN','LEFT OUTER JOIN','RIGHT JOIN','RIGHT OUTER JOIN','FULL JOIN','FULL OUTER JOIN','CROSS JOIN','ON','USING','AND','OR','NOT','IN','BETWEEN','LIKE','IS NOT NULL','IS NULL','AS','DISTINCT','INSERT INTO','VALUES','UPDATE','DELETE FROM','CREATE TABLE','ALTER TABLE','DROP TABLE','PRIMARY KEY','FOREIGN KEY','REFERENCES','DEFAULT','CONSTRAINT','IF NOT EXISTS','IF EXISTS','CASE','WHEN','THEN','ELSE','END','ASC','DESC','INTO'];
  var kw=base.concat(extra).sort(function(a,b){return b.length-a.length;});
  function pad(d){return new Array(d+1).join('  ');}
  return function(src){
    var store=[];
    function ph(s){store.push(s);return '\x01'+(store.length-1)+'\x01';}
    var s=src.replace(/--[^\n]*/g,ph).replace(/\/\*[\s\S]*?\*\//g,ph)
      .replace(/'(?:[^'\\]|\\[\s\S])*'/g,ph).replace(/"(?:[^"\\]|\\[\s\S])*"/g,ph)
      .replace(/`[^`]*`/g,ph).replace(/\[[^\]]*\]/g,ph);
    kw.forEach(function(k){
      var re=new RegExp('\\b'+k.replace(/ /g,'\\s+'),'gi');
      s=s.replace(re,k);
    });
    s=s.replace(/\s+/g,' ').trim();
    ['SELECT','FROM','WHERE','GROUP BY','ORDER BY','HAVING','LIMIT','OFFSET','UNION ALL','UNION','INTERSECT','EXCEPT','INSERT INTO','VALUES','UPDATE','DELETE FROM'].forEach(function(k){
      s=s.replace(new RegExp('\\s*\\b'+k.replace(/ /g,'\\s+')+'\\b','g'),'\n'+k);
    });
    s=s.replace(/\s*\b((?:LEFT|RIGHT|FULL|INNER|CROSS)(?:\s+OUTER)?\s+JOIN|JOIN)\b/g,'\n$1');
    s=s.replace(/\s*\bON\b/g,'\n  ON').replace(/\s*\b(AND|OR)\b/g,'\n  $1');
    var lines=s.split('\n'),out=[],depth=0;
    lines.forEach(function(l){
      var t=l.trim();if(!t)return;
      var opens=(t.match(/\(/g)||[]).length,closes=(t.match(/\)/g)||[]).length;
      var d=depth;for(var q=0;q<closes;q++)d=Math.max(0,d-1);
      out.push(pad(d)+t);
      depth=Math.max(0,depth+opens-closes);
    });
    var fin=out.map(function(l){
      var m=l.match(/^(\s*)SELECT\s+(.+)$/);
      if(m&&m[2].indexOf('\x01')<0){
        var parts=m[2].split(/,(?![^(]*\))/);
        if(parts.length>1)return m[1]+'SELECT\n'+parts.map(function(x){return m[1]+'  '+x.trim();}).join(',\n');
      }
      return l;
    });
    var r=fin.join('\n');
    store.forEach(function(o,i){r=r.split('\x01'+i+'\x01').join(o);});
    return r.replace(/[ \t]+\n/g,'\n').trim();
  };
}

