var VOIDTAGS={area:1,base:1,br:1,col:1,embed:1,hr:1,img:1,input:1,link:1,meta:1,param:1,source:1,track:1,wbr:1};
function parseHTML(html){
  var root={tag:'#root',attrs:{},children:[]},stack=[root];
  var re=/<!--[\s\S]*?-->|<\/?[a-zA-Z][^<>]*>|[^<]+/g,m;
  while((m=re.exec(html))){
    var t=m[0];
    if(t.charAt(0)!=='<'){stack[stack.length-1].children.push({tag:'#text',text:t});continue;}
    if(t.charAt(1)==='!')continue;
    if(t.charAt(1)==='/'){
      var nm=t.slice(2,-1).trim().toLowerCase().split(/\s/)[0];
      while(stack.length>1&&stack[stack.length-1].tag!==nm)stack.pop();
      if(stack.length>1)stack.pop();continue;
    }
    var self=/\/\s*>$/.test(t);
    var inner=t.slice(1,self?t.length-2:t.length-1);
    var sp=inner.search(/\s/);
    var tag=(sp<0?inner:inner.slice(0,sp)).toLowerCase();
    if(!/^[a-zA-Z]/.test(tag))continue;
    var attrs={},rest=sp<0?'':inner.slice(sp);
    var ar=/([a-zA-Z_:][\w:.-]*)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g,am;
    while((am=ar.exec(rest))){attrs[am[1].toLowerCase()]=am[2]!==undefined?am[2]:(am[3]!==undefined?am[3]:(am[4]!==undefined?am[4]:''));}
    var node={tag:tag,attrs:attrs,children:[]};
    stack[stack.length-1].children.push(node);
    if(!self&&!VOIDTAGS[tag])stack.push(node);
  }
  return root;
}
function escHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function findTag(n,t){if(n.tag===t)return n;var ch=n.children||[];for(var i=0;i<ch.length;i++){var f=findTag(ch[i],t);if(f)return f;}return null;}
function serialize(node,escText){
  if(node.tag==='#text')return escText?escHtml(node.text):node.text;
  if(node.tag==='#root')return node.children.map(function(c){return serialize(c,escText);}).join('');
  var a='';for(var k in node.attrs){a+=' '+k+'="'+node.attrs[k].replace(/"/g,'&quot;')+'"';}
  if(VOIDTAGS[node.tag])return '<'+node.tag+a+'>';
  return '<'+node.tag+a+'>'+node.children.map(function(c){return serialize(c,escText);}).join('')+'</'+node.tag+'>';
}

function htmlToPug(src){
  var root=parseHTML(src),out=[];
  function walk(n,ind){
    var pad=new Array(ind+1).join('  ');
    if(n.tag==='#text'){var t=n.text.replace(/\s+/g,' ');if(t.trim())out.push(pad+'| '+t.trim());return;}
    var line=n.tag;
    if(n.attrs.id)line+='#'+n.attrs.id;
    (n.attrs['class']||'').split(/\s+/).forEach(function(c){if(c)line+='.'+c;});
    var at=[];for(var k in n.attrs){if(k==='id'||k==='class')continue;at.push(k+(n.attrs[k]?'="'+n.attrs[k].replace(/"/g,'&quot;')+'"':''));}
    if(at.length)line+='('+at.join(', ')+')';
    var els=n.children.filter(function(c){return c.tag!=='#text';});
    var str=n.children.filter(function(c){return c.tag==='#text'&&c.text.trim();});
    if(!els.length&&str.length){
      var all=str.map(function(c){return c.text;}).join(' ').replace(/\s+/g,' ').trim();
      if(all){out.push(pad+line+' '+all);return;}
    }
    out.push(pad+line);
    n.children.forEach(function(c){walk(c,ind+1);});
  }
  var body=findTag(root,'body');
  var start=body?body.children:root.children.filter(function(c){return c.tag!=='head';});
  start.forEach(function(c){walk(c,0);});
  return out.join('\n');
}

