function pugToHtml(src){
  var VOID={area:1,base:1,br:1,col:1,embed:1,hr:1,img:1,input:1,link:1,meta:1,param:1,source:1,track:1,wbr:1};
  function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
  var lines=src.split('\n'),root={children:[]},stack=[{n:root,ind:-1}];
  lines.forEach(function(raw){
    if(!raw.trim())return;
    var ind=raw.match(/^ */)[0].length,line=raw.trim();
    if(line.slice(0,2)==='//')return;
    var node;
    if(line.charAt(0)==='|'){node={tag:'#text',text:line.slice(1).replace(/^ /,'')};}
    else{
      var m=line.match(/^([a-zA-Z][\w-]*)?((?:[#.][\w-]+)*)\s*(\((.*)\))?\s?(.*)$/);
      if(!m||(!m[1]&&!m[2]&&!m[4]&&!m[5]))return;
      var tag=m[1]||'div',attrs={},cls=[];
      (m[2]||'').replace(/([#.])([\w-]+)/g,function(x,p,c){if(p==='#')attrs.id=c;else cls.push(c);return '';});
      if(cls.length)attrs['class']=cls.join(' ');
      if(m[4]){var ar=/([\w-]+)\s*=\s*("[^"]*"|'[^']*'|[^\s,]+)/g,am;
        while((am=ar.exec(m[4]))){var v=am[2];if((v.charAt(0)==='"'&&v.slice(-1)==='"')||(v.charAt(0)==="'"&&v.slice(-1)==="'"))v=v.slice(1,-1);attrs[am[1].toLowerCase()]=v;}}
      node={tag:tag,attrs:attrs,children:[]};
      var rest=(m[5]||'').trim();
      if(rest)node.children.push({tag:'#text',text:rest});
    }
    while(stack.length>1&&stack[stack.length-1].ind>=ind)stack.pop();
    stack[stack.length-1].n.children.push(node);
    if(node.tag!=='#text'&&!VOID[node.tag])stack.push({n:node,ind:ind});
  });
  function rend(n){
    if(n.tag==='#text')return esc(n.text);
    var a='';for(var k in n.attrs){a+=' '+k+'="'+esc(n.attrs[k])+'"';}
    if(VOID[n.tag])return '<'+n.tag+a+'>';
    return '<'+n.tag+a+'>'+n.children.map(rend).join('')+'</'+n.tag+'>';
  }
  return root.children.map(rend).join('\n');
}

