function parseCssRules(css){
  css=css.replace(/\/\*[\s\S]*?\*\//g,'');
  var rules=[],re=/([^{}]+)\{([^{}]*)\}/g,m;
  while((m=re.exec(css))){
    var sel=m[1].trim();
    if(!sel)continue;
    if(sel.charAt(0)==='@'){rules.push({at:sel,body:m[2].trim().replace(/\s+/g,' ')});continue;}
    var decls=m[2].split(';').map(function(d){return d.trim().replace(/\s*:\s*/g,': ');}).filter(Boolean);
    if(decls.length)rules.push({sel:sel,decls:decls});
  }
  return rules;
}

function cssToScss(src){
  var rules=parseCssRules(src),tree={kids:{}},ats=[];
  rules.forEach(function(r){
    if(r.at){ats.push(r);return;}
    r.sel.split(',').forEach(function(sel){
      var parts=sel.trim().replace(/\s*([>+~])\s*/g,' $1 ').split(/\s+/),merged=[];
      parts.forEach(function(p,ix){
        if(/^[>+~]$/.test(p)&&merged.length){merged[merged.length-1]=merged[merged.length-1]+' '+p+' '+(parts[ix+1]||'');}
        else if(ix>0&&/^[>+~]$/.test(parts[ix-1])){}
        else merged.push(p);
      });
      var node=tree;
      merged.forEach(function(p){p=p.trim();if(!node.kids[p])node.kids[p]={kids:{},decls:[]};node=node.kids[p];});
      node.decls=node.decls.concat(r.decls);
    });
  });
  var out=[];
  function pad(d){return new Array(d+1).join('  ');}
  function emit(node,ind){
    Object.keys(node.kids).forEach(function(k){
      var ch=node.kids[k];
      out.push(pad(ind)+k+' {');
      ch.decls.forEach(function(d){out.push(pad(ind+1)+d+';');});
      emit(ch,ind+1);
      out.push(pad(ind)+'}');
    });
