    while((am=ar.exec(rest))){attrs[am[1].toLowerCase()]=am[2]!==undefined?am[2]:(am[3]!==undefined?am[3]:(am[4]!==undefined?am[4]:''));}
    var node={tag:tag,attrs:attrs,children:[]};
