function setupCopy(btnId,outId,label){
  var btn=el(btnId);
  btn.addEventListener('click',function(){
    var t=el(outId).textContent;
    function done(ok){btn.textContent=ok?'Copied':label;setTimeout(function(){btn.textContent=label;},1500);}
    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(function(){done(true);},function(){done(false);});}
    else{var ta=document.createElement('textarea');ta.value=t;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();var ok=false;try{ok=document.execCommand('copy');}catch(e){}ta.remove();done(ok);}
  });
}
function loadScript(src,cb){
  var s=document.createElement('script');s.src=src;s.async=true;
  s.onload=function(){cb(true);};s.onerror=function(){cb(false);};
  document.head.appendChild(s);
}
var P='sha224';
function compute(){try{showOut(P+'-out',CryptoJS.SHA224(el(P+'-input').value).toString(CryptoJS.enc.Hex));}catch(e){showOut(P+'-out','Error: '+(e&&e.message?e.message:e));}}
el(P+'-gen').addEventListener('click',function(){
  var btn=el(P+'-gen');
  if(window.CryptoJS&&window.CryptoJS.SHA224){compute();return;}
  btn.disabled=true;btn.textContent='Loading library...';
  loadScript('https://cdnjs.cloudflare.com/ajax/libs/crypto-js/4.2.0/crypto-js.min.js',function(ok){
    btn.disabled=false;btn.textContent='Generate digest';
    if(ok&&(window.CryptoJS&&window.CryptoJS.SHA224))compute();
    else showOut(P+'-out','Could not load the crypto library. Check your connection and try again.');
  });
});
setupCopy(P+'-copy',P+'-out','Copy');
})();

