var P='argon2';
function randSalt(){
  var c='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',s='';
  var r=new Uint8Array(16);
  if(window.crypto&&window.crypto.getRandomValues)window.crypto.getRandomValues(r);else for(var i=0;i<16;i++)r[i]=Math.floor(Math.random()*256);
