    var bitLen=msg.length*8;
    msg+='\x80';
    while(msg.length%64!==56){msg+='\x00';}
    var hi=Math.floor(bitLen/Math.pow(2,32)),lo=bitLen>>>0;
    msg+=String.fromCharCode((hi>>>24)&255,(hi>>>16)&255,(hi>>>8)&255,hi&255,(lo>>>24)&255,(lo>>>16)&255,(lo>>>8)&255,lo&255);
    function rol(v,n){return ((v<<n)|(v>>>(32-n)))>>>0;}
    for(var off=0;off<msg.length;off+=64){
      var w=[],i,a,b,c,d,e,f,k,temp;
      for(i=0;i<16;i++){w[i]=((msg.charCodeAt(off+i*4)<<24)|(msg.charCodeAt(off+i*4+1)<<16)|(msg.charCodeAt(off+i*4+2)<<8)|msg.charCodeAt(off+i*4+3))>>>0;}
      for(i=16;i<80;i++){w[i]=rol(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);}
      a=H[0];b=H[1];c=H[2];d=H[3];e=H[4];
      for(i=0;i<80;i++){
        if(i<20){f=(b&c)|((~b)&d);k=0x5A827999;}
        else if(i<40){f=b^c^d;k=0x6ED9EBA1;}
        else if(i<60){f=(b&c)|(b&d)|(c&d);k=0x8F1BBCDC;}
        else{f=b^c^d;k=0xCA62C1D6;}
        temp=(rol(a,5)+f+e+k+w[i])>>>0;
        e=d;d=c;c=rol(b,30);b=a;a=temp;
      }
      H[0]=(H[0]+a)>>>0;H[1]=(H[1]+b)>>>0;H[2]=(H[2]+c)>>>0;H[3]=(H[3]+d)>>>0;H[4]=(H[4]+e)>>>0;
    }
    var out='';
    for(var q=0;q<5;q++){out+=('00000000'+H[q].toString(16)).slice(-8);}
    return out;
  }
  function uuidv5(nsUuid,name){
    var hexns=nsUuid.replace(/-/g,''),bytes='';
    for(var i=0;i<32;i+=2){bytes+=String.fromCharCode(parseInt(hexns.substr(i,2),16));}
    var h=sha1(bytes+utf8(name));
    var d=((parseInt(h.substr(16,2),16)&0x3f)|0x80).toString(16);
    d=(d.length<2?'0'+d:d)+h.substr(18,2);
    return h.substr(0,8)+'-'+h.substr(8,4)+'-5'+h.substr(13,3)+'-'+d+'-'+h.substr(20,12);
  }
  function gen(){
    var nm=nameEl.value;
    if(!nm){out.textContent='Type a name first.';return;}
    out.textContent=uuidv5(ns.value,nm);
  }
  document.getElementById('u5-gen').addEventListener('click',gen);
  document.getElementById('u5-copy').addEventListener('click',function(){
