(function(){
  var inp=document.getElementById('ot-in'),res=document.getElementById('ot-res');
  function ago(ts){
    var s=Math.floor(Date.now()/1000)-ts;
    if(s<0){return 'in the future';}
    if(s<60){return s+' seconds ago';}
    var m=Math.floor(s/60);
    if(m<60){return m+' minutes ago';}
    var h=Math.floor(m/60);
    if(h<48){return h+' hours ago';}
    var d=Math.floor(h/24);
    if(d<60){return d+' days ago';}
    var mo=Math.floor(d/30);
    if(mo<24){return mo+' months ago';}
    return Math.floor(mo/12)+' years ago';
  }
  function extract(){
    var v=inp.value.trim().toLowerCase();
    if(!/^[0-9a-f]{24}$/.test(v)){
      res.innerHTML='<div class="callout info">Enter a valid 24-character hex ObjectId, for example 507f1f77bcf86cd799439011.</div>';
      return;
    }
    var ts=parseInt(v.slice(0,8),16);
    var d=new Date(ts*1000);
    res.innerHTML='<div class="card result-card"><div class="result-label">Creation time</div>'+'<div class="output-box mono">'+v+'</div>'+'<p class="sub">UTC: <strong>'+d.toUTCString()+'</strong><br>Local: <strong>'+d.toString()+'</strong><br>Unix timestamp: <strong>'+ts+'</strong><br>Relative: <strong>'+ago(ts)+'</strong></p></div>';
  }
  document.getElementById('ot-go').addEventListener('click',extract);
  inp.addEventListener('input',extract);
})();

