  var FMT={DE:18,GB:18,FR:23,ES:20,IT:23,NL:14,BE:12};
  function ibanNum(s){var o='';for(var i=0;i<s.length;i++){var ch=s.charAt(i);o+=(ch>='A'&&ch<='Z')?(ch.charCodeAt(0)-55):ch;}return o;}
  function mod97(s){var r=0;for(var i=0;i<s.length;i++){r=(r*10+parseInt(s.charAt(i),10))%97;}return r;}
  function iban(c){
    var n=FMT[c],bban='',r=new Uint8Array(n),i;
    crypto.getRandomValues(r);
    for(i=0;i<n;i++){bban+=String(r[i]%10);}
