    var arr=s.split('');
    if(v&parseInt('4000',8)){arr[2]=arr[2]==='x'?'s':'S';}
    if(v&parseInt('2000',8)){arr[5]=arr[5]==='x'?'s':'S';}
    if(v&parseInt('1000',8)){arr[8]=arr[8]==='x'?'t':'T';}
    return arr.join('');
  }
  function fromBoxes(){
    var v=0,i;
    for(i=0;i<boxes.length;i++){if(boxes[i].checked){v+=parseInt(boxes[i].getAttribute('data-v'),8);}}
    oct.value=v.toString(8);
    render(v);
  }
  function fromOctal(){
    var v=parseInt(oct.value,8);
    if(isNaN(v)||v<0||v>parseInt('7777',8)){sym.textContent='-';cmd.textContent='-';return;}
    var i;
    for(i=0;i<boxes.length;i++){
      var bit=parseInt(boxes[i].getAttribute('data-v'),8);
      boxes[i].checked=(v&bit)===bit;
    }
    render(v);
  }
  function render(v){
    var o=v.toString(8);
    sym.textContent=toSymbolic(v);
    cmd.textContent='chmod '+o+' <file>';
  }
  var i;
  for(i=0;i<boxes.length;i++){boxes[i].addEventListener('change',fromBoxes);}
  oct.addEventListener('input',fromOctal);
  fromBoxes();
})();

(function(){
  var domain=document.getElementById('nx-domain'),
      root=document.getElementById('nx-root'),
      port=document.getElementById('nx-port'),
      ssl=document.getElementById('nx-ssl'),
      www=document.getElementById('nx-www'),
      php=document.getElementById('nx-php'),
      gzip=document.getElementById('nx-gzip'),
      sec=document.getElementById('nx-sec'),
      out=document.getElementById('nx-out');
  function build(){
    var d=(domain.value||'example.com').trim().replace(/^https?:\/\//,'').replace(/\/$/,'');
    var r=(root.value||'/var/www/html').trim();
    var p=parseInt(port.value,10)||80;
    var c='';
    if(www.checked){
      c+='server {\n    listen '+p+';\n    server_name www.'+d+';\n    return 301 http'+(ssl.checked?'s':'')+'://'+d+'$request_uri;\n}\n\n';
    }
    c+='server {\n';
    c+='    listen '+p+(ssl.checked?'':' default_server')+';\n';
    if(ssl.checked){
      c+='    listen 443 ssl;\n';
      c+='    ssl_certificate /etc/letsencrypt/live/'+d+'/fullchain.pem;\n';
      c+='    ssl_certificate_key /etc/letsencrypt/live/'+d+'/privkey.pem;\n';
    }
    c+='    server_name '+d+';\n\n';
    c+='    root '+r+';\n';
    c+='    index index.html index.htm'+(php.checked?' index.php':'')+';\n\n';
    c+='    location / {\n        try_files $uri $uri/ =404;\n    }\n\n';
    if(php.checked){
      c+='    location ~ \\.php$ {\n        include snippets/fastcgi-php.conf;\n        fastcgi_pass unix:/run/php/php8.2-fpm.sock;\n    }\n\n';
    }
    c+='    location ~ /\\.ht {\n        deny all;\n    }\n';
    if(gzip.checked){
      c+='\n    gzip on;\n    gzip_types text/plain text/css application/json application/javascript text/xml;\n';
    }
    if(sec.checked){
      c+='\n    add_header X-Frame-Options "SAMEORIGIN" always;\n    add_header X-Content-Type-Options "nosniff" always;\n    add_header Referrer-Policy "strict-origin-when-cross-origin" always;\n';
    }
    c+='}';
    out.textContent=c;
  }
  var els=[domain,root,port,ssl,www,php,gzip,sec];
  for(var i=0;i<els.length;i++){els[i].addEventListener('input',build);els[i].addEventListener('change',build);}
  document.getElementById('nx-copy').addEventListener('click',function(){
    if(navigator.clipboard){navigator.clipboard.writeText(out.textContent);}
  });
  build();
})();

(function(){
  function val(id){return document.getElementById(id).value.trim();}
  function spf(){
    var parts=['v=spf1'];
    if(document.getElementById('dns-spf-a').checked){parts.push('a');}
    if(document.getElementById('dns-spf-mx').checked){parts.push('mx');}
    var ip=val('dns-spf-ip');
    if(ip){parts.push('ip4:'+ip);}
    var inc=val('dns-spf-inc');
    if(inc){
      var arr=inc.split(','),i;
      for(i=0;i<arr.length;i++){var s=arr[i].trim();if(s){parts.push('include:'+s);}}
    }
    parts.push(val('dns-spf-all')||'-all');
    document.getElementById('dns-spf-out').textContent=parts.join(' ');
  }
  function dkim(){
    var sel=val('dns-dkim-sel')||'selector1';
    var key=(document.getElementById('dns-dkim-key').value||'').replace(/-----[A-Z ]+-----/g,'').replace(/\s+/g,'');
    var host=sel+'._domainkey';
    document.getElementById('dns-dkim-host').textContent=host;
    document.getElementById('dns-dkim-out').textContent='v=DKIM1; k=rsa; p='+key;
  }
  function dmarc(){
    var dom=val('dns-domain')||'example.com';
    var parts=['v=DMARC1'];
    parts.push('p='+document.getElementById('dns-dm-ppol').value);
    var sp=document.getElementById('dns-dm-sp').value;
    if(sp){parts.push('sp='+sp);}
    var pct=val('dns-dm-pct');
    if(pct){parts.push('pct='+pct);}
    var rua=val('dns-dm-rua');
    if(rua){parts.push('rua=mailto:'+rua);}
    var ruf=val('dns-dm-ruf');
    if(ruf){parts.push('ruf=mailto:'+ruf);}
    var adkim=document.getElementById('dns-dm-adkim').value;
    if(adkim){parts.push('adkim='+adkim);}
    var aspf=document.getElementById('dns-dm-aspf').value;
    if(aspf){parts.push('aspf='+aspf);}
    document.getElementById('dns-dm-host').textContent='_dmarc.'+dom;
    document.getElementById('dns-dm-out').textContent=parts.join('; ')+';';
  }
  function all(){spf();dkim();dmarc();}
  var ids=['dns-domain','dns-spf-a','dns-spf-mx','dns-spf-ip','dns-spf-inc','dns-spf-all','dns-dkim-sel','dns-dkim-key','dns-dm-ppol','dns-dm-sp','dns-dm-pct','dns-dm-rua','dns-dm-ruf','dns-dm-adkim','dns-dm-aspf'];
  for(var i=0;i<ids.length;i++){
    var el=document.getElementById(ids[i]);
    el.addEventListener('input',all);
    el.addEventListener('change',all);
  }
  all();
})();

(function(){
  var zone=document.getElementById('mp-zone');
  var cur=document.getElementById('mp-cur'),
      avg=document.getElementById('mp-avg'),
      mx=document.getElementById('mp-max'),
      cnt=document.getElementById('mp-count');
  var times=[],total=0,max=0,running=false,start=0;
  zone.addEventListener('mousemove',function(){
    if(!running){return;}
    times.push(performance.now());
    total++;
  });
  setInterval(function(){
    if(!running){return;}
    var now=performance.now();
    while(times.length&&times[0]<now-1000){times.shift();}
    var hz=times.length;
    if(hz>max){max=hz;}
    cur.textContent=hz+' Hz';
    mx.textContent=max+' Hz';
    cnt.textContent=total;
    var secs=(now-start)/1000;
    avg.textContent=secs>0?Math.round(total/secs)+' Hz':'0 Hz';
  },250);
  document.getElementById('mp-start').addEventListener('click',function(){
    times=[];total=0;max=0;running=true;start=performance.now();
    this.textContent='Restart test';
    zone.querySelector('.mp-hint').textContent='Move your mouse fast inside this box.';
  });
})();

