(function(){
  var ctx=null,osc=null;
  var freq=document.getElementById('sp-freq'),
      fv=document.getElementById('sp-freq-v'),
      status=document.getElementById('sp-status');
  function stop(){
    if(osc){try{osc.stop();}catch(e){}osc=null;}
  }
  function play(pan){
    stop();
    var AC=window.AudioContext||window.webkitAudioContext;
    if(!AC){status.textContent='Web Audio is not supported in this browser.';return;}
    ctx=ctx||new AC();
    if(ctx.state==='suspended'){ctx.resume();}
    var o=ctx.createOscillator(),g=ctx.createGain();
    o.type='sine';
    o.frequency.value=parseInt(freq.value,10)||440;
    g.gain.value=0.5;
    if(ctx.createStereoPanner){
      var p=ctx.createStereoPanner();
      p.pan.value=pan;
      o.connect(g);g.connect(p);p.connect(ctx.destination);
    }else{
      o.connect(g);g.connect(ctx.destination);
    }
    o.start();
    osc=o;
    status.textContent='Playing '+(pan<0?'left':(pan>0?'right':'center'))+' channel at '+o.frequency.value+' Hz. Stops automatically after 3 seconds.';
    setTimeout(stop,3000);
  }
  freq.addEventListener('input',function(){fv.textContent=freq.value+' Hz';});
  document.getElementById('sp-left').addEventListener('click',function(){play(-1);});
  document.getElementById('sp-right').addEventListener('click',function(){play(1);});
  document.getElementById('sp-center').addEventListener('click',function(){play(0);});
  document.getElementById('sp-stop').addEventListener('click',function(){stop();status.textContent='Stopped.';});
})();

(function(){
  var polling=false,raf=null;
  var status=document.getElementById('gp-status');
  var padsEl=document.getElementById('gp-pads');
  function render(){
    var pads=[],i;
    try{
      var raw=navigator.getGamepads?navigator.getGamepads():[];
      for(i=0;i<raw.length;i++){if(raw[i]){pads.push(raw[i]);}}
    }catch(e){}
    if(!pads.length){
      padsEl.innerHTML='<div class="callout info">No gamepad detected. Connect one and press any button.</div>';
      return;
    }
    var html='',p,b,a;
    for(p=0;p<pads.length;p++){
      var gp=pads[p];
      html+='<div class="card" style="margin-bottom:.75rem"><p class="sub"><strong>'+gp.id+'</strong></p><div class="gp-btns">';
      for(b=0;b<gp.buttons.length;b++){
        html+='<span class="gp-btn'+(gp.buttons[b].pressed?' on':'')+'">'+b+'</span>';
      }
      html+='</div><p class="sub mono">';
      for(a=0;a<gp.axes.length;a++){html+='A'+a+'='+gp.axes[a].toFixed(2)+'  ';}
      html+='</p></div>';
    }
    padsEl.innerHTML=html;
  }
  function loop(){
    if(!polling){return;}
    render();
    raf=requestAnimationFrame(loop);
  }
  document.getElementById('gp-start').addEventListener('click',function(){
    if(polling){
      polling=false;
      if(raf){cancelAnimationFrame(raf);}
      this.textContent='Start polling';
      status.textContent='Polling stopped.';
      return;
    }
    polling=true;
    this.textContent='Stop polling';
    status.textContent='Polling. Press buttons on your gamepad.';
    loop();
  });
  window.addEventListener('gamepadconnected',function(e){status.textContent='Gamepad connected: '+e.gamepad.id;});
  window.addEventListener('gamepaddisconnected',function(){status.textContent='Gamepad disconnected.';});
  render();
})();

