  function transform(s){
    var desc=document.getElementById("sortnum-order").value==="desc";
    function num(l){var m=l.match(/-?\d[\d,]*(?:\.\d+)?/);return m?parseFloat(m[0].replace(/,/g,"")):null;}
    var rows=s.split("\n").map(function(l,i){return{line:l,i:i,n:num(l)};});
    rows.sort(function(a,b){
      if(a.n===null&&b.n===null)return a.i-b.i;
