function sim(debts,extra){
var ds=debts.map(function(d){return{bal:d.bal,r:d.rate/100/12,min:d.min};});
var interest=0,months=0,freed=0;
while(months<1200){
var act=ds.filter(function(d){return d.bal>0.01;});
if(!act.length)break;
months++;
act.forEach(function(d){var i=d.bal*d.r;d.bal+=i;interest+=i;});
act.forEach(function(d){d.bal=Math.max(0,d.bal-Math.min(d.min,d.bal));});
var pool=extra+freed;
for(var k=0;k<ds.length&&pool>0.005;k++){if(ds[k].bal>0.01){var p=Math.min(pool,ds[k].bal);ds[k].bal-=p;pool-=p;}}
freed=0;
ds.forEach(function(d){if(d.bal<=0.01&&d.min>0){freed+=d.min;d.min=0;}});
}
return{months:months,interest:interest,stuck:months>=1200};
}
function fmtM(m){if(m>=1200)return"100+ yrs";var y=Math.floor(m/12),r=m%12;return y>0?(y+"y "+r+"m"):m+" mo";}
