var ds=[{bal:v("ds-b1"),rate:v("ds-r1"),min:v("ds-m1")},{bal:v("ds-b2"),rate:v("ds-r2"),min:v("ds-m2")}].filter(function(d){return isFinite(d.bal)&&d.bal>0&&isFinite(d.min)&&d.min>0;});
