  var btn=document.getElementById("mt-btn"),dots=document.getElementById("mt-dots");
  var ctx=null,timer=null,nextTime=0,beat=0,running=false;
  function renderDots(){
    var n=parseInt(beatsSel.value,10);dots.innerHTML="";
    for(var i=0;i<n;i++){var s=document.createElement("span");s.className="mt-dot";s.id="mt-dot-"+i;dots.appendChild(s);}
    beat=0;
  }
  function click(t,accent){
    var o=ctx.createOscillator(),g=ctx.createGain();
    o.type="sine";o.frequency.value=accent?1500:1000;
    var v=0.0001+0.5*(parseInt(vol.value,10)/100);
    g.gain.setValueAtTime(0.0001,t);
    g.gain.exponentialRampToValueAtTime(v,t+0.003);
    g.gain.exponentialRampToValueAtTime(0.0001,t+0.07);
    o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+0.09);
  }
  function schedule(){
    var iv=60/parseInt(bpm.value,10),n=parseInt(beatsSel.value,10);
    while(nextTime<ctx.currentTime+0.15){
      click(nextTime,beat===0);
      (function(b,delay,n2){
        setTimeout(function(){
          for(var k=0;k<n2;k++){var d=document.getElementById("mt-dot-"+k);if(d)d.classList.toggle("on",k===b);}
        },delay);
      })(beat,Math.max(0,(nextTime-ctx.currentTime)*1000),n);
      nextTime+=iv;beat=(beat+1)%n;
    }
    timer=setTimeout(schedule,25);
  }
  function start(){
    var AC=window.AudioContext||window.webkitAudioContext;
    if(!AC){alert("Web Audio is not supported in this browser.");return;}
