(function(){
  var taps=[];
  function set(id,t){var e=document.getElementById(id);if(e)e.textContent=t;}
  function update(){
    set("tp-count","Taps: "+taps.length);
    if(taps.length<2){set("tp-out","-");set("tp-note","Tap the button to start measuring.");return;}
    var iv=[];
    for(var i=1;i<taps.length;i++)iv.push(taps[i]-taps[i-1]);
    iv.sort(function(a,b){return a-b;});
    var mid=iv[Math.floor(iv.length/2)];
    var near=iv.filter(function(x){return Math.abs(x-mid)<mid*0.35;});
    var use=near.length>=2?near:iv;
    var avg=use.reduce(function(a,b){return a+b;},0)/use.length;
    var bpm=60000/avg;
    set("tp-out",Math.round(bpm)+" BPM");
    set("tp-note","Average interval "+Math.round(avg)+" ms over "+use.length+" steady taps. Tap more for a steadier reading.");
  }
  document.getElementById("tp-tap").addEventListener("click",function(){
    var now=performance.now();
    if(taps.length&&now-taps[taps.length-1]>3000)taps=[];
    taps.push(now);
    if(taps.length>32)taps.shift();
    update();
  });
  document.getElementById("tp-reset").addEventListener("click",function(){taps=[];update();});
  update();
})();

