(function(){
  var RANGES=[[1,15],[16,30],[31,45],[46,60],[61,75]];
  var HEADERS=["B","I","N","G","O"];
  function pick(lo,hi,n){
    var pool=[];
    for(var x=lo;x<=hi;x++)pool.push(x);
    var out=[];
    for(var i=0;i<n;i++){out.push(pool.splice(Math.floor(Math.random()*pool.length),1)[0]);}
    return out.sort(function(a,b){return a-b;});
  }
  function render(){
    var cols=RANGES.map(function(r){return pick(r[0],r[1],5);});
    var h='<div class="bg-grid">';
    HEADERS.forEach(function(H){h+='<div class="bg-head">'+H+'</div>';});
    for(var r=0;r<5;r++){
      for(var c=0;c<5;c++){
        if(r===2&&c===2)h+='<div class="bg-cell bg-free">FREE</div>';
        else h+='<div class="bg-cell">'+cols[c][r]+'</div>';
      }
    }
    h+='</div>';
    document.getElementById("bg-card").innerHTML=h;
  }
  document.getElementById("bg-gen").addEventListener("click",render);
  document.getElementById("bg-print").addEventListener("click",function(){window.print();});
  render();
})();

