(function(){
function el(id){return document.getElementById(id);}
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function inline(s){
  s=esc(s);
  s=s.replace(/`([^`]+)`/g,'<code>$1<\/code>');
  s=s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1<\/strong>');
  s=s.replace(/\*([^*]+)\*/g,'<em>$1<\/em>');
  s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2">$1<\/a>');
  return s;
}
function md(src){
  var lines=src.split('\n'),html='',i=0,list=null;
  function closeList(){if(list){html+='<\/'+list+'>';list=null;}}
  while(i<lines.length){
    var ln=lines[i];
    if(/^\s*$/.test(ln)){closeList();i++;continue;}
    var h=ln.match(/^(#{1,6})\s+(.*)/);
    if(h){closeList();var lv=h[1].length;html+='<h'+lv+'>'+inline(h[2])+'<\/h'+lv+'>';i++;continue;}
    if(/^---+$/.test(ln.trim())){closeList();html+='<hr>';i++;continue;}
    var bqm=ln.match(/^>\s?(.*)/);
    if(bqm){closeList();html+='<blockquote>'+inline(bqm[1])+'<\/blockquote>';i++;continue;}
    var ul=ln.match(/^\s*[-*]\s+(.*)/);
    if(ul){if(list!=='ul'){closeList();html+='<ul>';list='ul';}html+='<li>'+inline(ul[1])+'<\/li>';i++;continue;}
    var ol=ln.match(/^\s*\d+\.\s+(.*)/);
    if(ol){if(list!=='ol'){closeList();html+='<ol>';list='ol';}html+='<li>'+inline(ol[1])+'<\/li>';i++;continue;}
    closeList();html+='<p>'+inline(ln)+'<\/p>';i++;
  }
  closeList();return html;
}
