  osc.connect(g);g.connect(c.destination);osc.start();osc.stop(c.currentTime+1.6);
}
function render(){
  var box=el('ht-list');box.innerHTML='';
  FREQS.forEach(function(f){
    var row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:8px;padding:10px 0;border-bottom:1px solid var(--line);flex-wrap:wrap;';
    var lab=document.createElement('strong');lab.textContent=f+' Hz';lab.style.minWidth='70px';
    var play=document.createElement('button');play.className='btn btn-outline btn-sm';play.type='button';play.textContent='Play';
    play.addEventListener('click',function(){tone(f);});
    var yes=document.createElement('button');yes.className='btn btn-sm '+(ans[f]===true?'btn-primary':'btn-outline');yes.type='button';yes.textContent='I hear it';
    var no=document.createElement('button');no.className='btn btn-sm '+(ans[f]===false?'btn-primary':'btn-outline');no.type='button';no.textContent="I don't";
    yes.addEventListener('click',function(){ans[f]=true;render();summary();});
