  var keys=Object.keys(ans);
  if(keys.length<FREQS.length){el('ht-note').textContent='Answered '+keys.length+' of 6. Keep going.';return;}
  var heard=FREQS.filter(function(f){return ans[f];});
  var missed=FREQS.filter(function(f){return !ans[f];});
  var html='<strong>You heard '+heard.length+' of 6 tones.</strong><br><br>';
  html+='Heard: '+(heard.length?heard.join(' Hz, ')+' Hz':'none')+'<br>';
  html+='Missed: '+(missed.length?missed.join(' Hz, ')+' Hz':'none')+'<br><br>';
  if(missed.length===0)html+='You heard the full tested range. Nice.';
  else if(missed.indexOf(8000)>=0&&missed.length<=2)html+='Missing only the highest tones is common with age and not alarming on its own.';
  else html+='You missed several tones. Consider a professional hearing check, especially if you struggle in conversations.';
  html+='<br><br><span class="sub">Rough self-check, not a diagnosis.</span>';
  el('ht-out').innerHTML=html;
  el('ht-note').textContent='Test complete.';
}
