var ROWS={ '1':697,'2':697,'3':697,'A':697, '4':770,'5':770,'6':770,'B':770, '7':852,'8':852,'9':852,'C':852, '*':941,'0':941,'#':941,'D':941 };
var COLS={ '1':1209,'2':1336,'3':1477,'A':1633, '4':1209,'5':1336,'6':1477,'B':1633, '7':1209,'8':1336,'9':1477,'C':1633, '*':1209,'0':1336,'#':1477,'D':1633 };
var KEYS=['1','2','3','4','5','6','7','8','9','*','0','#'];
function tone(key,dur){
  dur=dur||0.22;
  var f1=ROWS[key],f2=COLS[key];
  if(!f1)return;
  var c=ac(),t=c.currentTime;
  [f1,f2].forEach(function(f){
    var o=c.createOscillator(),g=c.createGain();
    o.type='sine';o.frequency.value=f;
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(0.3,t+0.01);
    g.gain.setValueAtTime(0.3,t+dur-0.02);g.gain.linearRampToValueAtTime(0,t+dur);
    o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+dur+0.03);
  });
  el('dt-k').textContent=key;
  el('dt-f').textContent=f1+' + '+f2+' Hz';
  el('dt-note').textContent='Played key '+key+'.';
}
var box=el('dt-keys');
