  el('dt-note').textContent='Dialing '+seq.length+' keys...';
  var i=0;
  function next(){
    if(i>=seq.length){el('dt-note').textContent='Done dialing.';return;}
    tone(seq[i]);i++;
    setTimeout(next,320);
  }
  next();
});
