function phase(t){
  var c=ac(),o=c.createOscillator(),g=c.createGain();
  o.type='sine';o.frequency.value=t.f0;
  o.frequency.exponentialRampToValueAtTime(t.f1,c.currentTime+t.dur);
  g.gain.setValueAtTime(0.0001,c.currentTime);
  g.gain.exponentialRampToValueAtTime(0.9,c.currentTime+0.3);
  g.gain.setValueAtTime(0.9,c.currentTime+t.dur-0.3);
  g.gain.exponentialRampToValueAtTime(0.0001,c.currentTime+t.dur);
  o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+t.dur+0.05);
  nodes.push({osc:o});
}
