    var p=(Date.now()-t0)/DUR;
    el('sw-fill').style.width=Math.min(100,p*100)+'%';
    if(p>=1){stop();el('sw-note').textContent='Cycle complete. Wipe the speaker and repeat if sound is still muffled.';el('sw-step').textContent='Phase: done';return;}
    raf=requestAnimationFrame(loop);
  }
