function parseTime(s){
  s=s.trim();
  if(/^\d+$/.test(s)){return parseInt(s,10);}
  var parts=s.split(':').map(function(x){return parseInt(x,10);});
  if(parts.some(isNaN)){return null;}
  var total=0;
  for(var i=0;i<parts.length;i++){total=total*60+parts[i];}
  return total;
}
