(function(){
var out=document.getElementById('as-out');
function row(k,v){return '<div class="ar-row"><span>'+k+'</span><strong class="mono">'+v+'</strong></div>';}
function render(d,cached){
  var html=row('IP',d.ip||'-')+row('ASN','AS'+(d.asn||'-'))+row('Organization',d.org||'-')+
    row('ISP',d.isp||'-')+row('City',d.city||'-')+row('Region',d.region||'-')+
    row('Country',(d.country_name||'-')+' ('+(d.country_code||'-')+')')+
    row('Location',(d.latitude||'-')+', '+(d.longitude||'-'))+
    row('Timezone',d.timezone||'-');
  if(cached){html+='<p class="sub">Served from 24-hour browser cache.</p>';}
  out.innerHTML=html;
}
function lookup(ip){
  var key='c15_asn_'+(ip||'self');
  try{
    var c=JSON.parse(localStorage.getItem(key)||'null');
    if(c&&Date.now()-c.t<86400000){render(c.d,true);return;}
  }catch(e){}
  out.innerHTML='<p class="sub">Looking up...</p>';
  fetch('https://ipapi.co/'+(ip?encodeURIComponent(ip)+'/':'')+'json/').then(function(r){
    if(!r.ok){throw new Error('bad response');}
    return r.json();
  }).then(function(d){
    if(d.error){throw new Error(d.reason||'lookup failed');}
    try{localStorage.setItem(key,JSON.stringify({t:Date.now(),d:d}));}catch(e){}
    render(d,false);
  }).catch(function(){
    out.innerHTML='<p class="sub">Lookup failed. The IP may be invalid, or the free API limit was reached. Try again later.</p>';
  });
}
