  var ip=document.getElementById('as-ip').value.trim();
  if(ip&&!/^(\d{1,3}\.){3}\d{1,3}$/.test(ip)){out.innerHTML='<p class="sub">That does not look like a valid IPv4 address.</p>';return;}
  lookup(ip);
});
})();

