(function(){
var out=document.getElementById('dn-out');
function lookup(){
  var domain=document.getElementById('dn-domain').value.trim().toLowerCase().replace(/^https?:\/\//,'').replace(/\/.*$/,''),
      type=document.getElementById('dn-type').value;
  if(!domain||domain.indexOf('.')<0){out.innerHTML='<p class="sub">Enter a valid domain like example.com.</p>';return;}
  out.innerHTML='<p class="sub">Querying '+type+' records for '+domain+'...</p>';
  fetch('https://cloudflare-dns.com/dns-query?name='+encodeURIComponent(domain)+'&type='+type,{
    headers:{'Accept':'application/dns-json'}
  }).then(function(r){
    if(!r.ok){throw new Error('bad response');}
    return r.json();
  }).then(function(d){
    if(!d.Answer||!d.Answer.length){out.innerHTML='<p class="sub">No '+type+' records found for '+domain+'. The domain may not publish this record type.</p>';return;}
    var html='';
    d.Answer.forEach(function(a){
      var val=a.data.replace(/^"|"$/g,'');
      if(type==='MX'){var parts=val.split(' ');val='priority '+parts[0]+' -> '+parts.slice(1).join(' ');}
      html+='<div class="ar-row"><span class="mono">'+type+'</span><strong class="mono">'+val+'</strong></div>';
    });
    html+='<p class="sub">'+d.Answer.length+' record(s) returned via DNS over HTTPS.</p>';
    out.innerHTML=html;
  }).catch(function(){
    out.innerHTML='<p class="sub">DNS query failed. Check the domain spelling and your connection, then retry.</p>';
  });
}
document.getElementById('dn-go').addEventListener('click',lookup);
document.getElementById('dn-domain').addEventListener('keydown',function(e){if(e.key==='Enter'){lookup();}});
})();

(function(){
  var FROM="USD",TO="EUR";
  var API="/api/rates?from="+encodeURIComponent(FROM)+"&to="+encodeURIComponent(TO);
  var KEY="mth-fx-"+FROM+"-"+TO;
  var TTL=6*60*60*1000;
  function $(id){return document.getElementById(id);}
  function v(id){var e=$(id);var n=parseFloat(e&&e.value);return isFinite(n)?n:NaN;}
  function setT(id,t){var e=$(id);if(e)e.textContent=t;}
  function fmt(n){if(!isFinite(n))return "-";return n.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});}
  function fmtR(n){if(!isFinite(n))return "-";if(n>=1000)return n.toLocaleString("en-US",{maximumFractionDigits:2});return n.toLocaleString("en-US",{minimumFractionDigits:4,maximumFractionDigits:4});}
  function pad(n){return (n<10?"0":"")+n;}
  function stamp(ts){var d=new Date(ts);return pad(d.getHours())+":"+pad(d.getMinutes());}
  var rate=null;
  function render(){
    var amt=v("fx-amt");
    if(rate==null){setT("fx-out","-");setT("fx-rate-line","1 "+FROM+" = - "+TO);return;}
    setT("fx-out",isFinite(amt)?fmt(amt*rate)+" "+TO:"-");
    setT("fx-rate-line","1 "+FROM+" = "+fmtR(rate)+" "+TO);
  }
  function showError(){
    rate=null;render();
    setT("fx-note","Live rates unavailable. Check your connection and try again.");
    setT("fx-updated","-");
  }
  function applyRate(r,label){
    rate=r;
    setT("fx-note","Mid-market rate. Your bank or transfer service will quote a slightly different retail rate.");
    setT("fx-updated",label);
    render();
  }
  function load(){
    var cached=null;
    try{cached=JSON.parse(localStorage.getItem(KEY)||"null");}catch(err){}
    if(cached&&isFinite(cached.rate)&&Date.now()-cached.ts<TTL){applyRate(cached.rate,"Cached "+stamp(cached.ts));return;}
    fetch(API).then(function(res){if(!res.ok)throw new Error("bad");return res.json();}).then(function(data){
      var r=data&&data.rates&&data.rates[TO];
      if(!isFinite(r))throw new Error("bad");
      try{localStorage.setItem(KEY,JSON.stringify({rate:r,ts:Date.now()}));}catch(err){}
      applyRate(r,"Live "+stamp(Date.now()));
    }).catch(showError);
  }
  var amt=$("fx-amt");if(amt)amt.addEventListener("input",render);
  load();
})();

