(function(){
  var from='JPY', to='EUR';
  var key='fx_'+from+'_'+to;
  var rate=null;
  var amountInput=document.getElementById('cc-amount');
  var resultEl=document.getElementById('cc-result');
  var rateEl=document.getElementById('cc-rate');
  var noteEl=document.getElementById('cc-note');
  function fmt(n){ return Number(n).toLocaleString('en-US',{maximumFractionDigits:2}); }
  function convert(){
    var amt=parseFloat(amountInput.value);
    if(!isFinite(amt)||amt<0){ resultEl.textContent='Enter an amount to convert.'; return; }
    if(rate===null){ resultEl.textContent='Loading rate...'; return; }
    resultEl.textContent=fmt(amt)+' '+from+' = '+fmt(amt*rate)+' '+to;
  }
  function showRate(){ if(rate!==null){ rateEl.textContent='1 '+from+' = '+rate+' '+to; } }
  function stamp(ts){
    var d=new Date(ts);
    var hh=('0'+d.getHours()).slice(-2), mm=('0'+d.getMinutes()).slice(-2);
    noteEl.textContent='Rates updated '+hh+':'+mm+'. Powered by frankfurter.app (ECB reference rates).';
  }
  function load(){
    var cached=null;
    try{ cached=JSON.parse(localStorage.getItem(key)); }catch(e){}
    if(cached&&cached.rate&&(Date.now()-cached.ts)<6*3600*1000){ rate=cached.rate; showRate(); stamp(cached.ts); convert(); return; }
    noteEl.textContent='Fetching live rate...';
    fetch('/api/rates?from='+from+'&to='+to)
      .then(function(r){ if(!r.ok){ throw new Error('bad'); } return r.json(); })
      .then(function(data){
        if(!data.rates||!data.rates[to]){ throw new Error('no rate'); }
        rate=data.rates[to];
        var ts=Date.now();
        try{ localStorage.setItem(key,JSON.stringify({rate:rate,ts:ts})); }catch(e){}
        showRate(); stamp(ts); convert();
      })
      .catch(function(){
        noteEl.textContent='Live rates unavailable. Check your connection and try again.';
        resultEl.textContent='Could not load the '+from+' to '+to+' rate.';
      });
  }
  amountInput.addEventListener('input',convert);
  load();
})();

