(function(){
'use strict';
function gid(id){return document.getElementById(id);}
function err(m){var e=gid('d2p-error');e.style.display='block';gid('d2p-errmsg').textContent=m;}
function ok(s){gid('d2p-error').style.display='none';gid('d2p-status').textContent=s;}
gid('d2p-file').addEventListener('change',function(){
  var f=this.files[0];gid('d2p-dl').style.display='none';
  if(f)ok('Ready: '+f.name+' ('+Math.round(f.size/1024)+' KB). Click Convert to PDF.');
  else ok('No file selected.');
});
gid('d2p-go').addEventListener('click',function(){
  var f=gid('d2p-file').files[0];
  if(!f){err('Choose a .docx file first.');return;}
  if(typeof JSZip==='undefined'||typeof PDFLib==='undefined'){err('Libraries failed to load. Check your connection and retry.');return;}
  ok('Reading document...');
  var reader=new FileReader();
  reader.onload=function(){
    JSZip.loadAsync(reader.result).then(function(zip){
      var docFile=zip.file('word/document.xml');
      if(!docFile)throw new Error('word/document.xml was not found in this file.');
      return docFile.async('string');
    }).then(function(xmlText){
      var doc=new DOMParser().parseFromString(xmlText,'application/xml');
      var paras=doc.getElementsByTagName('w:p'),lines=[];
      if(paras.length){
        for(var i=0;i<paras.length;i++){
          var ts=paras[i].getElementsByTagName('w:t'),s='';
          for(var j=0;j<ts.length;j++)s+=ts[j].textContent;
          lines.push(s);
        }
      }else{
        var all=doc.getElementsByTagName('*'),s2='';
        for(var k=0;k<all.length;k++){if(all[k].localName==='t')s2+=all[k].textContent;}
        lines=s2.split('\n');
      }
      return lines;
    }).then(function(lines){
      ok('Building PDF...');
      return PDFLib.PDFDocument.create().then(function(p){
        return p.embedStandardFont(PDFLib.StandardFonts.Helvetica).then(function(font){
          var W=595.28,H=841.89,margin=56,y=H-margin,size=11,lh=15,maxW=W-2*margin,page=p.addPage([W,H]);
          function wrap(line){
            var ws=String(line).split(/\s+/),cur='',out=[];
            ws.forEach(function(w){var t=cur?cur+' '+w:w;
              if(font.widthOfTextAtSize(t,size)>maxW){if(cur)out.push(cur);cur=w;}else cur=t;});
            if(cur)out.push(cur);if(!out.length)out.push('');return out;
          }
          lines.forEach(function(line){
            wrap(line).forEach(function(wl){
              if(y<margin+lh){page=p.addPage([W,H]);y=H-margin;}
              page.drawText(wl,{x:margin,y:y,size:size,font:font});
              y-=lh;
            });
          });
          return p.save();
        });
      });
    }).then(function(bytes){
      var blob=new Blob([bytes],{type:'application/pdf'});
      var a=gid('d2p-dl');a.href=URL.createObjectURL(blob);a.style.display='inline-block';
      ok('Done. Click Download PDF to save it.');
    }).catch(function(ex){err(ex&&ex.message?ex.message:String(ex));});
  };
  reader.readAsArrayBuffer(f);
});
})();

(function(){
'use strict';
function gid(id){return document.getElementById(id);}
function err(m){var e=gid('pmv-error');e.style.display='block';gid('pmv-errmsg').textContent=m;}
function row(tbody,k,v){
  var tr=document.createElement('tr');
  var td1=document.createElement('td');td1.textContent=k;
  var td2=document.createElement('td');td2.textContent=(v===undefined||v===null||v==='')?'(not set)':String(v);
  tr.appendChild(td1);tr.appendChild(td2);tbody.appendChild(tr);
}
gid('pmv-file').addEventListener('change',function(){
  var f=this.files[0];
  gid('pmv-result-card').style.display='none';
  gid('pmv-status').textContent=f?('Ready: '+f.name):'No file selected.';
});
gid('pmv-go').addEventListener('click',function(){
  var f=gid('pmv-file').files[0];
  if(!f){err('Choose a PDF file first.');return;}
  if(typeof PDFLib==='undefined'){err('PDF library failed to load. Check your connection and retry.');return;}
  gid('pmv-status').textContent='Reading...';
  var reader=new FileReader();
  reader.onload=function(){
    PDFLib.PDFDocument.load(reader.result).then(function(pdf){
      var tb=gid('pmv-table').querySelector('tbody');tb.innerHTML='';
      function fmtDate(d){
        if(!d)return undefined;
        if(d instanceof Date)return d.toLocaleString();
        return String(d);
      }
      row(tb,'File name',f.name);
      row(tb,'File size',(f.size/1024).toFixed(1)+' KB');
      row(tb,'Pages',pdf.getPageCount());
      row(tb,'Title',pdf.getTitle());
      row(tb,'Author',pdf.getAuthor());
      row(tb,'Subject',pdf.getSubject());
      var kw=pdf.getKeywords();row(tb,'Keywords',Array.isArray(kw)?kw.join(', '):kw);
      row(tb,'Creator',pdf.getCreator());
      row(tb,'Producer',pdf.getProducer());
      row(tb,'Created',fmtDate(pdf.getCreationDate()));
      row(tb,'Modified',fmtDate(pdf.getModificationDate()));
      gid('pmv-filename').textContent=f.name;
      gid('pmv-result-card').style.display='block';
      gid('pmv-error').style.display='none';
      gid('pmv-status').textContent='Done.';
    }).catch(function(ex){err(ex&&ex.message?ex.message:String(ex));});
  };
  reader.readAsArrayBuffer(f);
});
})();

(function(){
'use strict';
function gid(id){return document.getElementById(id);}
function err(m){var e=gid('ps-error');e.style.display='block';gid('ps-errmsg').textContent=m;}
function ok(s){gid('ps-error').style.display='none';gid('ps-status').textContent=s;}
var pageCount=0;
gid('ps-file').addEventListener('change',function(){
  var f=this.files[0];
  gid('ps-out-card').style.display='none';
  if(!f){ok('No file selected.');pageCount=0;return;}
  if(typeof PDFLib==='undefined'){err('PDF library failed to load.');return;}
  ok('Reading '+f.name+'...');
  var r=new FileReader();
  r.onload=function(){
    PDFLib.PDFDocument.load(r.result).then(function(pdf){
      pageCount=pdf.getPageCount();
      ok(f.name+' loaded: '+pageCount+' pages. Enter ranges like 1-3, 5.');
    }).catch(function(ex){err(ex&&ex.message?ex.message:String(ex));});
  };
  r.readAsArrayBuffer(f);
});
function parseRanges(text,n){
  var parts=text.split(','),out=[];
  for(var i=0;i<parts.length;i++){
    var p=parts[i].trim();if(!p)continue;
    var m=p.match(/^(\d+)\s*-\s*(\d+)$/);
    if(m){
      var a=parseInt(m[1],10),b=parseInt(m[2],10);
      if(a<1||b>n||a>b)return{error:'Range "'+p+'" is invalid for a '+n+'-page PDF.'};
      var arr=[];for(var k=a;k<=b;k++)arr.push(k-1);out.push(arr);
    }else if(/^\d+$/.test(p)){
      var pg=parseInt(p,10);
      if(pg<1||pg>n)return{error:'Page '+p+' is out of range (1-'+n+').'};
      out.push([pg-1]);
    }else return{error:'Could not understand "'+p+'". Use formats like 1-3 or 5.'};
  }
  return{ranges:out};
}
