(function(){
'use strict';
function gid(id){return document.getElementById(id);}
var PASSAGES=[
'The quick brown fox jumps over the lazy dog while the river flows quietly beneath the old wooden bridge at dawn.',
'Good typing comes from steady rhythm, not speed. Keep your fingers on the home row and let accuracy lead the way forward.',
'Every expert was once a beginner. Small daily practice builds muscle memory faster than occasional long sessions ever will.',
'Rain tapped the window as the kettle whistled. She poured the tea, opened her notebook, and started writing without pause.',
'Technology changes fast, but clear thinking stays valuable. Learn the fundamentals deeply and the tools will follow easily.'
];
var target='',pos=0,typed=0,correct=0,active=false,timer=null,left=0,dur=30;
function paint(){
  var box=gid('tt-text');box.innerHTML='';
  for(var i=0;i<target.length;i++){
    var sp=document.createElement('span');sp.textContent=target[i];
    if(i<pos)sp.style.color=target[i]==='OK'?'#888':'#888';
    box.appendChild(sp);
  }
  var spans=box.children;
  for(var j=0;j<typedChars.length;j++){
    if(j>=spans.length)break;
    if(typedChars[j]===target[j])spans[j].style.color='#1a9e50';
    else spans[j].style.color='#d33';
    spans[j].style.background=j===pos-1?'#ffe9e9':'transparent';
  }
  if(pos<spans.length){spans[pos].style.background='#e3f2fd';spans[pos].style.borderRadius='3px';}
}
var typedChars=[];
function start(){
  target=PASSAGES[Math.floor(Math.random()*PASSAGES.length)];
  pos=0;typed=0;correct=0;typedChars=[];active=true;
  dur=parseInt(gid('tt-dur').value,10);left=dur;
  gid('tt-res-card').style.display='none';
  gid('tt-timer').textContent=left+'s left. Type the text above.';
  paint();
  clearInterval(timer);
  timer=setInterval(function(){
    left--;
    if(left<=0){finish();}
    else gid('tt-timer').textContent=left+'s left. Type the text above.';
  },1000);
}
