  active=false;clearInterval(timer);
  var mins=(dur-left)/60||dur/60;
  var wpm=Math.round((correct/5)/mins);
  var acc=typed?Math.round(correct/typed*100):0;
  gid('tt-wpm').textContent=wpm+' WPM';
  gid('tt-acc').textContent=acc+'%';
