(function(){
'use strict';
function gid(id){return document.getElementById(id);}
var STOP=['the','a','an','and','or','but','in','on','at','to','for','of','with','by','is','are','was','were','be','been','it','its','this','that','these','those','i','you','he','she','we','they','as','from','not','have','has','had','will','would','can','if','so','do','does','my','your','our','their','me','him','her','us','them','what','which','who','when','where','how','all','any','each','few','more','most','other','some','such','no','nor','too','very','just','than','then','there','here','into','over','after','before','between','through','during','about','up','out','off','again','once'];
function analyze(){
  var text=gid('kd-in').value.toLowerCase();
  var words=text.replace(/[^a-z0-9\s'-]/g,' ').split(/\s+/).filter(function(w){return w.length>1;});
  var rmStop=gid('kd-stop').checked;
  if(rmStop)words=words.filter(function(w){return STOP.indexOf(w)<0;});
  var n=parseInt(gid('kd-n').value,10),top=parseInt(gid('kd-top').value,10);
  var counts={},total=0;
  for(var i=0;i+n<=words.length;i++){
    var phrase=words.slice(i,i+n).join(' ');
    counts[phrase]=(counts[phrase]||0)+1;total++;
  }
  var rows=Object.keys(counts).map(function(k){return{k:k,c:counts[k]};});
  rows.sort(function(a,b){return b.c-a.c;});
  rows=rows.slice(0,top);
  var tb=gid('kd-table');tb.innerHTML='';
  rows.forEach(function(r){
    var tr=document.createElement('tr');
    var a=document.createElement('td');a.textContent=r.k;
    var b=document.createElement('td');b.textContent=r.c;
    var c=document.createElement('td');c.textContent=total?(r.c/total*100).toFixed(2)+'%':'-';
    tr.appendChild(a);tr.appendChild(b);tr.appendChild(c);tb.appendChild(tr);
  });
  gid('kd-stats').textContent=words.length+' words analyzed, '+Object.keys(counts).length+' unique phrases.';
  if(!rows.length)tb.innerHTML='<tr><td colspan="3">Paste some text to analyze.</td></tr>';
}
gid('kd-go').addEventListener('click',analyze);
})();

