(function(){
'use strict';
function gid(id){return document.getElementById(id);}
var FR=[[0.25,'1/4'],[1/3,'1/3'],[0.5,'1/2'],[2/3,'2/3'],[0.75,'3/4']];
function fmtQty(x){
  if(x<=0)return '0';
  var whole=Math.floor(x+1e-9),frac=x-whole,best='',bd=1e9;
  FR.forEach(function(f){var d=Math.abs(frac-f[0]);if(d<bd){bd=d;best=f[1];}});
  if(bd<0.06){
    if(best===''||frac<0.06)return String(whole||'');
    return (whole?whole+' ':'')+best;
  }
  var r=Math.round(x*100)/100;
  return String(r).replace(/\.0+$/,'');
}
function parseLine(line){
  var m=line.match(/^\s*(\d+\s+\d+\/\d+|\d+\/\d+|\d+(?:\.\d+)?)\s+(.*)$/);
  if(!m)return{qty:null,rest:line.trim()};
  var qs=m[1],qty;
  var mm=qs.match(/(\d+)\s+(\d+)\/(\d+)/);
  if(mm)qty=parseInt(mm[1],10)+parseInt(mm[2],10)/parseInt(mm[3],10);
  else if(qs.indexOf('/')>0){var p=qs.split('/');qty=parseInt(p[0],10)/parseInt(p[1],10);}
  else qty=parseFloat(qs);
  return{qty:qty,rest:m[2].trim()};
}
function scale(){
  var from=parseFloat(gid('rs-from').value),to=parseFloat(gid('rs-to').value);
  var tb=gid('rs-table');tb.innerHTML='';
  if(!isFinite(from)||!isFinite(to)||from<=0||to<=0){
    gid('rs-note').textContent='Enter valid serving numbers.';return;
  }
  var f=to/from;
  gid('rs-note').textContent='Scale factor: '+(Math.round(f*100)/100)+'x ('+from+' to '+to+' servings).';
  gid('rs-in').value.split('\n').forEach(function(line){
    if(!line.trim())return;
    var p=parseLine(line);
    var tr=document.createElement('tr');
    var a=document.createElement('td'),b=document.createElement('td');
    a.innerHTML='<strong>'+(p.qty===null?'to taste':fmtQty(p.qty*f))+'</strong>';
    b.textContent=p.rest;
    tr.appendChild(a);tr.appendChild(b);tb.appendChild(tr);
  });
  if(!tb.children.length)tb.innerHTML='<tr><td colspan="2">Enter ingredients above.</td></tr>';
}
