function err(m){var e=gid('am-error');e.style.display='block';gid('am-errmsg').textContent=m;}
function ok(s){gid('am-error').style.display='none';gid('am-status').textContent=s;}
var GENRES=['Blues','Classic Rock','Country','Dance','Disco','Funk','Grunge','Hip-Hop','Jazz','Metal','New Age','Oldies','Other','Pop','R&B','Rap','Reggae','Rock','Techno','Industrial','Alternative','Ska','Death Metal','Pranks','Soundtrack','Euro-Techno','Ambient','Trip-Hop','Vocal','Jazz+Funk','Fusion','Trance','Classical','Instrumental','Acid','House','Game','Sound Clip','Gospel','Noise','AlternRock','Bass','Soul','Punk','Space','Meditative','Instrumental Pop','Instrumental Rock','Ethnic','Gothic','Darkwave','Techno-Industrial','Electronic','Pop-Folk','Eurodance','Dream','Southern Rock','Comedy','Cult','Gangsta','Top 40','Christian Rap','Pop/Funk','Jungle','Native American','Cabaret','New Wave','Psychadelic','Rave','Showtunes','Trailer','Lo-Fi','Tribal','Acid Punk','Acid Jazz','Polka','Retro','Musical','Rock & Roll','Hard Rock'];
function synch(b){return (b[0]<<21)|(b[1]<<14)|(b[2]<<7)|b[3];}
function decText(bytes,enc){
  var s='';
  if(enc===1||enc===2){
    var u16=bytes[0]===255&&bytes[1]===254;
    for(var i=2;i+1<bytes.length;i+=2){
      var c=u16?bytes[i]|(bytes[i+1]<<8):(bytes[i]<<8)|bytes[i+1];
      if(c===0)break;s+=String.fromCharCode(c);
    }
  }else{
    for(var j=0;j<bytes.length;j++){if(bytes[j]===0)break;s+=String.fromCharCode(bytes[j]);}
  }
  return s.trim();
}
function parseID3v2(dv){
  var out={};
  if(dv.getUint8(0)!==0x49||dv.getUint8(1)!==0x44||dv.getUint8(2)!==0x33)return out;
  var size=synch([dv.getUint8(6),dv.getUint8(7),dv.getUint8(8),dv.getUint8(9)]);
  var off=10,end=10+size;
  var map={TIT2:'Title',TPE1:'Artist',TALB:'Album',TRCK:'Track',TYER:'Year',TCON:'Genre',COMM:'Comment',TCOM:'Composer'};
  while(off+10<end){
    var id=String.fromCharCode(dv.getUint8(off),dv.getUint8(off+1),dv.getUint8(off+2),dv.getUint8(off+3));
    if(!/^[A-Z0-9]{4}$/.test(id))break;
    var fsize=(dv.getUint8(off+4)<<24)|(dv.getUint8(off+5)<<16)|(dv.getUint8(off+6)<<8)|dv.getUint8(off+7);
    if(fsize<=0||off+10+fsize>dv.byteLength)break;
    if(map[id]){
      var enc=dv.getUint8(off+10),bytes=[];
      for(var i=off+11;i<off+10+fsize;i++)bytes.push(dv.getUint8(i));
      out[map[id]]=decText(bytes,enc);
    }
    off+=10+fsize;
  }
  return out;
}
function parseID3v1(dv){
  var out={},n=dv.byteLength;
  if(n<128)return out;
  var o=n-128;
  if(String.fromCharCode(dv.getUint8(o),dv.getUint8(o+1),dv.getUint8(o+2))!=='TAG')return out;
  function str(a,b){var s='';for(var i=a;i<b;i++){var c=dv.getUint8(o+i);if(c===0)break;s+=String.fromCharCode(c);}return s.trim();}
  out.Title=out.Title||str(3,33);out.Artist=out.Artist||str(33,63);
  out.Album=out.Album||str(63,93);out.Year=out.Year||str(93,97);
  out.Comment=out.Comment||str(97,127);
  var g=dv.getUint8(o+127);if(GENRES[g])out.Genre=out.Genre||GENRES[g];
  return out;
}
gid('am-file').addEventListener('change',function(){
  var f=this.files[0];gid('am-card').style.display='none';
  ok(f?('Ready: '+f.name):'No file selected.');
