function parse(md){
  var lines=md.split('\n'),html=[],i=0,inCode=false,codeBuf=[],listStack=[];
  function closeLists(){
    while(listStack.length){html.push(listStack.pop()==='ul'?'</ul>':'</ol>');}
  }
  while(i<lines.length){
    var line=lines[i];
    if(/^```/.test(line)){
      if(inCode){html.push('<pre><code>'+esc(codeBuf.join('\n'))+'</code></pre>');codeBuf=[];inCode=false;}
      else{closeLists();inCode=true;}
      i++;continue;
    }
    if(inCode){codeBuf.push(line);i++;continue;}
    var hm=line.match(/^(#{1,6})\s+(.*)$/);
    if(hm){closeLists();html.push('<h'+hm[1].length+'>'+inline(hm[2])+'</h'+hm[1].length+'>');i++;continue;}
    if(/^\s*---+\s*$/.test(line)){closeLists();html.push('<hr>');i++;continue;}
    if(/^\s*>\s?/.test(line)){
