    }
    var ulm=line.match(/^\s*[-*+]\s+(.*)$/);
    var olm=line.match(/^\s*\d+\.\s+(.*)$/);
    if(ulm||olm){
      var tag=ulm?'ul':'ol',txt=ulm?ulm[1]:olm[1];
      if(listStack[listStack.length-1]!==tag){closeLists();html.push('<'+tag+'>');listStack.push(tag);}
      html.push('<li>'+inline(txt)+'</li>');i++;continue;
    }
    closeLists();
