function parse(dv,name){
  setMsg('');
  if(dv.byteLength<4||dv.getUint16(0)!==0xFFD8){out.innerHTML='<p class="sub">Not a JPEG file. EXIF lives in JPEG photos.</p>';return;}
  var off=2,tiff=-1;
  while(off<dv.byteLength-8){
