  var le=gs(dv,tiff,2)==='II';
  function u32o(o){return le?dv.getUint32(o,true):dv.getUint32(o);}
  var tags={};
  readIfd(dv,tiff,tiff+u32o(tiff+4),le,tags);
  var rows=[];
  Object.keys(NAMES).forEach(function(k){
    k=parseInt(k,10);
    if(tags[k]!==undefined&&tags[k]!==''&&tags[k]!==null)rows.push([NAMES[k],fmtVal(k,tags[k])]);
  });
  if(tags[0x8769]!==undefined){var ex={};readIfd(dv,tiff,tiff+tags[0x8769],le,ex);
    Object.keys(NAMES).forEach(function(k){k=parseInt(k,10);
      if(ex[k]!==undefined&&ex[k]!==''&&ex[k]!==null&&!rows.some(function(r){return r[0]===NAMES[k];}))rows.push([NAMES[k],fmtVal(k,ex[k])]);});}
  if(tags[0x8825]!==undefined){var g={};readIfd(dv,tiff,tiff+tags[0x8825],le,g);
    var lat=gpsDec(g[1],g[2]),lon=gpsDec(g[3],g[4]);
    if(lat&&lon)rows.push(['GPS location',lat+', '+lon]);}
  if(!rows.length){out.innerHTML='<p class="sub">This JPEG has an EXIF block but no readable tags.</p>';return;}
  var h='<table style="width:100%;border-collapse:collapse;font-size:.9rem">';
  rows.forEach(function(r){h+='<tr><td style="padding:8px 10px;border-bottom:1px solid var(--line);font-weight:700">'+r[0]+'</td><td style="padding:8px 10px;border-bottom:1px solid var(--line)">'+String(r[1]).replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</td></tr>';});
  out.innerHTML=h+'</table><p class="hint" style="margin-top:10px">Parsed from '+rows.length+' tag(s) in '+name.replace(/&/g,'&amp;').replace(/</g,'&lt;')+'.</p>';
}
})();

