(function(){
var input=document.getElementById('ls-input'),
    out=document.getElementById('ls-out'),
    mode=document.getElementById('ls-mode'),
    dedupe=document.getElementById('ls-dedupe'),
    empty=document.getElementById('ls-empty'),
    trim=document.getElementById('ls-trim'),
    cs=document.getElementById('ls-case'),
    count=document.getElementById('ls-count');
function process(){
  var lines=input.value.split(/\r?\n/);
  if(trim.checked)lines=lines.map(function(l){return l.trim();});
  if(empty.checked)lines=lines.filter(function(l){return l.length>0;});
  if(dedupe.checked){
    var seen={},u=[];
    lines.forEach(function(l){var k=cs.checked?l.toLowerCase():l;if(!seen[k]){seen[k]=1;u.push(l);}});
    lines=u;
  }
  var m=mode.value;
  function key(l){return cs.checked?l.toLowerCase():l;}
  if(m==='az')lines.sort(function(a,b){var x=key(a),y=key(b);return x<y?-1:x>y?1:0;});
  else if(m==='za')lines.sort(function(a,b){var x=key(a),y=key(b);return x<y?1:x>y?-1:0;});
  else if(m==='num')lines.sort(function(a,b){return (parseFloat(a)||0)-(parseFloat(b)||0);});
  else if(m==='len')lines.sort(function(a,b){return a.length-b.length;});
  else if(m==='lenr')lines.sort(function(a,b){return b.length-a.length;});
  else if(m==='rev')lines.reverse();
  else if(m==='shuffle'){for(var i=lines.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=lines[i];lines[i]=lines[j];lines[j]=t;}}
  out.value=lines.join('\n');
  count.textContent=lines.length;
}
['input','change'].forEach(function(ev){
  input.addEventListener(ev,process);
  mode.addEventListener(ev,process);
  dedupe.addEventListener(ev,process);
  empty.addEventListener(ev,process);
  trim.addEventListener(ev,process);
  cs.addEventListener(ev,process);
});
document.getElementById('ls-copy').addEventListener('click',function(){
  out.select();
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(out.value);}
  else{document.execCommand('copy');}
});
document.getElementById('ls-clear').addEventListener('click',function(){input.value='';process();input.focus();});
process();
})();

(function(){
var input=document.getElementById('tt-input'),
    out=document.getElementById('tt-out'),
    mode=document.getElementById('tt-mode'),
    limit=document.getElementById('tt-limit'),
    whole=document.getElementById('tt-words'),
    ell=document.getElementById('tt-ellipsis'),
    one=document.getElementById('tt-oneline'),
    stats=document.getElementById('tt-stats'),
    flag=document.getElementById('tt-flag'),
    unit=document.getElementById('tt-unit');
function words(s){var w=s.trim().split(/\s+/);return s.trim()?w.length:0;}
function process(){
  var t=input.value;
  if(one.checked)t=t.replace(/\s+/g,' ');
  var lim=Math.max(1,parseInt(limit.value,10)||160);
  var truncated=false,res=t;
  if(mode.value==='chars'){
    if(t.length>lim){
      truncated=true;res=t.slice(0,lim);
      if(whole.checked){var sp=res.lastIndexOf(' ');if(sp>lim*0.5)res=res.slice(0,sp);}
      if(ell.checked)res=res.replace(/\s+$/,'')+'...';
