(function(){
function v(id){var e=document.getElementById(id);var n=parseFloat(e&&e.value);return isFinite(n)?n:0;}
function fmt(n){return '$'+Math.round(n).toLocaleString('en-US');}
function calc(){
  var price=v('rb-price'),downPct=v('rb-down'),rate=v('rb-rate'),term=v('rb-term'),
      tax=v('rb-tax'),ins=v('rb-ins'),maintPct=v('rb-maint'),appr=v('rb-appr'),
      rent=v('rb-rent'),rise=v('rb-rise'),years=Math.max(1,Math.round(v('rb-years')||7));
  var down=price*downPct/100,P=price-down,r=rate/100/12,n=term*12,k=Math.min(years*12,n);
  var m=r>0?P*r/(1-Math.pow(1+r,-n)):P/n;
  var bal=r>0?P*Math.pow(1+r,k)-m*(Math.pow(1+r,k)-1)/r:P-P*k/n;
  var homeVal=price*Math.pow(1+appr/100,years);
  var equity=Math.max(0,homeVal-bal);
  var buyCash=down+m*k+tax*years+ins*years+price*maintPct/100*years;
  var buyNet=buyCash-equity;
  var rentTot=0,rm=rent;
  for(var y=0;y<years;y++){rentTot+=rm*12;rm*=1+rise/100;}
  document.getElementById('rb-mp').textContent=fmt(m);
  document.getElementById('rb-buy').textContent=fmt(buyNet)+' net (after equity)';
  document.getElementById('rb-rent-t').textContent=fmt(rentTot);
  document.getElementById('rb-eq').textContent=fmt(equity);
  var diff=Math.abs(buyNet-rentTot);
  var vd=document.getElementById('rb-verdict');
  if(buyNet<rentTot){vd.innerHTML='<strong>Buying wins</strong> by about '+fmt(diff)+' over '+years+' years.';vd.style.color='var(--teal)';}
  else if(rentTot<buyNet){vd.innerHTML='<strong>Renting wins</strong> by about '+fmt(diff)+' over '+years+' years.';vd.style.color='var(--accent-dark)';}
  else{vd.textContent='It is roughly a tie.';vd.style.color='';}
}
var ids=['rb-price','rb-down','rb-rate','rb-term','rb-tax','rb-ins','rb-maint','rb-appr','rb-rent','rb-rise','rb-years'];
ids.forEach(function(id){var el=document.getElementById(id);el.addEventListener('input',calc);el.addEventListener('change',calc);});
calc();
})();

