(function(){
var mode=document.getElementById('al-mode'),
    ans=document.getElementById('al-ans'),
    steps=document.getElementById('al-steps');
function v(id){var n=parseFloat(document.getElementById(id).value);return isFinite(n)?n:0;}
function r(n){return Math.abs(n)<1e-12?0:Math.round(n*1e10)/1e10;}
function show(a,s){ans.innerHTML=a;steps.innerHTML=s;}
function step(t){return '<p class="sub" style="margin:6px 0">'+t+'</p>';}
['lin','quad','sys'].forEach(function(k){document.getElementById('al-'+k);});
function toggle(){
  var m=mode.value;
  document.getElementById('al-lin').style.display=m==='lin'?'':'none';
  document.getElementById('al-quad').style.display=m==='quad'?'':'none';
  document.getElementById('al-sys').style.display=m==='sys'?'':'none';
  solve();
}
function solve(){
  var m=mode.value,s='';
  if(m==='lin'){
    var a=v('al-a'),b=v('al-b'),c=v('al-c');
    s+=step('Equation: '+a+'x + '+b+' = '+c);
    if(a===0){show(b===c?'Infinite solutions':'No solution',s+step(a===0&&b===c?'0x = 0 is always true.':'0x = '+(c-b)+' is impossible.'));return;}
    s+=step('Subtract '+b+': '+a+'x = '+(c-b));
    s+=step('Divide by '+a+': x = '+(c-b)+' / '+a);
    var x=r((c-b)/a);
    s+=step('Check: '+a+'('+x+') + '+b+' = '+r(a*x+b));
    show('x = '+x,s);
  }else if(m==='quad'){
    var qa=v('al-qa'),qb=v('al-qb'),qc=v('al-qc');
    s+=step('Equation: '+qa+'x^2 + '+qb+'x + '+qc+' = 0');
    if(qa===0){show('Not quadratic (a = 0)',s+step('With a = 0 this is linear, not quadratic.'));return;}
    var D=qb*qb-4*qa*qc;
    s+=step('Discriminant D = b^2 - 4ac = '+qb+'^2 - 4('+qa+')('+qc+') = '+r(D));
    if(D>0){
      var x1=r((-qb+Math.sqrt(D))/(2*qa)),x2=r((-qb-Math.sqrt(D))/(2*qa));
      s+=step('D &gt; 0: two real roots.');
      s+=step('x = (-b ± √D) / 2a = ('+(-qb)+' ± √'+r(D)+') / '+(2*qa));
      show('x = '+x1+' or x = '+x2,s);
    }else if(D===0){
      var x0=r(-qb/(2*qa));
      s+=step('D = 0: one repeated real root, x = -b / 2a.');
      show('x = '+x0+' (double root)',s);
    }else{
      var re=r(-qb/(2*qa)),im=r(Math.sqrt(-D)/(2*qa));
      s+=step('D &lt; 0: two complex roots, x = (-b ± i√|D|) / 2a.');
      show('x = '+re+' ± '+im+'i',s);
    }
  }else{
    var a1=v('al-a1'),b1=v('al-b1'),c1=v('al-c1'),a2=v('al-a2'),b2=v('al-b2'),c2=v('al-c2');
    s+=step('Eq1: '+a1+'x + '+b1+'y = '+c1+' &nbsp; Eq2: '+a2+'x + '+b2+'y = '+c2);
    var det=a1*b2-a2*b1;
    s+=step('Determinant = a1·b2 − a2·b1 = '+r(det));
    if(det===0){show('No unique solution',s+step('Determinant is 0: the lines are parallel or identical.'));return;}
    var x=r((c1*b2-c2*b1)/det),y=r((a1*c2-a2*c1)/det);
    s+=step("Using Cramer's rule: x = (c1·b2 − c2·b1) / det, y = (a1·c2 − a2·c1) / det.");
    s+=step('Check eq1: '+r(a1*x+b1*y)+' = '+c1+' &nbsp; Check eq2: '+r(a2*x+b2*y)+' = '+c2);
    show('x = '+x+', y = '+y,s);
  }
}
mode.addEventListener('change',toggle);
document.getElementById('al-go').addEventListener('click',solve);
var allIds=['al-a','al-b','al-c','al-qa','al-qb','al-qc','al-a1','al-b1','al-c1','al-a2','al-b2','al-c2'];
allIds.forEach(function(id){document.getElementById(id).addEventListener('input',solve);});
toggle();
})();

