  var dec=Math.max(0,sig-1-mag);
  return Number(r.toPrecision(sig)).toString();
}
function calc(){
  var raw=numEl.value.trim();
  var n=Number(raw);
  if(raw===''||!isFinite(n)){ans.textContent='Enter a valid number.';rule.textContent='';return;}
  var c=countSigFigs(raw);
  if(mode.value==='count'){
    ans.textContent=raw+' has '+c.n+' significant figure'+(c.n===1?'':'s');
    rule.textContent='Rule applied: '+c.note;
  }else{
    var sig=Math.max(1,Math.min(21,parseInt(nEl.value,10)||3));
    var r=roundSig(n,sig);
    ans.textContent=n+' → '+r+' ('+sig+' s.f.)';
    rule.textContent='Rounded using standard half-up rounding. The input itself has '+c.n+' significant figure'+(c.n===1?'':'s')+'.';
  }
}
