(function(){
var input=document.getElementById('hv-input'),
    out=document.getElementById('hv-out'),
    sum=document.getElementById('hv-sum');
var VOID={area:1,base:1,br:1,col:1,embed:1,hr:1,img:1,input:1,link:1,meta:1,param:1,source:1,track:1,wbr:1};
var DEPR={font:'use CSS font properties',center:'use CSS text-align',marquee:'use CSS animations',blink:'remove it, please',
  bgsound:'use the audio element',applet:'use object or embed',frame:'use iframe',frameset:'use iframe or CSS layout',
  big:'use CSS font-size',strike:'use del or CSS',tt:'use code or CSS',u:'use CSS text-decoration'};
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function lineOf(idx,lines){var c=0;for(var i=0;i<lines.length;i++){c+=lines[i].length+1;if(idx<c)return i+1;}return lines.length;}
function validate(){
  var html=input.value,lines=html.split('\n');
  var issues=[],ids={},stack=[];
  var re=/<!--[\s\S]*?-->|<!DOCTYPE[^>]*>|<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\s[^<>]*)?)\/?>/g,m;
  while((m=re.exec(html))!==null){
    var full=m[0],ln=lineOf(m.index,lines);
    if(full.indexOf('<!--')===0||/^<!DOCTYPE/i.test(full))continue;
    var tag=m[1].toLowerCase(),attrs=m[2]||'';
    var closing=full[1]==='/',selfClose=/\/$/.test(full)||VOID[tag];
    if(DEPR[tag])issues.push({t:'warn',msg:'Line '+ln+': <'+tag+'> is deprecated: '+DEPR[tag]+'.'});
    var idm=/\sid\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(attrs);
    if(idm){
      var idv=idm[2]||idm[3]||idm[4];
      if(ids[idv])issues.push({t:'err',msg:'Line '+ln+': duplicate id "'+idv+'" (first on line '+ids[idv]+').'});
      else ids[idv]=ln;
    }
    if(tag==='img'&&!/\salt\s*=/i.test(attrs))issues.push({t:'warn',msg:'Line '+ln+': <img> is missing an alt attribute.'});
    if(tag==='a'&&!/\shref\s*=/i.test(attrs))issues.push({t:'warn',msg:'Line '+ln+': <a> has no href attribute.'});
    if(closing){
      if(VOID[tag]){issues.push({t:'err',msg:'Line '+ln+': void element <'+tag+'> must not have a closing tag.'});continue;}
      var found=-1;
      for(var i=stack.length-1;i>=0;i--){if(stack[i].tag===tag){found=i;break;}}
      if(found<0){issues.push({t:'err',msg:'Line '+ln+': stray closing tag </'+tag+'> with no matching opener.'});}
      else{
        for(var j=stack.length-1;j>found;j--){
          var u=stack.pop();
          issues.push({t:'err',msg:'Line '+ln+': <'+u.tag+'> opened on line '+u.ln+' was never closed before </'+tag+'>.'});
        }
        stack.pop();
      }
    }else if(!selfClose){
      stack.push({tag:tag,ln:ln});
    }
  }
  stack.forEach(function(u){issues.push({t:'err',msg:'Line '+u.ln+': <'+u.tag+'> was never closed.'});});
  if(!/^\s*<!DOCTYPE/i.test(html))issues.push({t:'warn',msg:'Missing DOCTYPE declaration at the top of the document.'});
  if(!/<html[\s>]/i.test(html))issues.push({t:'warn',msg:'Missing <html> root element.'});
  if(!/<title[\s>]/i.test(html))issues.push({t:'warn',msg:'Missing <title> element (important for SEO and tabs).'});
  var errs=issues.filter(function(x){return x.t==='err';}).length,
      warns=issues.length-errs;
  if(!html.trim()){sum.textContent='';out.innerHTML='<p class="sub">Paste HTML and press Validate.</p>';return;}
  sum.textContent=issues.length===0?'No issues found. Clean markup!':(errs+' error(s), '+warns+' warning(s)');
  sum.style.color=issues.length===0?'var(--teal)':'';
  var h='';
  issues.forEach(function(x){
    h+='<div style="border-left:4px solid '+(x.t==='err'?'#DC2626':'#D97706')+';background:var(--surface);border-radius:0 10px 10px 0;padding:9px 13px;margin-bottom:8px;font-size:.88rem">'+esc(x.msg)+'</div>';
  });
  out.innerHTML=h||'<p class="sub">No issues found.</p>';
}
document.getElementById('hv-go').addEventListener('click',validate);
document.getElementById('hv-clear').addEventListener('click',function(){input.value='';sum.textContent='';out.innerHTML='<p class="sub">Paste HTML and press Validate.</p>';});
input.addEventListener('input',validate);
})();

(function(){
var input=document.getElementById('le-input'),
    baseEl=document.getElementById('le-base'),
    filter=document.getElementById('le-filter'),
    out=document.getElementById('le-out'),
    msg=document.getElementById('le-msg'),
    count=document.getElementById('le-count'),
    brk=document.getElementById('le-break'),
    found=[];
function setMsg(t){msg.textContent=t||'';}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function host(u){try{return new URL(u,baseEl.value.trim()||'https://x.local').hostname;}catch(e){return '';}}
function isExt(u){
  var b=baseEl.value.trim();
  if(!b)return null;
  try{
    var bh=new URL(b).hostname,uh=new URL(u,b).hostname;
    return uh&&uh!==bh;
  }catch(e){return null;}
}
function render(){
  var f=filter.value;
  var list=found.filter(function(x){
    if(f==='links')return x.kind==='a';
    if(f==='media')return x.kind!=='a';
    if(f==='ext')return x.ext===true;
    if(f==='int')return x.ext===false;
    return true;
  });
  count.textContent=list.length;
  var ext=list.filter(function(x){return x.ext;}).length;
  brk.textContent=ext+' external, '+(list.length-ext)+' internal/relative';
  if(!list.length){out.innerHTML='<p class="sub">No URLs match this filter.</p>';return;}
  var h='';
  list.slice(0,2000).forEach(function(x){
    h+='<div style="border-bottom:1px solid var(--line);padding:8px 2px;font-size:.85rem">'
      +'<span class="hint" style="margin:0 8px 0 0">'+esc(x.kind)+'</span>'
      +'<a href="'+esc(x.url)+'" target="_blank" rel="noopener" style="word-break:break-all">'+esc(x.url)+'</a>'
      +(x.text?'<div class="hint" style="margin:2px 0 0">link text: '+esc(x.text)+'</div>':'')+'</div>';
  });
  out.innerHTML=h+(list.length>2000?'<p class="hint">Showing first 2,000.</p>':'');
}
document.getElementById('le-go').addEventListener('click',function(){
  setMsg('');
  var html=input.value;
  if(!html.trim()){setMsg('Paste some HTML first.');return;}
  var doc;
  try{doc=new DOMParser().parseFromString(html,'text/html');}
  catch(e){setMsg('Could not parse that HTML.');return;}
  var seen={},res=[];
  function add(url,kind,text){
    if(!url)return;
    url=url.trim();
    if(!url||url[0]==='#'||url.indexOf('javascript:')===0||url.indexOf('mailto:')===0||url.indexOf('tel:')===0)return;
    try{url=new URL(url,baseEl.value.trim()||'https://x.local').href;}catch(e){}
    if(seen[url])return;seen[url]=1;
    res.push({url:url,kind:kind,text:(text||'').trim().slice(0,80),ext:isExt(url)});
  }
  var as=doc.querySelectorAll('a[href]');
  for(var i=0;i<as.length;i++)add(as[i].getAttribute('href'),'a',as[i].textContent);
  var imgs=doc.querySelectorAll('img[src]');
  for(var j=0;j<imgs.length;j++)add(imgs[j].getAttribute('src'),'img',imgs[j].getAttribute('alt'));
  var links=doc.querySelectorAll('link[href]');
  for(var k=0;k<links.length;k++)add(links[k].getAttribute('href'),'link');
  var scrs=doc.querySelectorAll('script[src]');
  for(var l=0;l<scrs.length;l++)add(scrs[l].getAttribute('src'),'script');
  var vids=doc.querySelectorAll('video[src],source[src]');
  for(var m2=0;m2<vids.length;m2++)add(vids[m2].getAttribute('src'),'media');
  found=res;
  render();
  setMsg('Extracted '+res.length+' unique URL(s).');
});
filter.addEventListener('change',render);
baseEl.addEventListener('input',function(){
  found.forEach(function(x){x.ext=isExt(x.url);});
  render();
});
document.getElementById('le-copy').addEventListener('click',function(){
  var urls=found.map(function(x){return x.url;});
  if(!urls.length){setMsg('Extract something first.');return;}
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(urls.join('\n'));setMsg('Copied '+urls.length+' URL(s).');}
});
document.getElementById('le-dl').addEventListener('click',function(){
  if(!found.length){setMsg('Extract something first.');return;}
  var a=document.createElement('a');
  a.href=URL.createObjectURL(new Blob([found.map(function(x){return x.url;}).join('\n')],{type:'text/plain'}));
  a.download='urls.txt';document.body.appendChild(a);a.click();a.remove();
});
})();

(function(){
var title=document.getElementById('sp-title'),
    url=document.getElementById('sp-url'),
    desc=document.getElementById('sp-desc');
var meas=document.createElement('canvas').getContext('2d');
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function truncPx(text,maxPx,font){
  meas.font=font;
  if(meas.measureText(text).width<=maxPx)return {t:text,cut:false};
  var lo=0,hi=text.length;
  while(lo<hi){
    var mid=Math.floor((lo+hi)/2);
    if(meas.measureText(text.slice(0,mid)+'…').width<=maxPx)lo=mid+1;else hi=mid;
  }
  return {t:text.slice(0,Math.max(0,lo-1))+'…',cut:true};
}
function truncChars(text,max){
  if(text.length<=max)return {t:text,cut:false};
  return {t:text.slice(0,max-1).replace(/\s+$/,'')+'…',cut:true};
}
function update(){
  var t=title.value||'Untitled',u=url.value,d=desc.value;
  meas.font='20px Arial, sans-serif';
  var tpx=Math.round(meas.measureText(t).width);
  document.getElementById('sp-tc').textContent=t.length;
  document.getElementById('sp-tpx').textContent=tpx;
  var dt=truncPx(t,600,'20px Arial, sans-serif');
  var mt=truncPx(t,360,'18px Arial, sans-serif');
  var dd=truncChars(d,160),md=truncChars(d,130);
  document.getElementById('sp-dt').innerHTML=esc(dt.t);
  document.getElementById('sp-mt').innerHTML=esc(mt.t);
  document.getElementById('sp-du').textContent=u;
  document.getElementById('sp-dd').textContent=dd.t;
  document.getElementById('sp-mdd').textContent=md.t;
  var tw=document.getElementById('sp-tw');
  tw.textContent=dt.cut?'(truncated on desktop!)':(tpx>580?'(close to the limit)':'(fits)');
  tw.style.color=dt.cut?'#DC2626':'var(--faint)';
  var dw=document.getElementById('sp-dw');
  dw.textContent=dd.cut?'(truncated!)':(d.length>150?'(close to the limit)':'(fits)');
  dw.style.color=dd.cut?'#DC2626':'var(--faint)';
  document.getElementById('sp-dc').textContent=d.length;
}
[title,url,desc].forEach(function(el){el.addEventListener('input',update);});
update();
})();

(function(){
var choresEl=document.getElementById('cs-chores'),
    out=document.getElementById('cs-out'),
    chores=[{n:'Dishes',f:'daily'},{n:'Vacuum living room',f:'weekly'},{n:'Take out trash',f:'weekly'}];
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function renderChores(){
  choresEl.innerHTML='';
  chores.forEach(function(c,i){
    var d=document.createElement('div');
    d.style.cssText='display:flex;gap:8px;margin-bottom:8px;align-items:center';
    d.innerHTML='<input type="text" value="'+esc(c.n).replace(/"/g,'&quot;')+'" data-i="'+i+'" placeholder="Chore name" style="flex:3;min-width:0"/>'
      +'<select data-i="'+i+'" data-f="1" style="flex:1;min-width:0"><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="monthly">Monthly</option></select>'
      +'<button class="btn btn-outline btn-sm" data-del="'+i+'">x</button>';
    choresEl.appendChild(d);
    d.querySelector('select').value=c.f;
  });
  var ins=choresEl.querySelectorAll('input[data-i]');
  for(var k=0;k<ins.length;k++){ins[k].addEventListener('input',function(){chores[parseInt(this.getAttribute('data-i'),10)].n=this.value;});}
  var sels=choresEl.querySelectorAll('select[data-f]');
  for(var j=0;j<sels.length;j++){sels[j].addEventListener('change',function(){chores[parseInt(this.getAttribute('data-i'),10)].f=this.value;});}
  var dels=choresEl.querySelectorAll('[data-del]');
  for(var l=0;l<dels.length;l++){dels[l].addEventListener('click',function(){chores.splice(parseInt(this.getAttribute('data-del'),10),1);renderChores();});}
