document.getElementById('cs-add').addEventListener('click',function(){chores.push({n:'',f:'weekly'});renderChores();});
document.getElementById('cs-week').value=new Date().toISOString().slice(0,10);
var DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function build(){
  var names=document.getElementById('cs-week')?document.getElementById('cs-names').value.split('\n').map(function(x){return x.trim();}).filter(function(x){return x;}):[];
  names=document.getElementById('cs-names').value.split('\n').map(function(x){return x.trim();}).filter(function(x){return x;});
  var list=chores.filter(function(c){return c.n.trim();});
  if(names.length<1){out.innerHTML='<p class="sub">Add at least one household member.</p>';return null;}
  if(!list.length){out.innerHTML='<p class="sub">Add at least one chore.</p>';return null;}
  var weekStr=document.getElementById('cs-week').value;
  var weekNum=0;
  if(weekStr){var d0=new Date(2026,0,5);var d1=new Date(weekStr+'T00:00:00');weekNum=Math.max(0,Math.floor((d1-d0)/604800000));}
  var daily=list.filter(function(c){return c.f==='daily';});
  var weekly=list.filter(function(c){return c.f==='weekly';});
  var monthly=list.filter(function(c){return c.f==='monthly';});
  var h='<table style="border-collapse:collapse;width:100%;font-size:.88rem"><thead><tr><th style="border:1px solid var(--line);padding:8px;background:var(--surface);text-align:left">Day</th><th style="border:1px solid var(--line);padding:8px;background:var(--surface);text-align:left">Chores</th></tr></thead><tbody>';
  var text='WEEKLY CHORE SCHEDULE\n';
  for(var di=0;di<7;di++){
    var rows=[];
    daily.forEach(function(c,ci){rows.push(esc(c.n)+' — '+esc(names[(ci+di+weekNum)%names.length]));});
    weekly.forEach(function(c,ci){var who=names[(ci+weekNum)%names.length];rows.push(esc(c.n)+' — '+esc(who)+(di===0?' (this week)':''));});
    if(di===0)monthly.forEach(function(c,ci){rows.push(esc(c.n)+' — '+esc(names[(ci+weekNum)%names.length])+' (monthly)');});
    h+='<tr><td style="border:1px solid var(--line);padding:8px;font-weight:700;white-space:nowrap">'+DAYS[di]+'</td><td style="border:1px solid var(--line);padding:8px">'+(rows.join('<br>')||'<span class="hint">Rest day</span>')+'</td></tr>';
    text+=DAYS[di].toUpperCase()+'\n'+rows.map(function(r){return ' - '+r.replace(/<[^>]+>/g,'');}).join('\n')+'\n';
  }
  out.innerHTML=h+'</tbody></table><p class="hint">Daily chores rotate by day; weekly and monthly chores rotate each week. Change the week-start date to see next week\'s rotation.</p>';
  return text;
}
var lastText='';
document.getElementById('cs-go').addEventListener('click',function(){lastText=build()||'';});
document.getElementById('cs-copy').addEventListener('click',function(){
  if(!lastText)lastText=build()||'';
  if(lastText&&navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(lastText);}
});
document.getElementById('cs-print').addEventListener('click',function(){window.print();});
renderChores();
})();

(function(){
