(function(){
function v(id){var n=parseFloat(document.getElementById(id).value);return isFinite(n)&&n>0?n:0;}
var shape=document.getElementById('ra-shape'),unit=document.getElementById('ra-unit');
function toggle(){
  var s=shape.value;
  document.getElementById('ra-rect').style.display=s==='rect'?'':'none';
  document.getElementById('ra-lshape').style.display=s==='lshape'?'':'none';
  document.getElementById('ra-circle').style.display=s==='circle'?'':'none';
  document.getElementById('ra-tri').style.display=s==='tri'?'':'none';
  calc();
}
function calc(){
  var s=shape.value,u=unit.value,f=u==='m'?1:0.3048;
  var areaU=0,perU=0,note='';
  if(s==='rect'){
    var l=v('ra-len'),w=v('ra-wid');areaU=l*w;perU=2*(l+w);
  }else if(s==='lshape'){
    var a1=v('ra-a1'),a2=v('ra-a2'),b1=v('ra-b1'),b2=v('ra-b2');
    areaU=a1*a2+b1*b2;perU=2*(a1+a2)+2*(b1+b2);
    note='L-shape perimeter is approximate (assumes the standard notch layout).';
  }else if(s==='circle'){
    var r=v('ra-rad');areaU=Math.PI*r*r;perU=2*Math.PI*r;
  }else{
    var b=v('ra-tb'),h=v('ra-th');areaU=0.5*b*h;perU=b+h+Math.sqrt(b*b+h*h);
    note='Triangle perimeter assumes a right triangle.';
  }
  var m2=areaU*f*f,mf=areaU/(f*f)*10.7639;
  if(u==='ft'){mf=areaU; m2=areaU/10.7639;}
  function r2(n){return Math.round(n*100)/100;}
  document.getElementById('ra-area').textContent=r2(m2)+' m² ('+r2(mf)+' ft²)';
  var perM=perU*f,perF=perU/(f)*3.28084;
  if(u==='ft'){perF=perU;perM=perU/3.28084;}
  document.getElementById('ra-per').textContent=r2(perM)+' m ('+r2(perF)+' ft)';
  var coats=Math.max(1,Math.round(v('ra-coats')||2));
  var liters=m2*coats/10;
  document.getElementById('ra-paint').textContent=r2(liters)+' liters ('+coats+' coat'+(coats>1?'s':'')+' at 10 m²/L)';
  document.getElementById('ra-note').textContent=note||'Add 10% extra paint for touch-ups and waste.';
}
shape.addEventListener('change',toggle);unit.addEventListener('change',calc);
['ra-len','ra-wid','ra-a1','ra-a2','ra-b1','ra-b2','ra-rad','ra-tb','ra-th','ra-coats'].forEach(function(id){
  var el=document.getElementById(id);el.addEventListener('input',calc);el.addEventListener('change',calc);
});
toggle();
})();

(function(){
var fileEl=document.getElementById('at-file'),
    sEl=document.getElementById('at-start'),eEl=document.getElementById('at-end'),
    sV=document.getElementById('at-start-v'),eV=document.getElementById('at-end-v'),
    lenEl=document.getElementById('at-len'),msg=document.getElementById('at-msg'),
    info=document.getElementById('at-info'),play=document.getElementById('at-play'),
    exp=document.getElementById('at-exp'),dl=document.getElementById('at-dl'),
    wave=document.getElementById('at-wave'),
    actx=null,buf=null;
function setMsg(t){msg.textContent=t||'';}
function fmtT(s){return (Math.round(s*10)/10)+'s';}
function sel(){
  var d=buf?buf.duration:0;
  var a=sEl.value/1000*d,b=eEl.value/1000*d;
  if(a>b){var t=a;a=b;b=t;}
  return [a,b];
}
function draw(){
  var ctx=wave.getContext('2d'),W=wave.width,H=wave.height;
  ctx.clearRect(0,0,W,H);
  if(!buf){ctx.fillStyle='#999';ctx.font='14px sans-serif';ctx.fillText('Waveform appears here',20,H/2);return;}
  var ch=buf.getChannelData(0),step=Math.max(1,Math.floor(ch.length/W));
  ctx.fillStyle='#7C3AED';
  for(var x=0;x<W;x++){
    var peak=0;
    for(var i=x*step;i<(x+1)*step&&i<ch.length;i+=4){var a=Math.abs(ch[i]);if(a>peak)peak=a;}
    var hh=Math.max(1,peak*H*0.9);
    ctx.fillRect(x,(H-hh)/2,1,hh);
  }
  var s=sEl.value/1000*W,e=eEl.value/1000*W;
  var x0=Math.min(s,e),x1=Math.max(s,e);
  ctx.fillStyle='rgba(0,0,0,0.45)';
  ctx.fillRect(0,0,x0,H);ctx.fillRect(x1,0,W-x1,H);
  ctx.strokeStyle='#10B981';ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(x0,0);ctx.lineTo(x0,H);ctx.moveTo(x1,0);ctx.lineTo(x1,H);ctx.stroke();
}
function refresh(){
  if(!buf)return;
  var ab=sel();
  sV.textContent=fmtT(ab[0]);eV.textContent=fmtT(ab[1]);lenEl.textContent=fmtT(ab[1]-ab[0]);
  draw();
}
fileEl.addEventListener('change',function(){
  var f=fileEl.files&&fileEl.files[0];if(!f)return;
  setMsg('Decoding '+f.name+' ...');
  try{actx=actx||new (window.AudioContext||window.webkitAudioContext)();}catch(e){setMsg('Web Audio is not supported in this browser.');return;}
  var r=new FileReader();
  r.onload=function(){
    actx.decodeAudioData(r.result).then(function(b){
      buf=b;
      sEl.disabled=false;eEl.disabled=false;play.disabled=false;exp.disabled=false;
      sEl.value=0;eEl.value=1000;
      info.textContent=f.name+': '+fmtT(b.duration)+', '+b.sampleRate+' Hz, '+b.numberOfChannels+' channel(s).';
      setMsg('');refresh();
    }).catch(function(){setMsg('Could not decode that file. Try MP3, WAV or OGG.');});
