(function(){
"use strict";
function esc(s){return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function inline(s){
  s=esc(s);
  s=s.replace(/`([^`]+)`/g,"<code>$1</code>");
  s=s.replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>");
  s=s.replace(/(^|[^*])\*([^*\n]+)\*/g,"$1<em>$2</em>");
  s=s.replace(/~~([^~]+)~~/g,"<del>$1</del>");
  s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2" rel="noopener">$1</a>');
  return s;
}
function mdToHtml(src){
  var lines=String(src).split("\n"), html=[], i=0, inCode=false, codeBuf=[], listBuf=[], listType=null;
  function flushList(){
    if(listBuf.length){ html.push("<"+listType+">"+listBuf.join("")+"</"+listType+">"); listBuf=[]; listType=null; }
  }
  while(i<lines.length){
    var ln=lines[i];
    if(/^```/.test(ln)){ if(inCode){ html.push("<pre><code>"+esc(codeBuf.join("\n"))+"</code></pre>"); codeBuf=[]; inCode=false; } else { flushList(); inCode=true; } i++; continue; }
    if(inCode){ codeBuf.push(ln); i++; continue; }
    var t=ln.trim();
    if(t===""){ flushList(); i++; continue; }
    if(/^(---+|\*\*\*+)$/.test(t)){ flushList(); html.push("<hr>"); i++; continue; }
    var hm=t.match(/^(#{1,6})\s+(.*)$/);
    if(hm){ flushList(); html.push("<h"+hm[1].length+">"+inline(hm[2])+"</h"+hm[1].length+">"); i++; continue; }
    var bq=t.match(/^>\s?(.*)$/);
    if(bq){ flushList(); html.push("<blockquote>"+inline(bq[1])+"</blockquote>"); i++; continue; }
    var ul=t.match(/^[-*+]\s+(.*)$/);
    var ol=t.match(/^\d+\.\s+(.*)$/);
    if(ul||ol){
      var type=ul?"ul":"ol", txt=ul?ul[1]:ol[1];
      if(listType&&listType!==type) flushList();
      listType=type; listBuf.push("<li>"+inline(txt)+"</li>"); i++; continue;
    }
    if(/^\|.*\|$/.test(t)){
      flushList();
      var rows=[], j=i;
      while(j<lines.length && /^\|.*\|$/.test(lines[j].trim())){ rows.push(lines[j].trim()); j++; }
      var body=rows.filter(function(r){return !/^\|[\s:|-]+\|$/.test(r);});
      var th=body[0].split("|").filter(function(c){return c.trim()!=="";}).map(function(c){return "<th>"+inline(c.trim())+"</th>";}).join("");
      var tb=body.slice(1).map(function(r){
        return "<tr>"+r.split("|").filter(function(c){return c.trim()!=="";}).map(function(c){return "<td>"+inline(c.trim())+"</td>";}).join("")+"</tr>";
      }).join("");
      html.push("<table><thead><tr>"+th+"</tr></thead><tbody>"+tb+"</tbody></table>");
      i=j; continue;
    }
    flushList(); html.push("<p>"+inline(t)+"</p>"); i++;
  }
  flushList();
  if(inCode) html.push("<pre><code>"+esc(codeBuf.join("\n"))+"</code></pre>");
  return html.join("\n");
}
var inp=document.getElementById("md-in"), prev=document.getElementById("md-preview"), out=document.getElementById("md-html");
function render(){
  var h=mdToHtml(inp.value);
  prev.innerHTML=h||'<span style="opacity:.6">Nothing to preview yet.</span>';
  out.value=h;
}
