(function(){
"use strict";
var fileEl=document.getElementById("px-file"), rangeEl=document.getElementById("px-range"),
    go=document.getElementById("px-go"), status=document.getElementById("px-status"),
    info=document.getElementById("px-info"), dlRow=document.getElementById("px-dl-row"),
    dl=document.getElementById("px-dl");
var pdfBytes=null, pageCount=0, fileName="extracted.pdf";
function setStatus(t){status.textContent=t;}
fileEl.addEventListener("change",function(){
  var f=fileEl.files[0]; if(!f) return;
  fileName=f.name.replace(/\.pdf$/i,"")+"-extracted.pdf";
  var rd=new FileReader();
  rd.onload=function(){
    pdfBytes=rd.result;
    window.PDFLib.PDFDocument.load(pdfBytes).then(function(doc){
      pageCount=doc.getPageCount();
      info.textContent="Loaded "+f.name+" — "+pageCount+" pages. Enter ranges like 1-3, 5.";
      go.disabled=false; setStatus("Ready. Enter the pages you want and press Extract.");
    }).catch(function(){ setStatus("Could not read that file. Please choose a valid PDF."); });
  };
  rd.readAsArrayBuffer(f);
});
function parseRange(str,total){
  var out=[], parts=str.split(",");
  for(var k=0;k<parts.length;k++){
    var p=parts[k].trim(); if(!p) continue;
    var m=p.match(/^(\d+)\s*-\s*(\d+)$/);
    if(m){
      var a=parseInt(m[1],10), b=parseInt(m[2],10);
      if(a>b){var t=a;a=b;b=t;}
      for(var n=a;n<=b;n++) if(n>=1&&n<=total&&out.indexOf(n)<0) out.push(n);
    } else if(/^\d+$/.test(p)){
      var v=parseInt(p,10);
      if(v>=1&&v<=total&&out.indexOf(v)<0) out.push(v);
    } else return null;
  }
  out.sort(function(x,y){return x-y;});
  return out;
}
go.addEventListener("click",function(){
  if(!pdfBytes) return;
  var pages=parseRange(rangeEl.value,pageCount);
  if(!pages||!pages.length){ setStatus("Invalid range. Use numbers like 1-3, 5 within 1-"+pageCount+"."); return; }
  setStatus("Extracting "+pages.length+" page(s)...");
  var idx=pages.map(function(p){return p-1;});
  window.PDFLib.PDFDocument.load(pdfBytes).then(function(src){
    return window.PDFLib.PDFDocument.create().then(function(dst){
      return dst.copyPages(src,idx).then(function(copied){
        copied.forEach(function(p){dst.addPage(p);});
        return dst.save();
      });
    });
  }).then(function(bytes){
    var blob=new Blob([bytes],{type:"application/pdf"});
    var url=URL.createObjectURL(blob);
    dl.href=url; dl.setAttribute("download",fileName);
    dlRow.style.display="block";
    setStatus("Done. "+pages.length+" page(s) extracted: "+pages.join(", ")+".");
  }).catch(function(){ setStatus("Extraction failed. The PDF may be encrypted or damaged."); });
});
})();

