  var goal=v("sg-goal"), now=v("sg-now"), dep=v("sg-monthly"), rate=v("sg-rate")/100;
  var mr=rate/12, bal=now, months=0, paid=0;
  if(goal<=0){document.getElementById("sg-time").textContent="-";document.getElementById("sg-date").textContent="Enter a goal above zero.";document.getElementById("sg-break").innerHTML="";return;}
