(function(){
"use strict";
var ALPHA="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-";
var CROCK="0123456789ABCDEFGHJKMNPQRSTVWXYZ";
function rnd(n){var a=new Uint8Array(n);(window.crypto||{}).getRandomValues?crypto.getRandomValues(a):a.forEach(function(_,i){a[i]=Math.floor(Math.random()*256);});return a;}
function nanoId(len){var r=rnd(len),s="";for(var i=0;i<len;i++)s+=ALPHA[r[i]&63];return s;}
function ulid(){
  var t=Date.now(), time="";
  for(var i=0;i<10;i++){time=CROCK[t%32]+time;t=Math.floor(t/32);}
  var r=rnd(10), rand="";
  var carry=0, val=0, bits=0;
  for(var j=0;j<10;j++){
    val=(val<<8)|r[j]; bits+=8;
    var out="";
    while(bits>=5){bits-=5;out=CROCK[(val>>bits)&31]+out;}
    rand=out+rand; val=val&((1<<bits)-1);
  }
  while(rand.length<16)rand="0"+rand;
  return (time+rand).slice(-26);
}
