(function(){
"use strict";
function isPrime(n){
  if(n<2)return false; if(n===2||n===3)return true;
  if(n%2===0||n%3===0)return false;
  for(var i=5;i*i<=n;i+=6){if(n%i===0||n%(i+2)===0)return false;}
  return true;
}
function factorize(n){
  var f={},d=2,temp=n;
  while(d*d<=temp){while(temp%d===0){f[d]=(f[d]||0)+1;temp/=d;}d+=d===2?1:2;}
  if(temp>1)f[temp]=(f[temp]||0)+1;
  return f;
}
var mode=document.getElementById("pr-mode"), bRow=document.getElementById("pr-b-row"),
    aLabel=document.getElementById("pr-a-label"), hint=document.getElementById("pr-hint");
var labels={check:"Number",range:"From",nth:"N (which prime)",factor:"Number"};
var hints={check:"Tests divisibility up to the square root. Handles numbers up to 10^12 quickly.",
 range:"Lists every prime between From and To (max range 100,000).",
 nth:"Finds the Nth prime (N up to 1,000,000).",
 factor:"Breaks the number into its prime factors."};
mode.addEventListener("change",function(){
  bRow.style.display=mode.value==="range"?"block":"none";
  aLabel.textContent=labels[mode.value]; hint.textContent=hints[mode.value];
});
document.getElementById("pr-go").addEventListener("click",function(){
  var m=mode.value, a=Math.floor(Math.abs(parseFloat(document.getElementById("pr-a").value)||0)),
      b=Math.floor(Math.abs(parseFloat(document.getElementById("pr-b").value)||0)),
      out=document.getElementById("pr-out");
  if(m==="check"){
    out.textContent=a+(isPrime(a)?" IS prime.":" is NOT prime.")+(a>1&&!isPrime(a)?" Smallest factor: "+function(){for(var i=2;i*i<=a;i++)if(a%i===0)return i;return a;}()+".":"");
  }else if(m==="range"){
    var lo=Math.min(a,b), hi=Math.max(a,b);
    if(hi-lo>100000){out.textContent="Range too wide. Keep it under 100,000.";return;}
    var arr=[]; for(var n=lo;n<=hi;n++) if(isPrime(n)) arr.push(n);
    out.textContent=arr.length+" prime(s) between "+lo+" and "+hi+":\n"+(arr.join(", ")||"none");
  }else if(m==="nth"){
    if(a<1||a>1000000){out.textContent="Enter N between 1 and 1,000,000.";return;}
    var count=0,cand=1;
    while(count<a){cand++; if(isPrime(cand))count++;}
    out.textContent="The "+a+ordinal(a)+" prime is "+cand+".";
  }else{
    if(a<2){out.textContent="Enter a number of 2 or more.";return;}
    var f=factorize(a), parts=Object.keys(f).map(function(p){return f[p]>1?p+"^"+f[p]:p;});
    out.textContent=a+" = "+parts.join(" x ");
  }
});
function ordinal(n){var s=["th","st","nd","rd"],v=n%100;return s[(v-20)%10]||s[v]||s[0];}
})();

(function(){
