  var nums=inp.value.split(/[\s,;]+/).map(function(s){return parseFloat(s);}).filter(function(n){return isFinite(n);});
  if(!nums.length){status.textContent="Paste numbers to compute statistics.";grid.innerHTML="";return;}
  var n=nums.length, sorted=nums.slice().sort(function(a,b){return a-b;});
  var sum=nums.reduce(function(a,b){return a+b;},0), mean=sum/n;
