(function(){
"use strict";
var inp=document.getElementById("cf-in"), out=document.getElementById("cf-out"),
    mode=document.getElementById("cf-mode"), stats=document.getElementById("cf-stats");
function stripComments(s){return s.replace(/\/\*[\s\S]*?\*\//g,"");}
function beautify(css){
  css=stripComments(css).replace(/\s+/g," ");
  var out="", indent=0, i=0;
  function pad(){return "  ".repeat(indent);}
  while(i<css.length){
    var ch=css[i];
    if(ch==="{"){out=out.replace(/[ ]+$/,"")+" {\n";indent++;out+=pad();i++;}
    else if(ch==="}"){indent=Math.max(0,indent-1);out=out.replace(/[ \n]+$/,"")+"\n"+pad()+"}\n"+pad();i++;}
    else if(ch===";"){out+=";\n"+pad();i++;}
    else if(ch===","){out+=", ";i++;}
    else{out+=ch;i++;}
  }
  return out.replace(/[ \t]+\n/g,"\n").replace(/\n{3,}/g,"\n\n").trim()+"\n";
}
function minify(css){
  css=stripComments(css);
  css=css.replace(/\s+/g," ");
