    playBtn=document.getElementById("aw-play"), audio=document.getElementById("aw-audio");
var actx=null, playing=false;
function fmtDur(s){s=Math.floor(s);var m=Math.floor(s/60);return m+":"+((s%60<10?"0":"")+(s%60));}
fileEl.addEventListener("change",function(){
  var f=fileEl.files[0]; if(!f) return;
  status.textContent="Decoding audio..."; cv.style.display="none"; meta.innerHTML="";
  if(!actx)actx=new (window.AudioContext||window.webkitAudioContext)();
  var rd=new FileReader();
  rd.onload=function(){
    actx.decodeAudioData(rd.result,function(buf){
      draw(buf);
      meta.innerHTML='<div>Duration: <strong>'+fmtDur(buf.duration)+'</strong> ('+buf.duration.toFixed(2)+' s)</div>'+
        '<div>Sample rate: <strong>'+buf.sampleRate+' Hz</strong></div>'+
        '<div>Channels: <strong>'+buf.numberOfChannels+(buf.numberOfChannels===1?" (mono)":buf.numberOfChannels===2?" (stereo)":"")+'</strong></div>'+
        '<div>File size: <strong>'+(f.size/1048576).toFixed(2)+' MB</strong></div>';
