(function(){
"use strict";
function specificity(sel){
  var a=0,b=0,c=0,s=sel;
  s=s.replace(/\/\*[\s\S]*?\*\//g,"");
  var nots=[];
  s=s.replace(/:not\(([^()]*)\)/g,function(m,inner){nots.push(inner);return " ";});
  a+=(s.match(/#[\w-]+/g)||[]).length;
  b+=(s.match(/\.[\w-]+/g)||[]).length;
  b+=(s.match(/\[[^\]]+\]/g)||[]).length;
  var pseudo=s.match(/::?[\w-]+(\([^)]*\))?/g)||[];
  pseudo.forEach(function(p){
    if(p.indexOf("::")===0)c++;
    else if(/^:(before|after|first-line|first-letter|selection|marker|placeholder)$/.test(p))c++;
    else b++;
  });
  var t=s.replace(/#[\w-]+/g," ").replace(/\.[\w-]+/g," ").replace(/\[[^\]]+\]/g," ").replace(/::?[\w-]+(\([^)]*\))?/g," ");
  c+=(t.match(/(^|[\s>+~])([a-zA-Z][\w-]*)/g)||[]).length;
  nots.forEach(function(inner){var r=specificity(inner);a+=r[0];b+=r[1];c+=r[2];});
  return [a,b,c];
}
var inp=document.getElementById("sp-in");
function render(){
  var raw=inp.value.trim();
  var score=document.getElementById("sp-score"), abc=document.getElementById("sp-abc"), br=document.getElementById("sp-break");
  if(!raw){score.textContent="-";abc.textContent="Enter a selector.";br.innerHTML="";return;}
  var parts=raw.split(",").map(function(s){return s.trim();}).filter(Boolean);
  var specs=parts.map(function(p){return {sel:p,sp:specificity(p)};});
  specs.sort(function(x,y){return (y.sp[0]-x.sp[0])||(y.sp[1]-x.sp[1])||(y.sp[2]-x.sp[2]);});
  var top=specs[0].sp, scoreVal=top[0]*100+top[1]*10+top[2];
  score.textContent=scoreVal;
  abc.textContent="Specificity ("+top[0]+", "+top[1]+", "+top[2]+")"+(parts.length>1?" - highest of "+parts.length+" selectors":"")+".";
  br.innerHTML='<div class="result-label">Breakdown</div>'+
    '<div>IDs <strong>'+top[0]+'</strong> (a) - #id selectors</div>'+
    '<div>Classes, attributes, pseudo-classes <strong>'+top[1]+'</strong> (b)</div>'+
    '<div>Elements, pseudo-elements <strong>'+top[2]+'</strong> (c)</div>'+
    (parts.length>1?'<div style="margin-top:8px;font-size:.85rem;opacity:.75">Winner: <code>'+specs[0].sel.replace(/</g,"&lt;")+'</code></div>':"");
}
