function gen(t){
  var fn=pick(FN),ln=pick(LN);
  switch(t){
    case "person": return fn+" "+ln;
    case "email": return (fn+"."+ln+Math.floor(Math.random()*99)+"@example.com").toLowerCase();
    case "phone": return "+1 ("+Math.floor(Math.random()*800+200)+") "+Math.floor(Math.random()*800+200)+"-"+pad(Math.floor(Math.random()*90)+10)+pad(Math.floor(Math.random()*90)+10);
    case "address": return (Math.floor(Math.random()*9000)+100)+" "+pick(ST)+" St, "+pick(CT)+", CA "+(90000+Math.floor(Math.random()*9999));
    case "company": return pick(CO)+(Math.random()<0.5?" Inc":" LLC");
    case "username": return (fn.charAt(0)+ln+Math.floor(Math.random()*999)).toLowerCase();
    case "date": return "2026-"+pad(Math.floor(Math.random()*12)+1)+"-"+pad(Math.floor(Math.random()*28)+1);
    case "lorem":
      var s=[],n=3+Math.floor(Math.random()*3);
      for(var i=0;i<n;i++){var w=[],m=8+Math.floor(Math.random()*8);for(var j=0;j<m;j++)w.push(pick(LW));s.push(w.join(" ")+".");}
      var p=s.join(" "); return p.charAt(0).toUpperCase()+p.slice(1);
