(function(){
  var fa=document.getElementById('pdfc-a'),fb=document.getElementById('pdfc-b'),
      btn=document.getElementById('pdfc-compare'),out=document.getElementById('pdfc-out'),
      st=document.getElementById('pdfc-status');
  if(window.pdfjsLib){pdfjsLib.GlobalWorkerOptions.workerSrc='https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.worker.min.js';}
  function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function extract(file){
    return file.arrayBuffer().then(function(buf){
      return pdfjsLib.getDocument({data:buf}).promise.then(function(doc){
        var ps=[],i;
        for(i=1;i<=doc.numPages;i++){
          ps.push(doc.getPage(i).then(function(page){
            return page.getTextContent().then(function(tc){
              return tc.items.map(function(it){return it.str;}).join(' ');
            });
          }));
        }
        return Promise.all(ps).then(function(pages){
          return {pages:doc.numPages,text:pages.join('\n')};
        });
      });
    });
  }
  function words(t){return (t.toLowerCase().match(/[a-z0-9']+/g)||[]);}
  function uniq(src,other,n){
    var arr=[],k;
    for(k in src){if(!other[k]){arr.push([k,src[k]]);}
    }
    arr.sort(function(a,b){return b[1]-a[1];});
    return arr.slice(0,n);
  }
  btn.addEventListener('click',function(){
    if(!fa.files[0]||!fb.files[0]){out.innerHTML='<p class="sub">Pick two PDF files first.</p>';return;}
    if(!window.pdfjsLib){out.innerHTML='<p class="sub">PDF library failed to load. Check your connection and try again.</p>';return;}
    st.textContent='Reading both PDFs, this can take a few seconds...';
    out.innerHTML='';
    Promise.all([extract(fa.files[0]),extract(fb.files[0])]).then(function(r){
      st.textContent='';
      var wa=words(r[0].text),wb=words(r[1].text),sa={},sb={},i;
      for(i=0;i<wa.length;i++){sa[wa[i]]=(sa[wa[i]]||0)+1;}
      for(i=0;i<wb.length;i++){sb[wb[i]]=(sb[wb[i]]||0)+1;}
      var inter=0,k;
      for(k in sa){if(sb[k]){inter+=Math.min(sa[k],sb[k]);}}
      var union=wa.length+wb.length-inter;
      var sim=union?Math.round(inter/union*1000)/10:0;
      var ua=uniq(sa,sb,10),ub=uniq(sb,sa,10);
      function li(p){return p.length?p.map(function(x){return '<li>'+esc(x[0])+' <span class="sub">x'+x[1]+'</span></li>';}).join(''):'<li><span class="sub">none</span></li>';}
      out.innerHTML=
        '<p style="font-size:2rem;font-weight:700;margin:0 0 4px">'+sim+'% <span class="sub" style="font-size:.9rem;font-weight:400">similar</span></p>'+
        '<div style="height:10px;border-radius:6px;background:var(--border);overflow:hidden;margin-bottom:12px"><div style="height:100%;width:'+sim+'%;background:var(--accent)"></div></div>'+
        '<p><strong>'+esc(fa.files[0].name)+'</strong>: '+r[0].pages+' pages, '+wa.length.toLocaleString()+' words<br>'+
        '<strong>'+esc(fb.files[0].name)+'</strong>: '+r[1].pages+' pages, '+wb.length.toLocaleString()+' words</p>'+
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><div><h3>Only in first PDF</h3><ul>'+li(ua)+'</ul></div>'+
        '<div><h3>Only in second PDF</h3><ul>'+li(ub)+'</ul></div></div>';
    }).catch(function(){
      st.textContent='';
      out.innerHTML='<p class="sub">Could not read one of the PDFs. Make sure both files are valid, non-encrypted PDFs.</p>';
    });
  });
})();

