        if(n.childNodes.length===0){out+=pad+'<'+n.tagName+attrs+'/>\n';}
        else if(n.childNodes.length===1&&n.childNodes[0].nodeType===3){
          out+=pad+'<'+n.tagName+attrs+'>'+n.childNodes[0].textContent.trim()+'</'+n.tagName+'>\n';
        }else{out+=pad+'<'+n.tagName+attrs+'>\n'+pretty(n,ind+1)+pad+'</'+n.tagName+'>\n';}
      }
    }
