      if(!vids.length){st.textContent='No video track found in this file.';busy=false;return;}
      var mime='video/webm';
      if(!MediaRecorder.isTypeSupported(mime)){mime='';}
      var rec=new MediaRecorder(new MediaStream(vids),mime?{mimeType:mime}:undefined);
      var chunks=[];
