(function(){
  var ti=document.getElementById('rl-in'),btn=document.getElementById('rl-go'),
      out=document.getElementById('rl-out'),sm=document.getElementById('rl-sample');
  function syllables(w){
    w=w.toLowerCase().replace(/[^a-z]/g,'');
    if(!w){return 0;}
    if(w.length<=3){return 1;}
    w=w.replace(/(?:[^laeiouy]e|ed|es)$/,'').replace(/^y/,'');
    var m=w.match(/[aeiouy]{1,2}/g);
    return m?m.length:1;
  }
  function easeLabel(s){
    if(s>=90){return 'Very easy: a 5th grader understands it.';}
    if(s>=80){return 'Easy: conversational plain English.';}
    if(s>=70){return 'Fairly easy: understood by most teens.';}
    if(s>=60){return 'Standard: plain adult reading level.';}
    if(s>=50){return 'Fairly difficult: some college level.';}
    if(s>=30){return 'Difficult: college level.';}
    return 'Very difficult: graduate level.';
  }
  function gradeLabel(g){
    if(g<1){return 'Below 1st grade level.';}
    if(g<=6){return 'Elementary school level.';}
    if(g<=9){return 'Middle school level.';}
    if(g<=12){return 'High school level.';}
    if(g<=16){return 'College level.';}
    return 'Graduate level.';
  }
  function analyze(){
    var t=ti.value.trim();
    if(t.split(/\s+/).length<10){out.innerHTML='<p class="sub">Paste at least 10 words for a meaningful score.</p>';return;}
    var sens=t.split(/[.!?]+/).map(function(s){return s.trim();}).filter(Boolean);
    var ws=t.toLowerCase().match(/[a-z']+/g)||[];
    var syl=0,complex=0,i;
    for(i=0;i<ws.length;i++){
      var sy=syllables(ws[i]);syl+=sy;
      if(sy>=3&&!/[A-Z]/.test(ws[i])){complex++;}
    }
    var w=ws.length,sn=Math.max(1,sens.length);
    var wps=w/sn,spw=syl/w;
    var ease=206.835-1.015*wps-84.6*spw;
    var grade=0.39*wps+11.8*spw-15.59;
    var fog=0.4*(wps+100*(complex/w));
    function row(name,val,note){
      return '<div style="padding:10px 0;border-bottom:1px solid var(--border)"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><strong>'+name+'</strong><span style="font-size:1.25rem;font-weight:700">'+val+'</span></div><p class="sub" style="margin:4px 0 0">'+note+'</p></div>';
    }
    out.innerHTML=
      '<p class="sub">'+w+' words, '+sn+' sentences, '+syl+' syllables.</p>'+
      row('Flesch Reading Ease',ease.toFixed(1),easeLabel(ease))+
      row('Flesch-Kincaid Grade Level',grade.toFixed(1),gradeLabel(grade))+
      row('Gunning Fog Index',fog.toFixed(1),'Roughly '+Math.max(1,Math.round(fog))+' years of schooling needed.');
  }
  btn.addEventListener('click',analyze);
  ti.addEventListener('input',function(){if(ti.value.trim().split(/\s+/).length>=10){analyze();}});
  sm.addEventListener('click',function(){
    ti.value='The quick brown fox jumps over the lazy dog. Readability formulas measure how easy a text is to read. They count sentence length and syllables per word. Short sentences and simple words score as easier. Writers use these scores to match their audience.';
    analyze();
  });
})();

