(function(){
  var ti=document.getElementById('cj-in'),to=document.getElementById('cj-out'),
      btn=document.getElementById('cj-go'),dir=document.getElementById('cj-dir');
  function parseCSV(s){
    var rows=[],row=[],cur='',q=false,i,c;
    for(i=0;i<s.length;i++){
      c=s[i];
      if(q){
        if(c==='"'){if(s[i+1]==='"'){cur+='"';i++;}else{q=false;}}
        else{cur+=c;}
      }else if(c==='"'){q=true;}
      else if(c===','){row.push(cur);cur='';}
      else if(c==='\n'||c==='\r'){
        if(c==='\r'&&s[i+1]==='\n'){i++;}
        row.push(cur);cur='';rows.push(row);row=[];
      }else{cur+=c;}
    }
    if(cur!==''||row.length){row.push(cur);rows.push(row);}
    return rows.filter(function(r){return !(r.length===1&&r[0]==='');});
  }
  function csvCell(v){
    v=String(v==null?'':v);
    return /[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;
  }
  function csvToJson(s){
    var rows=parseCSV(s);
    if(rows.length<2){throw new Error('Need a header row plus at least one data row.');}
    var head=rows[0],out=[],i,j;
    for(i=1;i<rows.length;i++){
      var o={};
      for(j=0;j<head.length;j++){o[head[j]]=rows[i][j]!==undefined?rows[i][j]:'';}
      out.push(o);
    }
    return JSON.stringify(out,null,2);
  }
  function jsonToCsv(s){
    var d=JSON.parse(s);
    if(!Array.isArray(d)){d=[d];}
    var keys=[],i,j;
    d.forEach(function(o){
      Object.keys(o).forEach(function(k){if(keys.indexOf(k)<0){keys.push(k);}});
    });
    var lines=[keys.map(csvCell).join(',')];
    d.forEach(function(o){
      lines.push(keys.map(function(k){
        var v=o[k];
        if(v&&typeof v==='object'){v=JSON.stringify(v);}
        return csvCell(v);
      }).join(','));
    });
    return lines.join('\n');
  }
  btn.addEventListener('click',function(){
    var s=ti.value.trim();
    if(!s){dir.textContent='Paste some data first.';return;}
    try{
      var looksJson=/^[\[{]/.test(s);
      var res=looksJson?jsonToCsv(s):csvToJson(s);
      to.value=res;
      dir.textContent=looksJson?'Detected JSON, converted to CSV.':'Detected CSV, converted to JSON.';
    }catch(e){
      dir.textContent='Error: '+e.message;
      to.value='';
    }
  });
  document.getElementById('cj-sample').addEventListener('click',function(){
    ti.value='name,age,city\nAda,36,"New York, NY"\nGrace,41,London\n"Katherine J.",28,Paris';
  });
  document.getElementById('cj-copy').addEventListener('click',function(){
    if(!to.value){return;}
    to.select();
    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(to.value);}
    else{document.execCommand('copy');}
  });
  document.getElementById('cj-dl').addEventListener('click',function(){
    if(!to.value){return;}
    var looksJson=/^[\[{]/.test(ti.value.trim());
    var blob=new Blob([to.value],{type:'text/plain'});
    var a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download=looksJson?'converted.csv':'converted.json';
    a.click();setTimeout(function(){URL.revokeObjectURL(a.href);},2000);
  });
})();

