    return rows.filter(function(r){return !(r.length===1&&r[0]==='');});
  }
  function cell(v,d){
    v=String(v==null?'':v);
    var needs=v.indexOf('"')>=0||v.indexOf(d)>=0||v.indexOf('\n')>=0||v.indexOf('\r')>=0;
    return needs?'"'+v.replace(/"/g,'""')+'"':v;
  }
