    var from=tabs>commas?'\t':',',toD=from==='\t'?',':'\t';
    var rows=parseD(s,from);
    to.value=rows.map(function(r){return r.map(function(v){return cell(v,toD);}).join(toD);}).join('\n');
    lastExt=toD==='\t'?'tsv':'csv';
    msg.textContent='Detected '+(from==='\t'?'TSV':'CSV')+', converted to '+(toD==='\t'?'TSV':'CSV')+'. '+rows.length+' rows.';
  });
  document.getElementById('ct-copy').addEventListener('click',function(){
