    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(to.value);}
    else{document.execCommand('copy');}
  });
  document.getElementById('ct-dl').addEventListener('click',function(){
    if(!to.value){return;}
    var blob=new Blob([to.value],{type:'text/plain'});
    var a=document.createElement('a');
    a.href=URL.createObjectURL(blob);a.download='converted.'+lastExt;a.click();
    setTimeout(function(){URL.revokeObjectURL(a.href);},2000);
  });
})();

