(function(){
  var btn=document.getElementById('fr-go'),out=document.getElementById('fr-out');
  function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){var t=a%b;a=b;b=t;}return a||1;}
  function parse(s){
    s=String(s).trim();
    if(!s){throw new Error('empty input');}
    var neg=/^-/.test(s);s=s.replace(/^[+-]/,'');
    var m=/^(\d+)\s+(\d+)\s*\/\s*(\d+)$/.exec(s),whole=0,num,den;
    if(m){whole=+m[1];num=+m[2];den=+m[3];}
    else if((m=/^(\d+)\s*\/\s*(\d+)$/.exec(s))){num=+m[1];den=+m[2];}
    else if((m=/^(\d+(\.\d+)?)$/.exec(s))){
      var v=parseFloat(m[1]);whole=Math.floor(v);var dec=v-whole;
      den=1000000;num=Math.round(dec*den);
    }
    else{throw new Error('"'+s+'" is not a valid fraction');}
    if(!den){throw new Error('denominator cannot be zero');}
    num=whole*den+num;
    if(neg){num=-num;}
    var g=gcd(num,den);
    return {n:num/g,d:den/g};
  }
  function fmt(f){
    var g=gcd(f.n,f.d),n=f.n/g,d=f.d/g;
    var frac=d===1?String(n):(n+'/'+d);
    var mixed='';
    if(d!==1&&Math.abs(n)>d){
      var w=Math.trunc(n/d),r=Math.abs(n%d);
      mixed=(w!==0?w+' ':'')+(r?r+'/'+d:'');
      if(n<0&&w===0){mixed='-'+mixed;}
    }
    var dec=(n/d);
    return {frac:frac,mixed:mixed||frac,dec:Math.round(dec*1000000)/1000000};
  }
  btn.addEventListener('click',function(){
    try{
      var A=parse(document.getElementById('fr-a').value),
          B=parse(document.getElementById('fr-b').value),
          op=document.getElementById('fr-op').value,res;
      if(op==='add'){res={n:A.n*B.d+A.d*B.n,d:A.d*B.d};}
      else if(op==='sub'){res={n:A.n*B.d-A.d*B.n,d:A.d*B.d};}
      else if(op==='mul'){res={n:A.n*B.n,d:A.d*B.d};}
      else{if(B.n===0){throw new Error('cannot divide by zero');}res={n:A.n*B.d,d:A.d*B.n};if(res.d<0){res.n=-res.n;res.d=-res.d;}}
      var f=fmt(res);
      out.innerHTML='<p style="font-size:1.6rem;font-weight:700;margin:0 0 6px">'+f.frac+'</p>'+
        '<p>As a mixed number: <strong>'+f.mixed+'</strong></p>'+
        '<p class="sub">Decimal equivalent: '+f.dec+'</p>';
    }catch(e){
      out.innerHTML='<p class="sub">Error: '+e.message+'. Use forms like 3/4, 2, or 1 1/2.</p>';
    }
  });
})();

(function(){
  var mode=document.getElementById('pr-mode'),btn=document.getElementById('pr-go'),
      out=document.getElementById('pr-out'),hint=document.getElementById('pr-hint');
  var w1=document.getElementById('pr-w1'),w2=document.getElementById('pr-w2'),
      w3=document.getElementById('pr-w3'),w4=document.getElementById('pr-w4'),
      la=w1.querySelector('label'),lb=w2.querySelector('label');
  function comb(n,k){
    if(k<0||k>n){return 0;}
    k=Math.min(k,n-k);var c=1,i;
    for(i=0;i<k;i++){c=c*(n-i)/(i+1);}
    return c;
  }
  function fmtP(p){
    var pct=(p*100);
    var ps=pct>=10?pct.toFixed(2):pct.toFixed(4);
    return '<p style="font-size:2rem;font-weight:700;margin:0 0 6px">'+ps+'%</p><p class="sub">Decimal: '+p.toPrecision(6)+' &middot; odds: 1 in '+(p>0?(1/p).toFixed(2):'&infin;')+'</p>';
  }
  mode.addEventListener('change',function(){
    var m=mode.value,single=m==='single';
    w1.style.display='block';
    w2.style.display=single?'block':'none';
    w3.style.display=single?'none':'block';
    w4.style.display=m==='binom'?'block':'none';
    la.textContent=single?'Favorable outcomes':'Success chance per trial (%)';
    lb.textContent='Total outcomes';
    hint.textContent=single?'Probability of rolling a 6 on one die.':(m==='repeat'?'Chance of at least one win in n tries at the given odds.':'Chance of exactly k successes in n independent trials.');
  });
  btn.addEventListener('click',function(){
    var m=mode.value,html='';
    if(m==='single'){
      var fav=parseFloat(document.getElementById('pr-a').value),
          tot=parseFloat(document.getElementById('pr-b').value);
      if(!(tot>0)||fav<0){out.innerHTML='<p class="sub">Enter a positive total and a non-negative favorable count.</p>';return;}
      if(fav>tot){out.innerHTML='<p class="sub">Favorable outcomes cannot exceed total outcomes.</p>';return;}
      html=fmtP(fav/tot);
    }else{
      var pc=parseFloat(document.getElementById('pr-a').value),
          n=Math.round(parseFloat(document.getElementById('pr-n').value||'0'));
      if(!(pc>=0&&pc<=100)||!(n>=1)){out.innerHTML='<p class="sub">Enter a chance between 0 and 100, and at least 1 trial.</p>';return;}
      var p=pc/100;
      if(m==='repeat'){
        html=fmtP(1-Math.pow(1-p,n));
        html+='<p class="sub">Formula: 1 - (1 - p)<sup>'+n+'</sup></p>';
      }else{
        var k=Math.round(parseFloat(document.getElementById('pr-k').value||'0'));
        if(k<0||k>n){out.innerHTML='<p class="sub">Successes (k) must be between 0 and n.</p>';return;}
        var bp=comb(n,k)*Math.pow(p,k)*Math.pow(1-p,n-k);
        html=fmtP(bp);
        html+='<p class="sub">C('+n+','+k+') = '+Math.round(comb(n,k)).toLocaleString()+' combinations.</p>';
      }
    }
    out.innerHTML=html;
  });
})();

