(function(){
  var btn=document.getElementById('sc-go'),out=document.getElementById('sc-out');
  function calc(){
    var w=Math.max(0,parseFloat(document.getElementById('sc-w').value||'0')),
        l=Math.max(0,parseFloat(document.getElementById('sc-l').value||'0')),
        wd=Math.max(0,parseFloat(document.getElementById('sc-wd').value||'0')),
        h=Math.max(0,parseFloat(document.getElementById('sc-h').value||'0')),
        rate=Math.max(0,parseFloat(document.getElementById('sc-rate').value||'0')),
        div=parseFloat(document.getElementById('sc-div').value||'5000');
    var vol=(l*wd*h)/div;
    var charge=Math.max(w,vol);
    var cost=charge*rate;
    var volWins=vol>w;
