(function(){
  var ti=document.getElementById('hs-in'),btn=document.getElementById('hs-go'),out=document.getElementById('hs-out');
  function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function check(){
    var html=ti.value;
    if(!html.trim()){out.innerHTML='<p class="sub">Paste some HTML first.</p>';return;}
    var doc=new DOMParser().parseFromString(html,'text/html');
    var hs=doc.querySelectorAll('h1,h2,h3,h4,h5,h6');
    if(!hs.length){out.innerHTML='<p class="sub">No headings found in this HTML.</p>';return;}
    var issues=[],prev=0,h1count=0,rows='';
    hs.forEach(function(h,i){
      var lvl=parseInt(h.tagName[1],10);
      var text=(h.textContent||'').trim().replace(/\s+/g,' ').slice(0,90);
      if(lvl===1){h1count++;}
      if(!text){issues.push('Heading #'+(i+1)+' ('+h.tagName+') is empty.');}
      if(i===0&&lvl!==1){issues.push('First heading is '+h.tagName+', not H1. Pages should start with a single H1.');}
      if(prev&&lvl>prev+1){issues.push('Skipped level: '+('H'+prev)+' followed by '+h.tagName+' ("'+text.slice(0,40)+'").');}
      prev=lvl;
      rows+='<div style="padding:4px 0 4px '+(lvl-1)*22+'px;border-bottom:1px solid var(--border)"><span class="mono" style="font-size:.75rem;background:var(--border);border-radius:4px;padding:1px 6px;margin-right:8px">H'+lvl+'</span>'+(esc(text)||'<span class="sub">(empty)</span>')+'</div>';
    });
    if(h1count===0){issues.unshift('No H1 found. Every page needs exactly one H1.');}
    if(h1count>1){issues.unshift('Found '+h1count+' H1 tags. Use exactly one H1 per page.');}
    var ih=issues.length?'<h3>Issues ('+issues.length+')</h3><ul>'+issues.map(function(x){return '<li>'+esc(x)+'</li>';}).join('')+'</ul>':'<p><strong>No issues found.</strong> Clean heading hierarchy.</p>';
    out.innerHTML='<h3>Outline ('+hs.length+' headings)</h3>'+rows+ih;
  }
  btn.addEventListener('click',check);
  document.getElementById('hs-sample').addEventListener('click',function(){
    ti.value='<h1>Guide to sourdough</h1><h2>Ingredients</h2><h4>Flour types</h4><h2>Method</h2><h3>Mixing</h3><h3></h3>';
    check();
  });
})();

(function(){
