(function(){
  var KEY='mth-cc-posts';
  var posts=[];
  try{posts=JSON.parse(localStorage.getItem(KEY)||'[]');}catch(e){posts=[];}
  var monthEl=document.getElementById('cc-month'),grid=document.getElementById('cc-grid'),list=document.getElementById('cc-list');
  var now=new Date();
  monthEl.value=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
  var PLAT={Instagram:'#e1306c',TikTok:'#111111',YouTube:'#ff0000',Facebook:'#1877f2',X:'#000000',LinkedIn:'#0a66c2',Blog:'#7c3aed',Newsletter:'#059669'};
  function save(){try{localStorage.setItem(KEY,JSON.stringify(posts));}catch(e){}}
  function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function curYM(){var p=monthEl.value.split('-');return {y:+p[0],m:+p[1]-1};}
  function render(){
    var ym=curYM(),first=new Date(ym.y,ym.m,1),days=new Date(ym.y,ym.m+1,0).getDate();
    var mp=posts.filter(function(p){return p.y===ym.y&&p.m===ym.m;});
    var byDay={};
    mp.forEach(function(p){(byDay[p.d]=byDay[p.d]||[]).push(p);});
    var cells=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(function(d){return '<div class="sub" style="text-align:center;font-size:.75rem">'+d+'</div>';}).join('');
    for(var i=0;i<first.getDay();i++){cells+='<div></div>';}
    for(var d=1;d<=days;d++){
      var dots=(byDay[d]||[]).map(function(p){
        return '<span title="'+esc(p.plat+': '+p.topic)+'" style="display:inline-block;width:10px;height:10px;border-radius:50%;background:'+(PLAT[p.plat]||'#7c3aed')+';margin:1px"></span>';
      }).join('');
      cells+='<div style="border:1px solid var(--border);border-radius:6px;min-height:52px;padding:4px;font-size:.8rem"><strong>'+d+'</strong><div>'+dots+'</div></div>';
    }
    grid.innerHTML='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px">'+cells+'</div>';
    mp.sort(function(a,b){return a.d-b.d;});
    if(!mp.length){list.innerHTML='<p class="sub">No posts planned yet.</p>';return;}
    list.innerHTML='';
    mp.forEach(function(p,idx){
      var row=document.createElement('div');
      row.style.cssText='display:flex;gap:10px;align-items:center;padding:6px 0;border-bottom:1px solid var(--border)';
      row.innerHTML='<strong style="min-width:64px">'+ym.m+1+'/'+p.d+'</strong><span class="mono" style="font-size:.75rem;background:var(--border);border-radius:4px;padding:1px 6px">'+esc(p.plat)+'</span><span style="flex:1">'+esc(p.topic)+'</span>';
      var del=document.createElement('button');del.className='btn btn-outline';del.textContent='x';del.style.padding='2px 8px';
      del.onclick=function(){posts.splice(posts.indexOf(p),1);save();render();};
      row.appendChild(del);list.appendChild(row);
    });
  }
  document.getElementById('cc-add').addEventListener('click',function(){
    var ym=curYM();
    var d=Math.max(1,Math.min(31,parseInt(document.getElementById('cc-day').value||'1',10)));
    var topic=document.getElementById('cc-topic').value.trim();
    if(!topic){return;}
    posts.push({y:ym.y,m:ym.m,d:d,plat:document.getElementById('cc-plat').value,topic:topic});
    document.getElementById('cc-topic').value='';
    save();render();
  });
  document.getElementById('cc-csv').addEventListener('click',function(){
    var ym=curYM();
    var mp=posts.filter(function(p){return p.y===ym.y&&p.m===ym.m;}).sort(function(a,b){return a.d-b.d;});
    if(!mp.length){return;}
    function q(s){return '"'+String(s).replace(/"/g,'""')+'"';}
    var csv='date,platform,topic\n'+mp.map(function(p){return (ym.m+1)+'/'+p.d+'/'+ym.y+','+q(p.plat)+','+q(p.topic);}).join('\n');
    var blob=new Blob([csv],{type:'text/csv'});
    var a=document.createElement('a');
    a.href=URL.createObjectURL(blob);a.download='content-calendar.csv';a.click();
    setTimeout(function(){URL.revokeObjectURL(a.href);},2000);
  });
  document.getElementById('cc-clear').addEventListener('click',function(){
    var ym=curYM();
    posts=posts.filter(function(p){return !(p.y===ym.y&&p.m===ym.m);});
    save();render();
  });
  monthEl.addEventListener('change',render);
  render();
})();

(function(){
  var cv=document.getElementById('qi-cv'),ctx=cv.getContext('2d');
  var BGS=[
    ['#2b1055','#7597de'],['#0f2027','#2c5364'],['#ff512f','#dd2476'],
    ['#134e5e','#71b280'],['#232526','#414345'],['#f5f0e6','#e8dcc3']
  ];
  function wrap(text,maxW){
    var words=text.split(/\s+/),lines=[],line='';
    words.forEach(function(w){
      var t=line?line+' '+w:w;
      if(ctx.measureText(t).width>maxW&&line){lines.push(line);line=w;}
      else{line=t;}
    });
    if(line){lines.push(line);}
    return lines;
  }
  function draw(){
    var bg=BGS[parseInt(document.getElementById('qi-bg').value,10)]||BGS[0];
    var tc=document.getElementById('qi-tc').value;
    var size=parseInt(document.getElementById('qi-size').value,10);
    var quote=document.getElementById('qi-text').value.trim()||'Your quote appears here.';
    var author=document.getElementById('qi-author').value.trim();
    var g=ctx.createLinearGradient(0,0,1080,1080);
    g.addColorStop(0,bg[0]);g.addColorStop(1,bg[1]);
    ctx.fillStyle=g;ctx.fillRect(0,0,1080,1080);
    ctx.fillStyle=tc;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.font='700 160px Georgia, serif';
    ctx.fillText('\u201C',540,180);
    ctx.font='italic 600 '+size+'px Georgia, serif';
    var lines=wrap('\u201C'+quote+'\u201D',880);
    var lh=size*1.35,startY=540-((lines.length-1)*lh)/2-20;
    lines.forEach(function(l,i){ctx.fillText(l,540,startY+i*lh);});
    if(author){
      ctx.font='400 44px Georgia, serif';
      ctx.fillText('\u2014 '+author,540,startY+lines.length*lh+40);
    }
  }
  ['qi-text','qi-author','qi-bg','qi-tc','qi-size'].forEach(function(id){
    document.getElementById(id).addEventListener('input',draw);
  });
  document.getElementById('qi-sample').addEventListener('click',function(){
    document.getElementById('qi-text').value='Nothing is impossible. The word itself says: I am possible!';
    document.getElementById('qi-author').value='Audrey Hepburn';
    draw();
  });
  document.getElementById('qi-dl').addEventListener('click',function(){
    var a=document.createElement('a');
    a.download='quote.png';a.href=cv.toDataURL('image/png');a.click();
  });
  draw();
})();

(function(){
