(function(){
  var drop=document.getElementById('fi-drop'),fi=document.getElementById('fi-file'),
      out=document.getElementById('fi-out'),st=document.getElementById('fi-status');
  function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function human(b){
    if(b<1024){return b+' B';}
    var u=['KB','MB','GB','TB'],i=-1;
    do{b/=1024;i++;}while(b>=1024&&i<u.length-1);
    return b.toFixed(2)+' '+u[i];
  }
  function hex(buf){
    return Array.prototype.map.call(new Uint8Array(buf),function(x){return ('0'+x.toString(16)).slice(-2);}).join('');
  }
  function inspect(file){
    st.textContent='Reading '+file.name+'...';
    var ext=(file.name.split('.').pop()||'').toLowerCase();
    var html='<table style="width:100%;border-collapse:collapse"><tbody>'+
      '<tr><td style="padding:6px;border-bottom:1px solid var(--border)"><strong>Name</strong></td><td style="padding:6px;border-bottom:1px solid var(--border)">'+esc(file.name)+'</td></tr>'+
      '<tr><td style="padding:6px;border-bottom:1px solid var(--border)"><strong>Size</strong></td><td style="padding:6px;border-bottom:1px solid var(--border)">'+human(file.size)+' ('+file.size.toLocaleString()+' bytes)</td></tr>'+
      '<tr><td style="padding:6px;border-bottom:1px solid var(--border)"><strong>MIME type</strong></td><td style="padding:6px;border-bottom:1px solid var(--border)">'+esc(file.type||'unknown')+'</td></tr>'+
      '<tr><td style="padding:6px;border-bottom:1px solid var(--border)"><strong>Extension</strong></td><td style="padding:6px;border-bottom:1px solid var(--border)">'+esc(ext)+'</td></tr>'+
      '<tr><td style="padding:6px;border-bottom:1px solid var(--border)"><strong>Last modified</strong></td><td style="padding:6px;border-bottom:1px solid var(--border)">'+new Date(file.lastModified).toLocaleString()+'</td></tr>'+
      '</tbody></table><p class="sub">Computing SHA-256...</p>';
    out.innerHTML=html;
    file.arrayBuffer().then(function(buf){
      return crypto.subtle.digest('SHA-256',buf).then(function(d){
        return {hash:hex(d),buf:buf};
      });
    }).then(function(r){
      st.textContent='';
      var h='<table style="width:100%;border-collapse:collapse"><tbody>'+
        '<tr><td style="padding:6px;border-bottom:1px solid var(--border)"><strong>SHA-256</strong></td><td style="padding:6px;border-bottom:1px solid var(--border);word-break:break-all"><span class="mono" style="font-size:.75rem">'+r.hash+'</span></td></tr>'+
        '</tbody></table>';
      var textTypes=/^(text\/|application\/(json|xml|javascript))/;
      if(textTypes.test(file.type)||/^(txt|md|csv|log|json|xml|html|css|js|ts|py|yml|yaml)$/.test(ext)){
        var txt=new TextDecoder().decode(r.buf).slice(0,2000);
        h+='<h3>Text preview (first 2000 chars)</h3><pre class="mono" style="white-space:pre-wrap;word-break:break-word;font-size:.8rem;background:var(--border);border-radius:8px;padding:12px;max-height:240px;overflow:auto">'+esc(txt)+'</pre>';
      }else if(file.type.indexOf('image/')===0){
        h+='<h3>Image preview</h3><img alt="preview" style="max-width:100%;max-height:240px;border-radius:8px" src="'+URL.createObjectURL(file)+'">';
      }
      out.innerHTML=out.innerHTML.replace(/<p class="sub">Computing SHA-256\.\.\.<\/p>/,'')+h;
    }).catch(function(){
      st.textContent='Could not read this file.';
    });
  }
  drop.addEventListener('click',function(){fi.click();});
  fi.addEventListener('change',function(){if(fi.files[0]){inspect(fi.files[0]);}});
  ['dragover','dragenter'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();drop.style.borderColor='var(--accent)';});});
  ['dragleave','drop'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();drop.style.borderColor='';});});
  drop.addEventListener('drop',function(e){
    if(e.dataTransfer.files[0]){inspect(e.dataTransfer.files[0]);}
  });
})();

