(function(){
  var out=document.getElementById('cu-out');
  function val(id){return parseFloat(document.getElementById(id).value)||0;}
  function calc(){
    var v=val('cu-val'),from=document.getElementById('cu-from').value,
        base=Math.max(1,val('cu-base')),vw=Math.max(1,val('cu-vw')),
        vh=Math.max(1,val('cu-vh')),parent=Math.max(1,val('cu-parent'));
    var px;
    switch(from){
      case 'px':px=v;break;
      case 'rem':px=v*base;break;
      case 'em':px=v*base;break;
      case 'pt':px=v*96/72;break;
      case 'pc':px=v*16;break;
      case 'in':px=v*96;break;
      case 'cm':px=v*96/2.54;break;
      case 'mm':px=v*96/25.4;break;
      case 'pct':px=v/100*parent;break;
      case 'vw':px=v/100*vw;break;
      case 'vh':px=v/100*vh;break;
      default:px=v;
    }
    function r(n){return Math.round(n*10000)/10000;}
    var rows=[
      ['px',r(px)],['rem',r(px/base)],['em',r(px/base)],
      ['pt',r(px*72/96)],['pc',r(px/16)],['in',r(px/96)],
      ['cm',r(px*2.54/96)],['mm',r(px*25.4/96)],
      ['%',r(px/parent*100)],['vw',r(px/vw*100)],['vh',r(px/vh*100)]
    ];
    var html='<table style="width:100%;border-collapse:collapse"><tbody>';
    rows.forEach(function(x){
      var hl=x[0]===from||(from==='pct'&&x[0]==='%');
      html+='<tr'+(hl?' style="background:rgba(124,58,237,.08)"':'')+'><td style="padding:6px;border-bottom:1px solid var(--border)"><strong>'+x[0]+'</strong></td><td class="mono" style="padding:6px;border-bottom:1px solid var(--border);font-size:1rem">'+x[1].toLocaleString()+'</td></tr>';
    });
    out.innerHTML=html+'</tbody></table>';
  }
  ['cu-val','cu-from','cu-base','cu-vw','cu-vh','cu-parent'].forEach(function(id){
    document.getElementById(id).addEventListener('input',calc);
  });
  calc();
})();

