(function(){
  var grid=document.getElementById('tg-grid'),out=document.getElementById('tg-out'),fmt='html';
  function escH(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;');}
  function data(){
    var rows=[];
    grid.querySelectorAll('tr').forEach(function(tr){
      var r=[];
      tr.querySelectorAll('th,td').forEach(function(c){r.push(c.textContent);});
      rows.push(r);
    });
    return rows;
  }
  function build(){
    var R=Math.max(1,Math.min(30,parseInt(document.getElementById('tg-r').value||'3',10))),
        C=Math.max(1,Math.min(12,parseInt(document.getElementById('tg-c').value||'3',10))),
        head=document.getElementById('tg-head').checked;
    var t=document.createElement('table');
    t.style.cssText='border-collapse:collapse;min-width:100%';
    for(var i=0;i<R;i++){
      var tr=document.createElement('tr');
      for(var j=0;j<C;j++){
        var c=document.createElement(head&&i===0?'th':'td');
        c.contentEditable='true';
        c.textContent=(head&&i===0)?'Header '+(j+1):'';
        c.style.cssText='border:1px solid var(--border);padding:8px;min-width:90px';
        tr.appendChild(c);
      }
      t.appendChild(tr);
    }
    grid.innerHTML='';grid.appendChild(t);
    render();
  }
  function render(){
    var rows=data();
    var head=document.getElementById('tg-head').checked;
    var border=document.getElementById('tg-border').checked;
    if(fmt==='html'){
      var h='<table'+(border?' border="1"':'')+'>\n';
      rows.forEach(function(r,i){
        var tag=(head&&i===0)?'th':'td';
        h+='  <tr>\n'+r.map(function(v){return '    <'+tag+'>'+escH(v)+'</'+tag+'>';}).join('\n')+'\n  </tr>\n';
      });
      out.value=h+'</table>';
    }else if(fmt==='md'){
      function cell(v){return String(v).replace(/\|/g,'\\|').replace(/\n/g,' ');}
      var lines=[ '| '+rows[0].map(cell).join(' | ')+' |','| '+rows[0].map(function(){return '---';}).join(' | ')+' |'];
      rows.slice(1).forEach(function(r){lines.push('| '+r.map(cell).join(' | ')+' |');});
      out.value=lines.join('\n');
    }else{
      function q(v){v=String(v);return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;}
      out.value=rows.map(function(r){return r.map(q).join(',');}).join('\n');
    }
  }
  document.getElementById('tg-build').addEventListener('click',build);
  document.getElementById('tg-head').addEventListener('change',build);
  grid.addEventListener('input',render);
  document.querySelectorAll('[data-fmt]').forEach(function(b){
    b.addEventListener('click',function(){
      fmt=b.getAttribute('data-fmt');render();
    });
  });
  document.getElementById('tg-border').addEventListener('change',render);
  document.getElementById('tg-copy').addEventListener('click',function(){
    if(!out.value){return;}
    out.select();
    if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(out.value);}
    else{document.execCommand('copy');}
  });
  build();
})();

