  for(i=0;i<lines.length;i++){
    var m=lines[i].match(/^[ \t]+/);lead=m?m[0]:"";var rest=lines[i].slice(lead.length);
    var hasTab=lead.indexOf("\t")>=0,hasSp=lead.indexOf(" ")>=0;
