  function term(){var x=fact();while(peek()==="*"||peek()==="/"||peek()==="%"){var o=t[p++];var y=fact();if(o==="*")x*=y;else if(o==="/"){if(y===0)throw "div0";x/=y;}else x%=y;}return x;}
  function fact(){var tk=peek();if(tk==="+"||tk==="-"){p++;var x=fact();return tk==="-"?-x:x;}if(typeof tk==="number"){p++;return tk;}throw "err";}
  var r=expr2();if(p<t.length)throw "err";return r;
