(function(){
"use strict";
var P="txtfileconv";
function $(id){return document.getElementById(P+"-"+id);}
var text=null,fileName="converted.txt",outBlob=null;
function status(t,ok){var s=$("status");s.textContent=t;s.style.borderColor=ok?"var(--ok)":"";}
var drop=$("drop"),fi=$("file");
drop.addEventListener("click",function(){fi.click();});
drop.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();fi.click();}});
drop.addEventListener("dragover",function(e){e.preventDefault();drop.style.borderColor="var(--accent)";});
drop.addEventListener("dragleave",function(){drop.style.borderColor="";});
drop.addEventListener("drop",function(e){e.preventDefault();drop.style.borderColor="";if(e.dataTransfer.files[0])load(e.dataTransfer.files[0]);});
fi.addEventListener("change",function(){if(fi.files[0])load(fi.files[0]);});
function load(f){
  fileName=f.name;
  var r=new FileReader();
  r.onload=function(){
    var bytes=new Uint8Array(r.result),enc="utf-8";
    if(bytes.length>=3&&bytes[0]===0xEF&&bytes[1]===0xBB&&bytes[2]===0xBF)enc="utf-8";
    else if(bytes.length>=2&&bytes[0]===0xFF&&bytes[1]===0xFE)enc="utf-16le";
    else if(bytes.length>=2&&bytes[0]===0xFE&&bytes[1]===0xFF)enc="utf-16be";
    try{text=new TextDecoder(enc).decode(r.result);}catch(e){try{text=new TextDecoder("windows-1252").decode(r.result);}catch(e2){status("Could not decode that file as text.",false);return;}}
    text=text.replace(/^\uFEFF/,"");
    $("label").textContent=f.name+" ("+(f.size/1024).toFixed(1)+" KB)";
    $("go").disabled=false;$("dl").disabled=true;
    status("Loaded ("+enc.toUpperCase()+"). Choose target format and press Convert.",true);
  };
  r.readAsArrayBuffer(f);
}
function encode(t,enc){
  var le=$("le").value;
  t=t.replace(/\r\n|\r|\n/g,le==="lf"?"\n":le==="crlf"?"\r\n":"\r");
  var bytes;
  if(enc==="utf8"||enc==="utf8bom"){
    bytes=new TextEncoder().encode(t);
    if(enc==="utf8bom"){var b=new Uint8Array(bytes.length+3);b[0]=0xEF;b[1]=0xBB;b[2]=0xBF;b.set(bytes,3);bytes=b;}
    return {bytes:bytes,mime:"text/plain;charset=utf-8"};
  }
  var n=t.length,out=new Uint8Array(n*2+2),i,c;
  var le16=enc==="utf16le";
  out[0]=le16?0xFF:0xFE;out[1]=le16?0xFE:0xFF;
  for(i=0;i<n;i++){c=t.charCodeAt(i);if(le16){out[2+i*2]=c&0xFF;out[2+i*2+1]=c>>8;}else{out[2+i*2]=c>>8;out[2+i*2+1]=c&0xFF;}}
  return {bytes:out,mime:"text/plain;charset=utf-16"};
}
$("go").addEventListener("click",function(){
  if(text===null)return;
  var r=encode(text,$("enc").value);
  outBlob=new Blob([r.bytes],{type:r.mime});
  $("dl").disabled=false;
  status("Converted: "+$("le").selectedOptions[0].textContent+" / "+$("enc").selectedOptions[0].textContent+". Press Download.",true);
});
$("dl").addEventListener("click",function(){
  if(!outBlob)return;
  var a=document.createElement("a");a.href=URL.createObjectURL(outBlob);a.download=fileName;
  document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},400);
});
$("clear").addEventListener("click",function(){text=null;outBlob=null;fi.value="";$("label").textContent="Drop text file here";$("go").disabled=true;$("dl").disabled=true;status("Choose a text file to start.",false);});
})();

(function(){
"use strict";
var P="emailval";
function $(id){return document.getElementById(P+"-"+id);}
function checkSyntax(e){
  var issues=[];
  if(e.length>254)issues.push("over 254 characters total");
  var parts=e.split("@");
  if(parts.length!==2){issues.push(parts.length<2?"missing @":"more than one @");return issues;}
  var local=parts[0],dom=parts[1].toLowerCase();
  if(!local)issues.push("empty local part");
  if(local.length>64)issues.push("local part over 64 characters");
  if(/^\.|\.$|\.\./.test(local))issues.push("dots at start/end or doubled in local part");
  if(!/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+$/.test(local))issues.push("invalid characters in local part");
  if(!dom)issues.push("empty domain");
  else{
    if(dom.length>253)issues.push("domain over 253 characters");
    if(/^\.|\.$|\.\./.test(dom))issues.push("dots at start/end or doubled in domain");
    if(!/^[a-z0-9.-]+$/.test(dom))issues.push("invalid characters in domain");
    var labels=dom.split(".");
    if(labels.some(function(l){return !l||l.length>63||/^-|-$/.test(l);}))issues.push("bad domain label");
    var tld=labels[labels.length-1];
    if(!/^[a-z]{2,}$/.test(tld))issues.push("suspicious TLD");
  }
  return issues;
}
function mxCheck(domain){
  return fetch("https://cloudflare-dns.com/dns-query?name="+encodeURIComponent(domain)+"&type=MX",{headers:{accept:"application/dns-json"}})
    .then(function(r){return r.json();})
    .then(function(j){return j&&j.Answer&&j.Answer.length>0;})
    .catch(function(){return null;});
}
function validate(){
  var lines=$("in").value.split("\n").map(function(s){return s.trim();}).filter(function(s){return s!=="";});
  var out=$("out"),mxOn=$("mx").value==="on";
  if(!lines.length){out.innerHTML="<div class='callout'>Enter at least one email address.</div>";return;}
  var jobs=lines.slice(0,200).map(function(e){
    var issues=checkSyntax(e);
    var dom=e.split("@")[1]||"";
    var p=(mxOn&&!issues.length&&dom)?mxCheck(dom):Promise.resolve("skip");
    return p.then(function(mx){return {e:e,issues:issues,mx:mx};});
  });
  out.innerHTML="<div class='callout'>Checking "+jobs.length+" address(es)...</div>";
  Promise.all(jobs).then(function(res){
    var okN=0,h="";
    res.forEach(function(r){
      var ok=r.issues.length===0;
      if(ok)okN++;
      var note=r.issues.length?r.issues.join("; "):"valid syntax";
      if(r.mx===true)note+=", MX records found";
      else if(r.mx===false)note+=", no MX records (cannot receive mail)";
      else if(r.mx===null)note+=", MX check unavailable";
      h+="<div class='ac-row "+(ok&&r.mx!==false?"ac-ok":r.mx===false?"ac-bad":"ac-warn")+"'><span>"+(ok&&r.mx!==false?"\u2713":r.mx===false?"\u2717":"!")+"</span><span><code>"+r.e.replace(/</g,"&lt;")+"</code><br><span class='hint'>"+note+"</span></span></div>";
    });
    out.innerHTML="<div class='callout' style='margin-bottom:10px'><strong>"+okN+"</strong> of "+res.length+" passed.</div>"+h;
  });
  if(lines.length>200)out.innerHTML+="<div class='hint'>First 200 addresses checked.</div>";
}
$("go").addEventListener("click",validate);
$("in").addEventListener("input",function(){
  if($("mx").value==="off"){
    var lines=$("in").value.split("\n").map(function(s){return s.trim();}).filter(function(s){return s!=="";});
    if(!lines.length){$("out").innerHTML="";return;}
    var h="",okN=0;
    lines.slice(0,200).forEach(function(e){
      var issues=checkSyntax(e),ok=!issues.length;if(ok)okN++;
      h+="<div class='ac-row "+(ok?"ac-ok":"ac-bad")+"'><span>"+(ok?"\u2713":"\u2717")+"</span><span><code>"+e.replace(/</g,"&lt;")+"</code><br><span class='hint'>"+(ok?"valid syntax":issues.join("; "))+"</span></span></div>";
    });
    $("out").innerHTML="<div class='callout' style='margin-bottom:10px'><strong>"+okN+"</strong> of "+Math.min(lines.length,200)+" passed.</div>"+h;
  }
});
$("clear").addEventListener("click",function(){$("in").value="";$("out").innerHTML="";$("in").focus();});
})();

(function(){
"use strict";
var P="urlval";
function $(id){return document.getElementById(P+"-"+id);}
function analyze(raw,httpOnly){
  var issues=[],u=null;
  var t=raw.trim();
  if(!t)return null;
  if(/\s/.test(t))issues.push("contains whitespace");
  var candidate=/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(t)?t:"https://"+t;
  try{u=new URL(candidate);}catch(e){issues.push("cannot be parsed as a URL");return {raw:t,issues:issues,u:null};}
  if(httpOnly&&u.protocol!=="http:"&&u.protocol!=="https:")issues.push("protocol "+u.protocol+" not allowed");
  if(!u.hostname)issues.push("missing hostname");
  else{
    if(u.hostname.indexOf(".")===-1&&u.hostname!=="localhost")issues.push("hostname has no dot (no TLD)");
    if(/[^a-zA-Z0-9.\-:\[\]]/.test(u.hostname))issues.push("suspicious characters in hostname");
    if(u.hostname.length>253)issues.push("hostname too long");
  }
  if(/[\x00-\x1f\x7f]/.test(t))issues.push("contains control characters");
  if(/[<>"{}|\\^`]/.test(u.pathname+u.search))issues.push("contains characters that should be percent-encoded");
  return {raw:t,issues:issues,u:u};
}
function run(){
  var lines=$("in").value.split("\n"),out=$("out"),httpOnly=$("proto").value==="http";
  var items=lines.map(function(l){return l.trim();}).filter(function(s){return s!=="";});
  if(!items.length){out.innerHTML="";return;}
  var h="",okN=0;
  items.slice(0,200).forEach(function(raw){
    var r=analyze(raw,httpOnly);
    if(!r)return;
    var ok=r.issues.length===0;if(ok)okN++;
    h+="<div class='ac-row "+(ok?"ac-ok":"ac-bad")+"'><span>"+(ok?"\u2713":"\u2717")+"</span><span><code>"+r.raw.replace(/</g,"&lt;")+"</code>";
    if(r.u){
      h+="<br><span class='hint'>protocol: "+r.u.protocol+" &middot; host: "+r.u.hostname.replace(/</g,"&lt;")+(r.u.port?" port "+r.u.port:"")+" &middot; path: "+(r.u.pathname||"/").replace(/</g,"&lt;")+(r.u.search?" &middot; "+(r.u.search.slice(1).split("&").length)+" query param(s)":"")+"</span>";
    }
    if(r.issues.length)h+="<br><span class='hint'>Issues: "+r.issues.join("; ")+"</span>";
    h+="</span></div>";
  });
  out.innerHTML="<div class='callout' style='margin-bottom:10px'><strong>"+okN+"</strong> of "+Math.min(items.length,200)+" valid.</div>"+h;
}
$("in").addEventListener("input",run);
$("proto").addEventListener("change",run);
})();

