(function(){
'use strict';
var fileEl=document.getElementById('pff-file'),drop=document.getElementById('pff-drop'),
fieldsBox=document.getElementById('pff-fields'),dl=document.getElementById('pff-download'),
reset=document.getElementById('pff-reset'),msg=document.getElementById('pff-msg');
var doc=null,fname='filled-form.pdf';
function pick(){fileEl.click();}
drop.addEventListener('click',pick);
drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();pick();}});
['dragover','dragenter'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();});});
drop.addEventListener('drop',function(e){e.preventDefault();if(e.dataTransfer.files.length)load(e.dataTransfer.files[0]);});
fileEl.addEventListener('change',function(){if(fileEl.files.length)load(fileEl.files[0]);});
reset.addEventListener('click',function(){doc=null;fieldsBox.innerHTML='';msg.textContent='';dl.disabled=true;fileEl.value='';});
function load(f){
  if(!window.PDFLib){msg.textContent='PDF library is still loading. Please wait a moment and try again.';return;}
  fname=(f.name||'form.pdf').replace(/\.pdf$/i,'')+'-filled.pdf';
  var rd=new FileReader();
  msg.textContent='Reading PDF...';
  rd.onload=function(){
    window.PDFLib.PDFDocument.load(rd.result,{ignoreEncryption:false}).then(function(d){
      doc=d;renderFields(d);
    }).catch(function(err){
      doc=null;fieldsBox.innerHTML='';dl.disabled=true;
      msg.textContent='Could not open this PDF. It may be encrypted or corrupted.';
    });
  };
  rd.readAsArrayBuffer(f);
}
function renderFields(d){
  var form;
  try{form=d.getForm();}catch(e){form=null;}
  fieldsBox.innerHTML='';
  if(!form||!form.getFields().length){
    msg.textContent='This PDF has no fillable form fields. Try a PDF with interactive fields instead.';
    dl.disabled=true;return;
  }
  var fs=form.getFields(),n=0;
  fs.forEach(function(f,i){
    var t=f.constructor.name;
    if(t!=='PDFTextField'&&t!=='PDFCheckBox'&&t!=='PDFDropdown'&&t!=='PDFOptionList'&&t!=='PDFRadioGroup')return;
    n++;
    var wrap=document.createElement('div');wrap.className='field';
    var lab=document.createElement('label');lab.textContent=f.getName();lab.setAttribute('for','pff-f'+i);
    wrap.appendChild(lab);
    var inp;
    if(t==='PDFCheckBox'){
      inp=document.createElement('input');inp.type='checkbox';inp.id='pff-f'+i;inp.dataset.idx=i;
    }else if(t==='PDFDropdown'||t==='PDFOptionList'){
      inp=document.createElement('select');inp.id='pff-f'+i;inp.dataset.idx=i;
      f.getOptions().forEach(function(o){var op=document.createElement('option');op.value=o;op.textContent=o;inp.appendChild(op);});
      try{inp.value=f.getSelected()[0]||'';}catch(e){}
    }else{
      inp=document.createElement('input');inp.type='text';inp.id='pff-f'+i;inp.dataset.idx=i;
      inp.className='tool-text';inp.style.width='100%';
      try{inp.value=f.getText()||'';}catch(e){}
    }
    wrap.appendChild(inp);fieldsBox.appendChild(wrap);
  });
  if(!n){msg.textContent='No supported form fields were found in this PDF.';dl.disabled=true;return;}
  msg.textContent=n+' field(s) found. Fill them in, then download the finished PDF.';
  dl.disabled=false;
}
dl.addEventListener('click',function(){
  if(!doc)return;
  var form=doc.getForm();
  fieldsBox.querySelectorAll('[data-idx]').forEach(function(inp){
    var f=form.getFields()[parseInt(inp.dataset.idx,10)],t=f.constructor.name;
    try{
      if(t==='PDFCheckBox'){if(inp.checked)f.check();else f.uncheck();}
      else if(t==='PDFDropdown'||t==='PDFOptionList'){f.select(inp.value);}
      else if(t==='PDFTextField'){f.setText(inp.value);}
    }catch(e){}
  });
  try{form.updateFieldAppearances();}catch(e){}
  doc.save().then(function(bytes){
    var blob=new Blob([bytes],{type:'application/pdf'});
    var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fname;
    document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},4000);
    msg.textContent='Done! Your filled PDF has been downloaded.';
  }).catch(function(){msg.textContent='Something went wrong while saving. Please try again.';});
});
})();

(function(){
'use strict';
var fileEl=document.getElementById('ppp-file'),drop=document.getElementById('ppp-drop'),
modeEl=document.getElementById('ppp-mode'),passEl=document.getElementById('ppp-pass'),
go=document.getElementById('ppp-go'),rst=document.getElementById('ppp-reset'),msg=document.getElementById('ppp-msg');
var current=null,fname='';
function pick(){fileEl.click();}
drop.addEventListener('click',pick);
drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();pick();}});
['dragover','dragenter'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();});});
drop.addEventListener('drop',function(e){e.preventDefault();if(e.dataTransfer.files.length)set(e.dataTransfer.files[0]);});
fileEl.addEventListener('change',function(){if(fileEl.files.length)set(fileEl.files[0]);});
rst.addEventListener('click',function(){current=null;fileEl.value='';passEl.value='';msg.textContent='';});
function set(f){current=f;fname=f.name;msg.textContent='Selected: '+f.name;}
function keyFrom(pass,salt){
  return crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey'])
  .then(function(bk){return crypto.subtle.deriveKey({name:'PBKDF2',salt:salt,iterations:120000,hash:'SHA-256'},bk,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);});
}
go.addEventListener('click',function(){
  var pass=passEl.value;
  if(!current){msg.textContent='Please choose a PDF file first.';return;}
  if(!pass||pass.length<4){msg.textContent='Please enter a password of at least 4 characters.';return;}
  msg.textContent='Working...';
  var rd=new FileReader();
  rd.onload=function(){
    var buf=new Uint8Array(rd.result);
    if(modeEl.value==='lock'){
      var salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));
      keyFrom(pass,salt).then(function(key){
        return crypto.subtle.encrypt({name:'AES-GCM',iv:iv},key,buf);
      }).then(function(ct){
        var out=new Uint8Array(16+12+ct.byteLength);
        out.set(salt,0);out.set(iv,16);out.set(new Uint8Array(ct),28);
        save(out,fname.replace(/\.pdf$/i,'')+'-locked.pdf');
        msg.textContent='Locked! Download started. Keep your password: there is no way to recover it.';
      }).catch(function(){msg.textContent='Encryption failed. Please try again.';});
    }else{
      if(buf.length<29){msg.textContent='This file does not look like a file locked by this tool.';return;}
      var salt=buf.slice(0,16),iv=buf.slice(16,28),ct=buf.slice(28);
      keyFrom(pass,salt).then(function(key){
        return crypto.subtle.decrypt({name:'AES-GCM',iv:iv},key,ct);
      }).then(function(pt){
        var base=fname.replace(/-locked\.pdf$/i,'').replace(/\.pdf$/i,'')||'document';
        save(new Uint8Array(pt),base+'-unlocked.pdf');
        msg.textContent='Unlocked! Download started.';
      }).catch(function(){msg.textContent='Wrong password, or this file was not locked by this tool.';});
    }
  };
  rd.readAsArrayBuffer(current);
});
function save(bytes,name){
  var blob=new Blob([bytes],{type:'application/pdf'});
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;
  document.body.appendChild(a);a.click();setTimeout(function(){URL.revokeObjectURL(a.href);a.remove();},4000);
}
})();

(function(){
'use strict';
var inp=document.getElementById('rtt-in'),out=document.getElementById('rtt-out'),
go=document.getElementById('rtt-go'),fb=document.getElementById('rtt-file-btn'),fi=document.getElementById('rtt-file'),
sm=document.getElementById('rtt-sample'),cl=document.getElementById('rtt-clear'),
cp=document.getElementById('rtt-copy'),dl=document.getElementById('rtt-dl'),cnt=document.getElementById('rtt-count');
function decode(rtf){
  var i=0,n=rtf.length,buf='',out='';
  function ctrl(){
