(function(){
'use strict';
var inp=document.getElementById('jp-in'),path=document.getElementById('jp-path'),
out=document.getElementById('jp-out'),info=document.getElementById('jp-info');
function query(data,path){
  var tokens=[],i=0;
  if(path[0]!=='$')throw new Error('Path must start with $');
  i=1;
  while(i<path.length){
    var c=path[i];
    if(c==='.'){
      i++;
      var m=path.slice(i).match(/^[A-Za-z_$][A-Za-z0-9_$]*/);
      if(!m)throw new Error('Bad key at position '+i);
      tokens.push({t:'k',v:m[0]});i+=m[0].length;
    }else if(c==='['){
      var j=path.indexOf(']',i);
      if(j<0)throw new Error('Missing ]');
      var inner=path.slice(i+1,j).trim();i=j+1;
      if(inner==='*')tokens.push({t:'*'});
      else if(/^-?\d+$/.test(inner))tokens.push({t:'i',v:parseInt(inner,10)});
      else{var q=inner.match(/^["'](.*)["']$/);if(!q)throw new Error('Bad bracket: '+inner);tokens.push({t:'k',v:q[1]});}
    }else throw new Error('Unexpected character "'+c+'" at position '+i);
  }
  var cur=[data];
  tokens.forEach(function(tk){
    var nx=[];
    cur.forEach(function(node){
      if(tk.t==='k'){if(node!==null&&typeof node==='object'&&tk.v in node)nx.push(node[tk.v]);}
      else if(tk.t==='i'){if(Array.isArray(node)){var k=tk.v<0?node.length+tk.v:tk.v;if(k>=0&&k<node.length)nx.push(node[k]);}}
      else if(tk.t==='*'){if(node!==null&&typeof node==='object'){Object.keys(node).forEach(function(k){nx.push(node[k]);});}}
    });
    cur=nx;
  });
  return cur;
}
function run(){
  var raw=inp.value.trim();
  if(!raw){out.value='';info.textContent='';return;}
  var data;
  try{data=JSON.parse(raw);}catch(e){out.value='';info.textContent='Invalid JSON: '+e.message;return;}
  var res;
  try{res=query(data,path.value.trim()||'$');}
  catch(e){out.value='';info.textContent='Invalid path: '+e.message;return;}
  out.value=res.map(function(v){return typeof v==='string'?v:JSON.stringify(v);}).join('\n');
  info.textContent=res.length+' match(es).';
}
document.getElementById('jp-go').addEventListener('click',run);
