      +'<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line)"><span>Size</span><strong>'+fmtSize(f.size)+'</strong></div>';
    if(found){
      var match=found.e.indexOf(ext)>=0;
      html+='<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line)"><span>Detected type</span><strong>'+found.n+'</strong></div>';
      html+=match
        ?'<div class="callout good" style="margin-top:12px"><strong>Match.</strong> The extension .'+esc(ext)+' matches the detected '+found.n+'. This file looks genuine.</div>'
        :'<div class="callout info" style="margin-top:12px"><strong>Mismatch!</strong> The file claims to be .'+esc(ext)+' but its signature says '+found.n+'. It may have been renamed'+(found.n==='Windows executable'?' <strong>and could be dangerous</strong>':'')+'. Treat it with caution.</div>';
    }else{
      html+='<div class="callout info" style="margin-top:12px">Signature not recognized. This is a format the checker does not know, not necessarily a problem.</div>';
