function caesar(t,s,dec){
  s=((s%26)+26)%26;if(dec)s=26-s;
  return t.replace(/[a-zA-Z]/g,function(c){
    var b=c<='Z'?65:97;
    return String.fromCharCode((c.charCodeAt(0)-b+s)%26+b);
  });
}
function atbash(t){
  return t.replace(/[a-zA-Z]/g,function(c){
    var b=c<='Z'?65:97;
    return String.fromCharCode(b+25-(c.charCodeAt(0)-b));
  });
}
function b64e(t){
  try{return btoa(unescape(encodeURIComponent(t)));}catch(e){return 'ERROR: '+e.message;}
}
function b64d(t){
  try{return decodeURIComponent(escape(atob(t.trim())));}catch(e){return 'ERROR: invalid Base64 input.';}
}
