var DAY=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
var DAYS=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
function p2(n){return (n<10?'0':'')+n;}
function format(d,pat){
  return pat.replace(/YYYY|YY|MMMM|MMM|MM|DD|dddd|ddd|HH|mm|ss/g,function(t){
    switch(t){
      case 'YYYY':return d.getFullYear();
      case 'YY':return String(d.getFullYear()).slice(2);
      case 'MMMM':return MON[d.getMonth()];
      case 'MMM':return MONS[d.getMonth()];
      case 'MM':return p2(d.getMonth()+1);
      case 'DD':return p2(d.getDate());
      case 'dddd':return DAY[d.getDay()];
      case 'ddd':return DAYS[d.getDay()];
      case 'HH':return p2(d.getHours());
