function parseDate(s){
  s=s.trim();
  var m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(m)return new Date(+m[1],+m[2]-1,+m[3]);
  m=s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if(m){var a=+m[1],b=+m[2],y=+m[3];if(y<100)y+=2000;
    if(a>12)return new Date(y,b-1,a);
