document.getElementById('gc-go').addEventListener('click',function(){
  var s=shape.value,res=[],formula='';
  function need(ids){var o={};for(var i=0;i<ids.length;i++){var v=val(ids[i]);if(v===null)return null;o[ids[i]]=v;}return o;}
  if(s==='square'){var v=need(['side']);if(!v)return bad();res=[['Area',r2(v.side*v.side)+' sq units'],['Perimeter',r2(4*v.side)+' units']];formula='Area = side^2, Perimeter = 4 x side';}
