  else if(s==='trapezoid'){var v=need(['a','b','h']);if(!v)return bad();res=[['Area',r2(0.5*(v.a+v.b)*v.h)+' sq units']];formula='Area = 1/2 x (a + b) x h';}
  else if(s==='cube'){var v=need(['side']);if(!v)return bad();res=[['Volume',r2(Math.pow(v.side,3))+' cubic units'],['Surface area',r2(6*v.side*v.side)+' sq units']];formula='Volume = side^3, Surface = 6 x side^2';}
  else if(s==='sphere'){var v=need(['r']);if(!v)return bad();res=[['Volume',r2(4/3*Math.PI*Math.pow(v.r,3))+' cubic units'],['Surface area',r2(4*Math.PI*v.r*v.r)+' sq units']];formula='Volume = 4/3 pi r^3, Surface = 4 pi r^2';}
  else if(s==='cylinder'){var v=need(['r','h']);if(!v)return bad();res=[['Volume',r2(Math.PI*v.r*v.r*v.h)+' cubic units'],['Surface area',r2(2*Math.PI*v.r*(v.r+v.h))+' sq units']];formula='Volume = pi r^2 h, Surface = 2 pi r(r + h)';}
  else if(s==='cone'){var v=need(['r','h']);if(!v)return bad();res=[['Volume',r2(Math.PI*v.r*v.r*v.h/3)+' cubic units']];formula='Volume = 1/3 pi r^2 h';}
