});
})();

(function(){
'use strict';
var expr=document.getElementById('sc-expr'),keys=document.getElementById('sc-keys'),hist=document.getElementById('sc-hist');
var KEYS=['sin(','cos(','tan(','asin(','acos(','atan(','log(','ln(','sqrt(','cbrt(','x^y','x^2','1/x','pi','e','(',' )','%','7','8','9','/','C','4','5','6','*','back','1','2','3','-','ANS','0','.','^','+','='];
KEYS.forEach(function(k){
  var b=document.createElement('button');b.type='button';b.className='btn';b.textContent=k;b.style.padding='10px 4px';
  b.addEventListener('click',function(){press(k);});keys.appendChild(b);
});
var lastAns=0;
function press(k){
  if(k==='C'){expr.value='';return;}
  if(k==='back'){expr.value=expr.value.slice(0,-1);return;}
  if(k==='='){calc();return;}
  if(k==='ANS'){expr.value+=lastAns;return;}
  if(k==='x^y'){expr.value+='^';return;}
  if(k==='x^2'){expr.value+='^2';return;}
  if(k==='1/x'){expr.value='1/('+expr.value+')';return;}
  if(k==='%'){expr.value+='/100';return;}
  if(k==='pi'){expr.value+='pi';return;}
  expr.value+=k;
}
function calc(){
  var s=expr.value.trim();
  if(!s)return;
  if(!/^[0-9+\-*/^().,\s%a-z]+$/i.test(s)){showErr('Invalid characters');return;}
  var t=s.replace(/\^/g,'**')
    .replace(/\bsin\(/g,'S(').replace(/\bcos\(/g,'C(').replace(/\btan\(/g,'T(')
    .replace(/\basin\(/g,'AS(').replace(/\bacos\(/g,'AC(').replace(/\batan\(/g,'AT(')
    .replace(/\blog\(/g,'LOG(').replace(/\bln\(/g,'LN(')
    .replace(/\bsqrt\(/g,'SQ(').replace(/\bcbrt\(/g,'CB(')
    .replace(/\bpi\b/g,'PI').replace(/\be\b/g,'E');
  if(/[^0-9+\-*\/.(),\sA-Z]/.test(t)){showErr('Invalid expression');return;}
  var deg=document.querySelector('input[name="sc-ang"]:checked').value==='deg';
  var f=deg?Math.PI/180:1;
  try{
    var fn=new Function('S','C','T','AS','AC','AT','LOG','LN','SQ','CB','PI','E',
      'return ('+t+');');
    var r=fn(Math.sin,Math.cos,Math.tan,
      function(x){return Math.asin(x)/f;},function(x){return Math.acos(x)/f;},function(x){return Math.atan(x)/f;},
      function(x){return Math.log10(x);},Math.log,Math.sqrt,Math.cbrt,Math.PI,Math.E);
    if(typeof r!=='number'||!isFinite(r)){showErr('Math error');return;}
    r=Math.round(r*1e10)/1e10;lastAns=r;expr.value=String(r);
    addHist(s+' = '+r);
  }catch(e){showErr('Could not evaluate');}
}
function showErr(m){expr.value='';var d=document.createElement('div');d.textContent='Error: '+m;}
function addHist(line){
  var ph=hist.querySelector('.sub');if(ph)ph.remove();
  var d=document.createElement('div');
  d.style.cssText='padding:7px 0;border-bottom:1px solid var(--line);font-family:ui-monospace,monospace;font-size:.85rem';
  d.textContent=line;hist.insertBefore(d,hist.firstChild);
  while(hist.children.length>20)hist.removeChild(hist.lastChild);
}
document.getElementById('sc-clear').addEventListener('click',function(){expr.value='';});
document.getElementById('sc-hist-clear').addEventListener('click',function(){hist.innerHTML='<p class="sub">Your calculations will appear here.</p>';});
expr.addEventListener('keydown',function(e){if(e.key==='Enter')calc();});
})();

