function chips(words){
  if(!words.length)return '<p class="sub">None found.</p>';
  return '<div style="display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 14px">'+words.map(function(w){
    return '<button type="button" class="btn btn-sm" data-w="'+w.replace(/"/g,'&quot;')+'">'+w+'</button>';
  }).join('')+'</div>';
}
function bindChips(){
  out.querySelectorAll('button[data-w]').forEach(function(b){
    b.addEventListener('click',function(){inp.value=b.getAttribute('data-w');run();window.scrollTo(0,0);});
  });
}
function show(syn,ant,src){
  out.innerHTML='<h3 style="font-size:.95rem">Synonyms</h3>'+chips(syn)
    +'<h3 style="font-size:.95rem">Antonyms</h3>'+chips(ant)
    +'<p class="hint">Source: '+src+'. Click any word to look it up.</p>';
  bindChips();
}
function run(){
  var w=inp.value.trim().toLowerCase();
  if(!w){out.innerHTML='<p class="sub">Type a word first.</p>';return;}
  out.innerHTML='<p class="sub">Looking up "'+w.replace(/</g,'&lt;')+'"...</p>';
  var done=false;
  function fallback(){
    if(done)return;done=true;
    var s=FALLBACK[w]||[];
    show(s,[],s.length?'built-in word list (offline)':'built-in word list (offline)');
    if(!s.length)out.innerHTML='<p class="sub">No synonyms found for "'+w.replace(/</g,'&lt;')+'". Check the spelling or try another word.</p>';
  }
  try{
    var ctl=new AbortController();var to=setTimeout(function(){ctl.abort();fallback();},6000);
    fetch('https://api.datamuse.com/words?rel_syn='+encodeURIComponent(w)+'&max=24',{signal:ctl.signal})
      .then(function(r){return r.json();}).then(function(synJ){
        return fetch('https://api.datamuse.com/words?rel_ant='+encodeURIComponent(w)+'&max=12',{signal:ctl.signal})
          .then(function(r){return r.json();}).then(function(antJ){
            clearTimeout(to);if(done)return;done=true;
            var syn=synJ.map(function(x){return x.word;}),ant=antJ.map(function(x){return x.word;});
            if(!syn.length&&FALLBACK[w])syn=FALLBACK[w];
            if(!syn.length&&!ant.length){fallback();return;}
            show(syn,ant,'Datamuse API');
          });
      }).catch(function(){clearTimeout(to);fallback();});
  }catch(e){fallback();}
}
document.getElementById('sf-go').addEventListener('click',run);
document.getElementById('sf-clear').addEventListener('click',function(){inp.value='';out.innerHTML='<p class="sub">Type a word and press Find synonyms.</p>';});
inp.addEventListener('keydown',function(e){if(e.key==='Enter')run();});
})();

