function makeICO(sizes){
  return Promise.all(sizes.map(function(sz){
    return new Promise(function(res){resize(sz).toBlob(function(b){res({sz:sz,blob:b});},'image/png');});
  })).then(function(items){
    return Promise.all(items.map(function(it){
      return it.blob.arrayBuffer().then(function(ab){it.buf=new Uint8Array(ab);return it;});
    }));
  }).then(function(items){
    var head=6+16*items.length,total=head;
    items.forEach(function(it){total+=it.buf.length;});
    var ab=new ArrayBuffer(total),v=new DataView(ab),o=6+16*items.length;
    v.setUint16(0,0,true);v.setUint16(2,1,true);v.setUint16(4,items.length,true);
    items.forEach(function(it,i){
      var e=6+i*16,sz=it.sz>=256?0:it.sz;
      v.setUint8(e,sz);v.setUint8(e+1,sz);v.setUint8(e+2,0);v.setUint8(e+3,0);
      v.setUint16(e+4,1,true);v.setUint16(e+6,32,true);
      v.setUint32(e+8,it.buf.length,true);v.setUint32(e+12,o,true);
      new Uint8Array(ab,o,it.buf.length).set(it.buf);o+=it.buf.length;
    });
    return new Blob([ab],{type:'image/x-icon'});
  });
}
