(function(){
'use strict';
var inp=document.getElementById('jl-in'),out=document.getElementById('jl-out');
var REQ={
  'Article':['headline','author','datePublished'],
  'NewsArticle':['headline','author','datePublished'],
  'BlogPosting':['headline','author','datePublished'],
  'Product':['name','image','offers'],
  'Organization':['name','url'],
  'LocalBusiness':['name','address'],
  'FAQPage':['mainEntity'],
  'Recipe':['name','image','recipeIngredient'],
  'Event':['name','startDate','location'],
  'VideoObject':['name','description','thumbnailUrl','uploadDate'],
  'BreadcrumbList':['itemListElement'],
  'WebSite':['name','url'],
  'Person':['name']
};
function clean(s){
  s=s.trim();
  var m=s.match(/<script[^>]*>([\s\S]*?)<\/script>/i);
  return m?m[1]:s;
}
function run(){
  var raw=clean(inp.value);
  if(!raw){out.innerHTML='<p class="sub">Paste JSON-LD and press Validate.</p>';return;}
  var data;
  try{data=JSON.parse(raw);}catch(e){out.innerHTML='<div class="callout info"><strong>Invalid JSON:</strong> '+esc(e.message)+'</div>';return;}
  var items=Array.isArray(data)?data:[data];
  var graphs=[];
  items.forEach(function(it){if(it&&it['@graph']&&Array.isArray(it['@graph']))graphs=graphs.concat(it['@graph']);else graphs.push(it);});
  var html='',errors=0,warns=0;
  graphs.forEach(function(g,i){
    html+='<h3 style="font-size:.95rem;margin:12px 0 6px">Item '+(i+1)+'</h3>';
    if(!g||typeof g!=='object'){html+=line('bad','Not a JSON object.');errors++;return;}
    if(!g['@context']){html+=line('bad','Missing <b>@context</b> (should be "https://schema.org").');errors++;}
    else if(String(g['@context']).indexOf('schema.org')<0){html+=line('warn','@context does not reference schema.org.');warns++;}
    else html+=line('good','@context references schema.org.');
    var t=g['@type'];
    if(!t){html+=line('bad','Missing <b>@type</b>.');errors++;return;}
    var types=Array.isArray(t)?t:[t];
    html+=line('good','@type: <b>'+esc(types.join(', '))+'</b>');
    types.forEach(function(ty){
      (REQ[ty]||[]).forEach(function(p){
        if(!(p in g)){html+=line('warn','Recommended property missing for '+esc(ty)+': <b>'+p+'</b>');warns++;}
      });
    });
    if(g['@id']&&!/^https?:\/\//.test(g['@id'])){html+=line('warn','@id should be a full URL.');warns++;}
  });
  var head=errors===0&&warns===0
    ?'<div class="callout good" style="margin-bottom:10px"><strong>Valid!</strong> No errors or warnings found.</div>'
    :'<div class="callout '+(errors?'info':'good')+'" style="margin-bottom:10px"><strong>'+errors+' error(s), '+warns+' warning(s).</strong> Fix errors first; warnings are recommendations.</div>';
  out.innerHTML=head+html;
}
function line(cls,msg){
  var c=cls==='good'?'#16a34a':(cls==='bad'?'#dc2626':'#d97706');
  return '<div style="padding:6px 0;border-bottom:1px solid var(--line);font-size:.9rem"><span style="color:'+c+';font-weight:700">'+(cls==='good'?'PASS':cls==='bad'?'FAIL':'WARN')+'</span> - '+msg+'</div>';
}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
document.getElementById('jl-go').addEventListener('click',run);
document.getElementById('jl-clear').addEventListener('click',function(){inp.value='';out.innerHTML='<p class="sub">Paste JSON-LD and press Validate.</p>';});
document.getElementById('jl-sample').addEventListener('click',function(){
  inp.value=JSON.stringify({'@context':'https://schema.org','@type':'Article',headline:'Example headline',author:{'@type':'Person',name:'Jane Doe'},datePublished:'2026-10-19'},null,2);
  run();
});
})();

