'use strict';
var u=document.getElementById('ff-u'),fl=document.getElementById('ff-fl'),fw=document.getElementById('ff-fw'),
fh=document.getElementById('ff-fh'),dw=document.getElementById('ff-dw'),dh=document.getElementById('ff-dh'),
out=document.getElementById('ff-out');
function row(n,v){return '<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line)"><span>'+n+'</span><strong>'+v+'</strong></div>';}
document.getElementById('ff-go').addEventListener('click',function(){
  var L=parseFloat(fl.value),W=parseFloat(fw.value),H=parseFloat(fh.value),
      DW=parseFloat(dw.value),DH=parseFloat(dh.value),un=u.value;
  if(![L,W,H,DW,DH].every(function(v){return v>0;})){out.innerHTML='<p class="sub">Please enter valid positive numbers.</p>';return;}
  var dims=[L,W,H].sort(function(a,b){return a-b;});
  var s=dims[0],m=dims[1],lg=dims[2];
  var doorW=Math.min(DW,DH),doorH=Math.max(DW,DH);
  var html=row('Item (sorted)',s+' x '+m+' x '+lg+' '+un)+row('Doorway',doorW+' x '+doorH+' '+un);
  var verdict,cls;
  if(m<=doorW&&s<=doorH){
    verdict='Fits flat through the door.';cls='good';
  }else{
    var diag=Math.sqrt(doorW*doorW+doorH*doorH);
    var need=Math.sqrt(m*m+s*s);
    if(need<=diag&&lg>=doorW){
      verdict='Tight: it can pass tilted diagonally. Measure carefully and remove the door if needed.';cls='info';
    }else if(m<=doorH&&s<=doorW){
      verdict='Fits if you rotate it upright through the doorway.';cls='good';
    }else{
      verdict='Will not fit through this doorway. Consider a smaller item, disassembly, or another entrance.';cls='info';
    }
  }
  html+='<div class="callout '+cls+'" style="margin-top:12px"><strong>Verdict:</strong> '+verdict+'</div>'
  +'<p class="hint" style="margin-top:8px">Tip: also measure hallways, stair turns and elevator doors along the delivery path.</p>';
  out.innerHTML=html;
});
})();

