(function(){
'use strict';
var inp=document.getElementById('hf-in'),out=document.getElementById('hf-out'),
cs=document.getElementById('hf-case'),sp=document.getElementById('hf-sep'),dd=document.getElementById('hf-dupe'),
info=document.getElementById('hf-info');
function run(){
  var raw=inp.value;
  if(!raw.trim()){out.value='';info.textContent='';return;}
  var tokens=raw.split(/[\s,;|]+/).map(function(t){return t.trim();}).filter(Boolean);
  var seen={},tags=[],dupes=0;
  tokens.forEach(function(t){
    t=t.replace(/^#+/,'').replace(/[^\p{L}\p{N}_]/gu,'');
    if(!t)return;
    if(cs.value==='lower')t=t.toLowerCase();
    var key=t.toLowerCase();
    if(dd.checked&&seen[key]){dupes++;return;}
    seen[key]=1;tags.push('#'+t);
  });
  var sep=sp.value==='\n'?'\n':sp.value;
  out.value=tags.join(sep);
  info.textContent=tags.length+' hashtag(s)'+(dupes?' ('+dupes+' duplicate(s) removed)':'')+'. Instagram allows up to 30 per post.';
}
document.getElementById('hf-go').addEventListener('click',run);
document.getElementById('hf-clear').addEventListener('click',function(){inp.value='';out.value='';info.textContent='';});
document.getElementById('hf-copy').addEventListener('click',function(){out.select();document.execCommand('copy');});
})();

