(function(){
'use strict';
var video=document.getElementById('wc-video'),dev=document.getElementById('wc-dev'),
mirror=document.getElementById('wc-mirror'),off=document.getElementById('wc-off'),
start=document.getElementById('wc-start'),stop=document.getElementById('wc-stop'),
snap=document.getElementById('wc-snap'),out=document.getElementById('wc-out'),msg=document.getElementById('wc-msg');
var stream=null;
function listDevices(){
  if(!navigator.mediaDevices||!navigator.mediaDevices.enumerateDevices)return;
  navigator.mediaDevices.enumerateDevices().then(function(ds){
    var cams=ds.filter(function(d){return d.kind==='videoinput';});
    dev.innerHTML='<option value="">Default camera</option>'+cams.map(function(c,i){
      return '<option value="'+c.deviceId+'">'+(c.label||'Camera '+(i+1))+'</option>';
    }).join('');
  }).catch(function(){});
}
mirror.addEventListener('change',function(){
  video.style.transform=mirror.checked?'scaleX(-1)':'none';
});
start.addEventListener('click',function(){
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){
    msg.textContent='Your browser does not support camera access, or the page is not on HTTPS.';return;
  }
  var cons={video:dev.value?{deviceId:{exact:dev.value}}:true,audio:false};
  msg.textContent='Requesting camera permission...';
  navigator.mediaDevices.getUserMedia(cons).then(function(s){
    stream=s;video.srcObject=s;off.style.display='none';
    start.disabled=true;stop.disabled=false;snap.disabled=false;
    msg.textContent='Camera is live. Your video never leaves this device.';
    listDevices();
  }).catch(function(e){
    msg.textContent='Could not access the camera: '+(e.name==='NotAllowedError'?'permission was denied. Allow camera access and try again.':e.message||e.name);
  });
});
function end(){
  if(stream){stream.getTracks().forEach(function(t){t.stop();});stream=null;}
  video.srcObject=null;off.style.display='flex';
  start.disabled=false;stop.disabled=true;snap.disabled=true;
  msg.textContent='Camera stopped.';
}
stop.addEventListener('click',end);
snap.addEventListener('click',function(){
  if(!stream||!video.videoWidth){msg.textContent='Start the camera first.';return;}
  var c=document.createElement('canvas');
  c.width=video.videoWidth;c.height=video.videoHeight;
  var x=c.getContext('2d');
  if(mirror.checked){x.translate(c.width,0);x.scale(-1,1);}
  x.drawImage(video,0,0);
  var url=c.toDataURL('image/png');
  out.innerHTML='<h3 style="font-size:.95rem;margin-bottom:8px">Snapshot</h3>'
  +'<img src="'+url+'" alt="Webcam snapshot" style="max-width:320px;border-radius:8px;border:1px solid var(--line);display:block;margin-bottom:8px"/>'
  +'<button class="btn btn-sm" id="wc-dl">Download PNG</button>';
  document.getElementById('wc-dl').addEventListener('click',function(){
    var a=document.createElement('a');a.href=url;a.download='webcam-snapshot.png';
    document.body.appendChild(a);a.click();a.remove();
  });
  msg.textContent='Snapshot captured.';
});
listDevices();
window.addEventListener('beforeunload',end);
})();

