(function(){
'use strict';
var inp=document.getElementById('vc-in'),out=document.getElementById('vc-out');
function line(cls,msg){
  var c=cls==='good'?'#16a34a':(cls==='bad'?'#dc2626':'#d97706');
  return '<div style="padding:6px 0;border-bottom:1px solid var(--line);font-size:.9rem"><span style="color:'+c+';font-weight:700">'+(cls==='good'?'PASS':cls==='bad'?'FAIL':'WARN')+'</span> - '+msg+'</div>';
}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function audit(html){
  var tags=html.match(/<meta[^>]*name\s*=\s*["']viewport["'][^>]*>/gi)||[];
  tags=tags.concat((html.match(/<meta[^>]*content\s*=\s*["'][^"']*["'][^>]*name\s*=\s*["']viewport["']/gi)||[]).filter(function(t){return tags.indexOf(t)<0;}));
  var res=[];
  if(!tags.length){return {score:0,html:line('bad','No viewport meta tag found. Mobile browsers will render this page at desktop width.'),tag:null};}
  if(tags.length>1)res.push(line('warn','Multiple viewport tags found ('+tags.length+'). Only the first is used by browsers.'));
  var tag=tags[0];
  var cm=tag.match(/content\s*=\s*["']([^"']*)["']/i);
  var content=cm?cm[1]:'';
  res.push(line('good','Viewport tag found: <code>'+esc(content)+'</code>'));
  var parts={};
  content.split(',').forEach(function(p){
    var kv=p.split('=');if(kv.length===2)parts[kv[0].trim().toLowerCase()]=kv[1].trim().toLowerCase();
  });
  var score=100;
  if(!parts['width']){res.push(line('bad','Missing <b>width</b>. Add width=device-width.'));score-=40;}
  else if(parts['width']!=='device-width'){res.push(line('warn','width is "'+esc(parts['width'])+'" instead of device-width. Only use a fixed width for fixed-width layouts.'));score-=15;}
  else res.push(line('good','width=device-width is set.'));
  if(!parts['initial-scale'])res.push(line('warn','initial-scale is not set. initial-scale=1 is recommended.'));
  else res.push(line('good','initial-scale='+esc(parts['initial-scale'])+'.'));
  if(parts['user-scalable']==='no'||parts['user-scalable']==='0'){res.push(line('bad','user-scalable=no disables pinch zoom: an accessibility failure. Remove it.'));score-=30;}
  if(parts['maximum-scale']&&parseFloat(parts['maximum-scale'])<2){res.push(line('warn','maximum-scale below 2 restricts zoom for low-vision users.'));score-=10;}
  return {score:Math.max(0,score),html:res.join(''),tag:content};
}
function run(){
  var r=audit(inp.value);
  var cls=r.score>=85?'good':(r.score>=60?'info':'info');
  var label=r.score>=85?'Good':(r.score>=60?'Needs work':'Poor');
  out.innerHTML='<div class="callout '+cls+'" style="margin-bottom:10px"><strong>Score: '+r.score+'/100 ('+label+')</strong></div>'+r.html;
}
document.getElementById('vc-go').addEventListener('click',run);
document.getElementById('vc-clear').addEventListener('click',function(){inp.value='';out.innerHTML='<p class="sub">Paste HTML and press Check viewport.</p>';});
document.getElementById('vc-self').addEventListener('click',function(){
  var m=document.querySelector('meta[name="viewport"]');
  inp.value=m?m.outerHTML:'<!-- no viewport meta tag on this page -->';
  run();
});
})();

