  document.getElementById('ttp-text').value='';document.getElementById('ttp-title').value='';
  dl.innerHTML='';status.textContent='Ready.';
};
document.getElementById('ttp-go').onclick=function(){
  var text=document.getElementById('ttp-text').value;
  if(!text.trim()){status.textContent='Enter some text first.';return;}
  if(typeof PDFLib==='undefined'){status.textContent='PDF library failed to load. Check your connection and try again.';return;}
  var size=parseInt(document.getElementById('ttp-size').value,10)||12;
  var align=document.getElementById('ttp-align').value;
  var title=document.getElementById('ttp-title').value.trim();
  status.textContent='Building PDF\u2026';dl.innerHTML='';
  PDFLib.PDFDocument.create().then(function(doc){
    var font=doc.embedStandardFont(PDFLib.StandardFonts.Helvetica);
    var bold=doc.embedStandardFont(PDFLib.StandardFonts.HelveticaBold);
    return Promise.all([font,bold]).then(function(f){
      font=f[0];bold=f[1];
      var PW=595.28,PH=841.89,M=56,usable=PW-2*M,lineH=size*1.45;
      var words=text.replace(/\r/g,'').split('\n');
      var lines=[];
      words.forEach(function(para){
        if(!para.trim()){lines.push('');return;}
        var ws=para.split(/\s+/),cur='';
        ws.forEach(function(w){
          var t=cur?cur+' '+w:w;
          if(font.widthOfTextAtSize(t,size)>usable&&cur){lines.push(cur);cur=w;}
          else cur=t;
        });
        lines.push(cur);
      });
      var page=doc.addPage([PW,PH]),y=PH-M;
      function newPage(){page=doc.addPage([PW,PH]);y=PH-M;}
      if(title){
        var ts=Math.min(22,size+8);
        if(y-ts< M){newPage();}
        page.drawText(title,{x:M,y:y-ts,font:bold,size:ts,color:PDFLib.rgb(0.1,0.1,0.12)});
        y-=ts+18;
      }
      lines.forEach(function(ln){
        if(y-lineH<M){newPage();}
        var x=M;
        if(ln){
          var wdt=font.widthOfTextAtSize(ln,size);
          if(align==='center')x=M+(usable-wdt)/2;
          else if(align==='justify'&&wdt>usable*0.6){
            var ws=ln.split(' '),gaps=ws.length-1;
            if(gaps>0){var extra=(usable-wdt)/gaps,xx=M;
              ws.forEach(function(w,i){page.drawText(w,{x:xx,y:y-lineH,font:font,size:size});xx+=font.widthOfTextAtSize(w,size)+font.widthOfTextAtSize(' ',size)+extra;});
              y-=lineH;return;}
          }
          page.drawText(ln,{x:x,y:y-lineH,font:font,size:size});
        }
        y-=lineH;
      });
      if(title)doc.setTitle(title);
      return doc.save();
    });
  }).then(function(bytes){
    var blob=new Blob([bytes],{type:'application/pdf'});
    var a=document.createElement('a');a.href=URL.createObjectURL(blob);
