    var step=null,range=p;
    if(p.indexOf('/')>-1){var sp=p.split('/');range=sp[0];step=sp[1];}
    var t;
    if(range==='*'){
      if(unit==='minute')t='every minute';
      else if(unit==='hour')t='every hour';
      else if(unit==='day')t='every day';
      else if(unit==='month')t='every month';
      else t='every day of the week';
    }
    else if(range.indexOf('-')>-1){
      var b=range.split('-'),a0=parseInt(b[0],10),a1=parseInt(b[1],10);
