      else if(unit==='hour')t='hourly from '+a0+':00 through '+a1+':00';
      else if(unit==='day')t='on days '+a0+'-'+a1+' of the month';
      else if(unit==='month')t='in '+nm(a0)+' through '+nm(a1);
      else t='on '+nm(a0)+' through '+nm(a1);
    }
    else{
      var v0=parseInt(range,10);
      if(unit==='minute')t=range==='0'?'at the start of each hour':'at '+v0+' minutes past the hour';
      else if(unit==='hour')t='at '+v0+':00';
      else if(unit==='day')t='on day '+v0+' of the month';
      else if(unit==='month')t='in '+nm(v0);
      else t='on '+nm(v0);
