  var dowRaw=f[4].replace(/(^|[\s,\/-])7(?=[\s,\/-]|$)/g,'$10');
  var mi=parseField(f[0],0,59),h=parseField(f[1],0,23),dom=parseField(f[2],1,31),
      mo=parseField(f[3],1,12),dw=parseField(dowRaw,0,6);
  if(!mi||!h||!dom||!mo||!dw){out.innerHTML='<p class="sub" style="color:#b91c1c">Invalid field value. Check ranges: minute 0-59, hour 0-23, day 1-31, month 1-12, weekday 0-6.</p>';return;}
  var desc='Runs '+fieldText(f[0],0,59,null,'minute')+', '+fieldText(f[1],0,23,null,'hour')+', '+fieldText(f[2],1,31,null,'day')+', '+fieldText(f[3],1,12,MON,'month')+', '+fieldText(f[4],0,6,DOW,'dow');
