(function(){
'use strict';
var inp=document.getElementById('ent-in'),out=document.getElementById('ent-out'),
show=document.getElementById('ent-show');
show.addEventListener('change',function(){inp.type=show.checked?'text':'password';});
inp.type='password';
function fmtTime(sec){
  if(!isFinite(sec))return 'effectively never';
  var units=[[31557600,'year'],[86400,'day'],[3600,'hour'],[60,'minute'],[1,'second']];
  for(var i=0;i<units.length;i++){
    if(sec>=units[i][0]){var v=sec/units[i][0];
      return v>=1e12?(v/1e12).toFixed(1)+' trillion '+units[i][1]+'s':v>=1e9?(v/1e9).toFixed(1)+' billion '+units[i][1]+'s':v>=1e6?(v/1e6).toFixed(1)+' million '+units[i][1]+'s':Math.round(v).toLocaleString()+' '+units[i][1]+'s';}
  }
  return 'less than a second';
}
function analyze(){
  var p=inp.value;
  if(!p){out.innerHTML='<p class="sub">Type a password above to see its strength.</p>';return;}
  var pool=0,parts=[];
  if(/[a-z]/.test(p)){pool+=26;parts.push('lowercase (26)');}
  if(/[A-Z]/.test(p)){pool+=26;parts.push('uppercase (26)');}
  if(/[0-9]/.test(p)){pool+=10;parts.push('digits (10)');}
  var sym=p.replace(/[a-zA-Z0-9]/g,'');
  var symSet={};for(var i=0;i<sym.length;i++)symSet[sym[i]]=1;
  var symCount=Object.keys(symSet).length;
  if(symCount){pool+=33;parts.push('symbols (~33)');}
  var bits=p.length*Math.log(pool)/Math.log(2);
  var combos=Math.pow(pool,p.length);
  var verdict,bcolor;
  if(bits<40){verdict='Very weak';bcolor='#b91c1c';}
  else if(bits<60){verdict='Weak';bcolor='#c2410c';}
  else if(bits<80){verdict='Reasonable';bcolor='#a16207';}
  else if(bits<100){verdict='Strong';bcolor='#15803d';}
  else{verdict='Very strong';bcolor='#166534';}
  out.innerHTML=
   '<p style="font-size:2rem;font-weight:800;margin:4px 0">'+bits.toFixed(1)+' <span style="font-size:1rem;font-weight:400">bits of entropy</span></p>'+
   '<p style="font-weight:800;color:'+bcolor+';margin:4px 0">'+verdict+'</p>'+
   '<table style="width:100%;border-collapse:collapse;margin-top:8px">'+
   '<tr><td style="padding:6px 0;border-bottom:1px solid var(--line)">Length</td><td style="text-align:right;border-bottom:1px solid var(--line)">'+p.length+' characters</td></tr>'+
   '<tr><td style="padding:6px 0;border-bottom:1px solid var(--line)">Character pool</td><td style="text-align:right;border-bottom:1px solid var(--line)">'+pool+' ('+parts.join(' + ')+')</td></tr>'+
   '<tr><td style="padding:6px 0;border-bottom:1px solid var(--line)">Possible combinations</td><td style="text-align:right;border-bottom:1px solid var(--line)">'+(combos>1e21?combos.toExponential(2):Math.round(combos).toLocaleString())+'</td></tr>'+
   '<tr><td style="padding:6px 0">Brute-force time (10B guesses/sec)</td><td style="text-align:right;font-weight:700">'+fmtTime(combos/2/1e10)+'</td></tr>'+
   '</table><p class="sub" style="margin-top:8px">Entropy assumes random passwords. Dictionary words and patterns are far weaker than the math suggests: use a password manager.</p>';
}
inp.addEventListener('input',analyze);
})();

(function(){
'use strict';
var dateEl=document.getElementById('dow-date'),out=document.getElementById('dow-out');
var DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
var MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
function calc(){
  if(!dateEl.value){out.innerHTML='<p class="sub">Pick a date first.</p>';return;}
  var p=dateEl.value.split('-'),d=new Date(p[0],p[1]-1,p[2]);
  if(isNaN(d.getTime())){out.innerHTML='<p class="sub">Invalid date.</p>';return;}
  var wd=DAYS[d.getDay()];
  var start=new Date(d.getFullYear(),0,0);
  var doy=Math.floor((d-start)/86400000);
  var today=new Date();today.setHours(0,0,0,0);
