(function(){
'use strict';
var dateEl=document.getElementById('wn-date'),out=document.getElementById('wn-out');
function isoWeek(d){
  var t=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));
  var day=(t.getUTCDay()+6)%7;
  t.setUTCDate(t.getUTCDate()-day+3);
  var first=new Date(Date.UTC(t.getUTCFullYear(),0,4));
  var fday=(first.getUTCDay()+6)%7;
  first.setUTCDate(first.getUTCDate()-fday+3);
  var week=1+Math.round((t-first)/(7*86400000));
  return [week,t.getUTCFullYear()];
}
function weeksInYear(y){
  var jan1=new Date(y,0,1);
  var d=(jan1.getDay()+6)%7;
  if(d===3)return 53;
  if(d===2&&((y%4===0&&y%100!==0)||y%400===0))return 53;
  return 52;
}
function fmt(d){return d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'});}
function calc(){
  if(!dateEl.value){out.innerHTML='<p class="sub">Pick a date first.</p>';return;}
  var p=dateEl.value.split('-'),d=new Date(p[0],p[1]-1,p[2]);
  if(isNaN(d.getTime())){out.innerHTML='<p class="sub">Invalid date.</p>';return;}
  var r=isoWeek(d),week=r[0],wy=r[1];
