  var sun=new Date(mon);sun.setDate(mon.getDate()+6);
  out.innerHTML=
   '<p style="font-size:2rem;font-weight:800;margin:4px 0">Week '+week+' <span style="font-size:1.1rem;font-weight:400">of '+wy+'</span></p>'+
   '<table style="width:100%;border-collapse:collapse;margin-top:10px">'+
   '<tr><td style="padding:6px 0;border-bottom:1px solid var(--line)">Week starts (Monday)</td><td style="text-align:right;border-bottom:1px solid var(--line)">'+fmt(mon)+'</td></tr>'+
   '<tr><td style="padding:6px 0;border-bottom:1px solid var(--line)">Week ends (Sunday)</td><td style="text-align:right;border-bottom:1px solid var(--line)">'+fmt(sun)+'</td></tr>'+
   '<tr><td style="padding:6px 0">ISO weeks in '+wy+'</td><td style="text-align:right">'+weeksInYear(wy)+'</td></tr>'+
   '</table><p class="sub" style="margin-top:8px">ISO weeks start on Monday. Week 1 is the week containing the first Thursday of the year.</p>';
}
