(function(){
var $=function(id){return document.getElementById(id);};
var input=$('nb-input'),fromSel=$('nb-from'),toSel=$('nb-to'),
    result=$('nb-result'),errEl=$('nb-error');
var DIGITS='0123456789ABCDEF';
function parseNum(str,base){
  str=(str||'').trim().replace(/^0[xX]/,'').replace(/_/g,'').toUpperCase();
  if(!str)throw new Error('Enter a number first.');
  var neg=false;
  if(str[0]==='-'){neg=true;str=str.slice(1);}
  if(!str)throw new Error('Enter a number first.');
  var val=0n;
  var b=BigInt(base);
  for(var i=0;i<str.length;i++){
    var d=DIGITS.indexOf(str[i]);
    if(d<0||d>=base)throw new Error('Invalid digit "'+str[i]+'" for base '+base+'.');
    val=val*b+BigInt(d);
  }
  return neg?-val:val;
}
function fmt(val,base){
  var neg=val<0n;
  var s=(neg?-val:val).toString(base).toUpperCase();
  return (neg?'-':'')+s;
}
function convert(){
  errEl.textContent='';
