    $('nb-b10').textContent=fmt(v,10);
    $('nb-b16').textContent=fmt(v,16);
  }catch(e){
    result.textContent='—';
    $('nb-b2').textContent=$('nb-b8').textContent=$('nb-b10').textContent=$('nb-b16').textContent='—';
