fromSel.addEventListener('change',convert);
toSel.addEventListener('change',convert);
convert();
})();

(function(){
'use strict';
var inp=document.getElementById('sn-in'),sig=document.getElementById('sn-sig'),out=document.getElementById('sn-out');
function sup(n){var m={'-':'\u207b','0':'\u2070','1':'\u00b9','2':'\u00b2','3':'\u00b3','4':'\u2074','5':'\u2075','6':'\u2076','7':'\u2077','8':'\u2078','9':'\u2079'};return String(n).split('').map(function(c){return m[c]||c;}).join('');}
function convert(){
  var raw=inp.value.trim().replace(/,/g,'');
  var n=Number(raw);
  if(raw===''||!isFinite(n)){out.innerHTML='<p class="sub" style="color:#b91c1c">Enter a valid number, e.g. 123000 or 1.23e5.</p>';return;}
  var s=parseInt(sig.value,10);
  if(n===0){out.innerHTML='<p style="font-size:1.4rem;font-weight:800">0</p><p class="sub">Zero has no meaningful scientific form.</p>';return;}
  var exp=Math.floor(Math.log10(Math.abs(n)));
  var mant=n/Math.pow(10,exp);
  var sci=mant.toPrecision(s)+' \u00d7 10'+sup(exp);
  var eNote=mant.toPrecision(s)+'e'+exp;
  var engExp=Math.floor(exp/3)*3;
  var engMant=n/Math.pow(10,engExp);
  var eng=engMant.toPrecision(s)+' \u00d7 10'+sup(engExp);
  var prefixes={'24':'Y','21':'Z','18':'E','15':'P','12':'T','9':'G','6':'M','3':'k','0':'','-3':'m','-6':'\u00b5','-9':'n','-12':'p','-15':'f','-18':'a','-21':'z','-24':'y'};
  var pfx=prefixes[engExp]!==undefined?prefixes[engExp]:'';
  var plain=n.toLocaleString('en-US',{maximumFractionDigits:20});
  out.innerHTML='<table style="width:100%;border-collapse:collapse">'+
   '<tr><td style="padding:7px 8px;border-bottom:1px solid var(--line);font-weight:700;width:170px">Scientific</td><td style="padding:7px 8px;border-bottom:1px solid var(--line);font-family:ui-monospace,Menlo,monospace">'+sci+'</td></tr>'+
   '<tr><td style="padding:7px 8px;border-bottom:1px solid var(--line);font-weight:700">E-notation</td><td style="padding:7px 8px;border-bottom:1px solid var(--line);font-family:ui-monospace,Menlo,monospace">'+eNote+'</td></tr>'+
   '<tr><td style="padding:7px 8px;border-bottom:1px solid var(--line);font-weight:700">Engineering</td><td style="padding:7px 8px;border-bottom:1px solid var(--line);font-family:ui-monospace,Menlo,monospace">'+eng+(pfx?' ('+engMant.toPrecision(s)+' '+pfx+')':'')+'</td></tr>'+
   '<tr><td style="padding:7px 8px;font-weight:700">Decimal</td><td style="padding:7px 8px;font-family:ui-monospace,Menlo,monospace;word-break:break-all">'+plain+'</td></tr>'+
   '</table><p class="sub" style="margin-top:8px">Engineering notation uses exponents divisible by 3, matching SI prefixes like k, M, G, m and \u00b5.</p>';
}
document.getElementById('sn-go').onclick=convert;
inp.addEventListener('input',convert);
sig.addEventListener('change',convert);
convert();
})();

(function(){
