(function(){
'use strict';
var inp=document.getElementById('ld-in'),out=document.getElementById('ld-out');
var SCRIPTS=[
 [/[\u0600-\u06FF]/,'Arabic script',['Arabic','Persian','Urdu']],
 [/[\u0400-\u04FF]/,'Cyrillic script',['Russian','Ukrainian','Bulgarian','Serbian']],
 [/[\u0370-\u03FF]/,'Greek script',['Greek']],
 [/[\u4E00-\u9FFF]/,'Chinese characters',['Chinese','Japanese']],
 [/[\u3040-\u309F\u30A0-\u30FF]/,'Japanese kana',['Japanese']],
 [/[\uAC00-\uD7AF]/,'Korean Hangul',['Korean']],
 [/[\u0900-\u097F]/,'Devanagari script',['Hindi','Marathi']],
 [/[\u0E00-\u0E7F]/,'Thai script',['Thai']],
 [/[\u0590-\u05FF]/,'Hebrew script',['Hebrew']],
 [/[\u0B80-\u0BFF]/,'Tamil script',['Tamil']],
 [/[\u10A0-\u10FF]/,'Georgian script',['Georgian']]
];
var STOP={
 'English':['the','and','is','are','you','that','with','for','this','have','from','they'],
 'Spanish':['el','la','de','que','los','las','una','para','con','como','est\u00e1','pero'],
 'French':['le','la','les','de','des','est','une','pour','dans','que','pas','vous'],
 'German':['der','die','das','und','ist','mit','von','den','f\u00fcr','nicht','eine','auch'],
 'Italian':['il','la','che','una','per','con','sono','come','della','nella','questo','molto'],
 'Portuguese':['o','a','de','que','para','com','uma','n\u00e3o','como','mais','dos','das'],
 'Dutch':['de','het','een','van','dat','niet','voor','met','zijn','hebben','maar','ook'],
 'Indonesian':['yang','dan','dari','untuk','dengan','adalah','tidak','ini','itu','pada','dalam','akan','saya','kami','mereka'],
 'Malay':['yang','dan','dari','untuk','dengan','adalah','tidak','ini','itu','pada','dalam','saya','kami','mereka','juga'],
 'Turkish':['ve','bir','bu','i\u00e7in','ile','de\u011fil','olan','olarak','daha','gibi','kadar'],
 'Vietnamese':['c\u1ee7a','v\u00e0','l\u00e0','c\u00e1c','trong','v\u1edbi','kh\u00f4ng','n\u00e0y','\u0111\u1ec3','ng\u01b0\u1eddi'],
 'Polish':['nie','jak','jest','ale','dla','jego','przez','jako','lub','tylko'],
 'Swedish':['och','att','det','som','inte','med','f\u00f6r','till','eller','ocks\u00e5']
};
function detect(){
  var t=inp.value.trim();
  if(t.length<4){out.innerHTML='<p class="sub">Paste a longer sample for a reliable result.</p>';return;}
  var script='Latin script',langs=null;
  for(var i=0;i<SCRIPTS.length;i++){
    if(SCRIPTS[i][0].test(t)){script=SCRIPTS[i][1];langs=SCRIPTS[i][2];break;}
  }
  var html='<p class="sub" style="font-size:1rem">Detected script: <strong>'+script+'</strong></p>';
  if(langs){
    html+='<p style="font-size:1.5rem;font-weight:800;margin:6px 0">'+langs[0]+'</p>';
    if(langs.length>1)html+='<p class="sub">Could also be: '+langs.slice(1).join(', ')+'. These languages share the '+script.toLowerCase()+', so a longer sample helps.</p>';
  } else {
    var words=t.toLowerCase().replace(/[^a-z\u00e0-\u00ff\u0100-\u017f\u1ea0-\u1ef9 ]/gi,' ').split(/\s+/).filter(function(w){return w.length>1;});
    var scores=Object.keys(STOP).map(function(L){
      var hits=0;STOP[L].forEach(function(sw){if(words.indexOf(sw)>-1)hits++;});
      return [L,hits];
    }).filter(function(s){return s[1]>0;}).sort(function(a,b){return b[1]-a[1];});
    if(!scores.length){html+='<p style="font-size:1.3rem;font-weight:700;margin:6px 0">Unknown</p><p class="sub">Not enough recognizable words. Try a longer sample of natural sentences.</p>';}
    else{
      var total=0;scores.forEach(function(s){total+=s[1];});
      html+='<p style="font-size:1.8rem;font-weight:800;margin:6px 0">'+scores[0][0]+'</p>';
      html+='<p class="sub">Confidence signals from '+words.length+' words:</p><table style="width:100%;border-collapse:collapse;margin-top:6px;max-width:420px">';
      scores.slice(0,3).forEach(function(s){
        var pct=Math.round(s[1]/Math.max(1,total)*100);
        html+='<tr><td style="padding:6px 0;border-bottom:1px solid var(--line);font-weight:700">'+s[0]+'</td><td style="padding:6px 0;border-bottom:1px solid var(--line)"><div style="background:var(--line);border-radius:6px;height:10px"><div style="width:'+pct+'%;height:10px;border-radius:6px;background:var(--accent)"></div></div></td><td class="sub" style="padding:6px 0 6px 10px;border-bottom:1px solid var(--line);white-space:nowrap">'+pct+'%</td></tr>';
      });
      html+='</table>';
    }
  }
  html+='<p class="sub" style="margin-top:10px">Heuristic detection: best with 2+ full sentences. Short phrases and mixed-language text are harder to classify.</p>';
  out.innerHTML=html;
}
document.getElementById('ld-go').onclick=detect;
document.getElementById('ld-clear').onclick=function(){inp.value='';out.innerHTML='<p class="sub">Paste text and press Detect language.</p>';};
})();

