(function(){
'use strict';
var inp=document.getElementById('hf-in'),out=document.getElementById('hf-out'),
status=document.getElementById('hf-status'),indSel=document.getElementById('hf-indent');
var VOID={area:1,base:1,br:1,col:1,embed:1,hr:1,img:1,input:1,link:1,meta:1,param:1,source:1,track:1,wbr:1};
var RAW={pre:1,script:1,style:1,textarea:1};
function format(html,ind){
  var tokens=html.split(/(<[^>]+>)/g).filter(function(t){return t!=='';});
  var depth=0,lines=[],rawTag=null;
  tokens.forEach(function(tok){
    if(rawTag){
      lines.push(ind.repeat(depth)+tok.trim());
      var close=new RegExp('<\/'+rawTag+'\\s*>','i');
      if(close.test(tok))rawTag=null;
      return;
    }
    if(tok[0]!=='<'){
      var txt=tok.replace(/\s+/g,' ').trim();
      if(txt)lines.push(ind.repeat(depth)+txt);
      return;
    }
    var m=tok.match(/^<\s*(\/?)\s*([a-zA-Z][a-zA-Z0-9-]*)/);
    if(!m){lines.push(ind.repeat(depth)+tok.trim());return;}
    var closing=!!m[1],tag=m[2].toLowerCase();
    var selfClose=/\/\s*>$/.test(tok)||VOID[tag];
    if(closing){depth=Math.max(0,depth-1);lines.push(ind.repeat(depth)+tok.trim());}
    else{
      lines.push(ind.repeat(depth)+tok.trim());
      if(!selfClose){depth++;if(RAW[tag])rawTag=tag;}
    }
  });
  return lines.join('\n');
}
function go(){
  var ind=indSel.value==='tab'?'\t':' '.repeat(parseInt(indSel.value,10));
  if(!inp.value.trim()){status.textContent='Paste some HTML first.';return;}
  out.value=format(inp.value,ind);
  status.textContent='Formatted.';
}
