  if(!out.value)return;
  if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(out.value).then(function(){status.textContent='Copied to clipboard.';});
};
})();

(function(){
'use strict';
var inp=document.getElementById('jf-in'),out=document.getElementById('jf-out'),
status=document.getElementById('jf-status'),indSel=document.getElementById('jf-indent');
function format(src,ind){
  var res='',depth=0,i=0,n=src.length,atLineStart=true;
  function newline(){res+='\n';atLineStart=true;}
  function indent(){res+=ind.repeat(depth);}
  function put(ch){if(atLineStart){indent();atLineStart=false;}res+=ch;}
  while(i<n){
    var c=src[i],nx=src[i+1]||'';
    if(c==='"'||c==="'"||c==='`'){
      var q=c;put(c);i++;
      while(i<n){var d=src[i];put(d);if(d==='\\'){i++;if(i<n)put(src[i]);}else if(d===q)break;i++;}
      i++;continue;
    }
    if(c==='/'&&(nx==='/'||nx==='*')){
      if(nx==='/'){var j=i;while(j<n&&src[j]!=='\n')j++;put(src.slice(i,j).trim());i=j;newline();continue;}
      var k=src.indexOf('*/',i+2);k=k<0?n:k+2;put(src.slice(i,k).trim());i=k;continue;
    }
    if(c==='{'||c==='['){put(c);if(c==='{')depth++;newline();i++;continue;}
    if(c==='}'||c===']'){
      if(c==='}')depth=Math.max(0,depth-1);
      newline();put(c);i++;
      var t=i;while(t<n&&/\s/.test(src[t]))t++;
      if(src[t]===','||src[t]===';'||src[t]===')'||src[t]===']'||src[t]==='}'){put(src[t]);i=t+1;}
      newline();continue;
    }
    if(c===';'){put(';');newline();i++;continue;}
    if(c===','){put(', ');i++;continue;}
    if(c==='\n'||c==='\r'){i++;continue;}
    if(/\s/.test(c)){
      var p=res[res.length-1];
      if(p&&!/[\s({[;,]/.test(p))put(' ');
      i++;continue;
    }
    put(c);i++;
  }
  return res.split('\n').map(function(l){return l.replace(/[ \t]+$/,'');}).filter(function(l,ix,arr){return l.trim()!==''||(ix>0&&arr[ix-1].trim()!=='');}).join('\n').replace(/\n{3,}/g,'\n\n');
}
function go(){
  var ind=indSel.value==='tab'?'\t':' '.repeat(parseInt(indSel.value,10));
  if(!inp.value.trim()){status.textContent='Paste some JavaScript first.';return;}
  out.value=format(inp.value,ind);
  status.textContent='Formatted. Check the output before using it in production.';
}
document.getElementById('jf-go').onclick=go;
