document.getElementById('jf-copy').onclick=function(){
  if(!out.value)return;
  if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(out.value).then(function(){status.textContent='Copied to clipboard.';});
};
