document.getElementById('wm-icons').addEventListener('change',function(e){
  var files=e.target.files;
  var pending=files.length;
  if(!pending)return;
  for(var i=0;i<files.length;i++){
    (function(f){
      var img=new Image();
      img.onload=function(){
        icons.push({src:f.name,sizes:img.naturalWidth+'x'+img.naturalHeight,type:f.type||'image/png'});
        URL.revokeObjectURL(img.src);
        if(--pending===0)renderIcons();
