      img.onerror=function(){if(--pending===0)renderIcons();};
      img.src=URL.createObjectURL(f);
    })(files[i]);
  }
  e.target.value='';
});
function renderIcons(){
  if(!icons.length){iconList.textContent='No icons added yet.';return;}
  iconList.innerHTML=icons.map(function(ic,ix){
