  }).join('');
  var links=iconList.querySelectorAll('a');
  for(var i=0;i<links.length;i++)links[i].onclick=function(ev){ev.preventDefault();icons.splice(parseInt(this.getAttribute('data-ix'),10),1);renderIcons();};
