['dragover','dragenter'].forEach(function(ev){drop.addEventListener(ev,function(e){e.preventDefault();drop.style.borderColor='var(--accent)';});});
drop.addEventListener('dragleave',function(){drop.style.borderColor='';});
drop.addEventListener('drop',function(e){e.preventDefault();drop.style.borderColor='';if(e.dataTransfer.files[0])handle(e.dataTransfer.files[0]);});
inp.addEventListener('change',function(){if(inp.files[0])handle(inp.files[0]);inp.value='';});
function hex(r,g,b){return '#'+[r,g,b].map(function(v){return ('0'+v.toString(16)).slice(-2);}).join('').toUpperCase();}
function handle(f){
  var img=new Image();
  img.onload=function(){
    var max=160,sc=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));
    var cw=Math.max(1,Math.round(img.naturalWidth*sc)),ch=Math.max(1,Math.round(img.naturalHeight*sc));
    var cv=document.createElement('canvas');cv.width=cw;cv.height=ch;
    var cx=cv.getContext('2d');cx.drawImage(img,0,0,cw,ch);
    URL.revokeObjectURL(img.src);
    prev.innerHTML='';
    var pv=document.createElement('img');pv.src=cv.toDataURL();pv.style.cssText='max-width:220px;border-radius:10px;border:1px solid var(--line)';
    prev.appendChild(pv);
    var data=cx.getImageData(0,0,cw,ch).data,buckets={};
    for(var i=0;i<data.length;i+=4){
      if(data[i+3]<128)continue;
      var r=data[i]>>4,g=data[i+1]>>4,b=data[i+2]>>4;
      var k=r+','+g+','+b;
      if(!buckets[k])buckets[k]={c:0,r:0,g:0,b:0};
      buckets[k].c++;buckets[k].r+=data[i];buckets[k].g+=data[i+1];buckets[k].b+=data[i+2];
    }
    var arr=Object.keys(buckets).map(function(k){var o=buckets[k];return {c:o.c,r:Math.round(o.r/o.c),g:Math.round(o.g/o.c),b:Math.round(o.b/o.c)};});
    arr.sort(function(a,b){return b.c-a.c;});
    var picked=[],n=parseInt(document.getElementById('pe-n').value,10);
    arr.forEach(function(col){
      if(picked.length>=n)return;
      var ok=true;
      for(var j=0;j<picked.length;j++){
        var p=picked[j],d=Math.sqrt(Math.pow(p.r-col.r,2)+Math.pow(p.g-col.g,2)+Math.pow(p.b-col.b,2));
        if(d<48){ok=false;break;}
      }
      if(ok)picked.push(col);
    });
    var html='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:10px">';
    picked.forEach(function(col){
      var h=hex(col.r,col.g,col.b);
      html+='<div class="pe-sw" data-h="'+h+'" style="border:1px solid var(--line);border-radius:10px;overflow:hidden;cursor:pointer" title="Click to copy"><div style="height:64px;background:'+h+'"></div><div style="padding:6px 10px;font-family:ui-monospace,Menlo,monospace;font-size:.82rem;font-weight:700">'+h+'</div><div class="sub" style="padding:0 10px 8px;font-size:.75rem">rgb('+col.r+', '+col.g+', '+col.b+')</div></div>';
    });
    html+='</div>';
    out.innerHTML=html;
    var sws=out.querySelectorAll('.pe-sw');
    for(var s=0;s<sws.length;s++)sws[s].onclick=function(){
      var h=this.getAttribute('data-h');
      if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(h);
      this.style.outline='2px solid var(--accent)';
      var el=this;setTimeout(function(){el.style.outline='';},600);
    };
  };
  img.src=URL.createObjectURL(f);
}
document.getElementById('pe-n').addEventListener('change',function(){
  if(prev.querySelector('img'))out.innerHTML='<p class="sub">Re-upload the image to apply the new color count.</p>';
});
})();

(function(){
'use strict';
var out=document.getElementById('un-out'),last=[];
var PRE=['the','real','its','mr','ms','captain','dark','lil','big','super','not','official'];
var SUF=['gaming','plays','hq','tv','lab','zone','verse','ify','ster','aroo','nation','daily'];
var LEET={'a':'4','e':'3','i':'1','o':'0','s':'5','t':'7','l':'1','b':'8','g':'9'};
function rnd(a){return a[Math.floor(Math.random()*a.length)];}
function leet(s){return s.split('').map(function(c){var l=c.toLowerCase();return LEET[l]&&Math.random()<0.6?LEET[l]:c;}).join('');}
function gen(){
  var key=document.getElementById('un-key').value.trim().toLowerCase().replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,'');
  if(!key){out.innerHTML='<p class="sub">Enter a keyword first.</p>';return;}
  var count=parseInt(document.getElementById('un-count').value,10);
  var sep=document.getElementById('un-sep').value;
  var useNum=document.getElementById('un-num').checked,useLeet=document.getElementById('un-leet').checked,useFix=document.getElementById('un-fix').checked;
  var set={},guard=0;
  function push(s){s=s.toLowerCase();if(s.length>=3&&s.length<=24)set[s]=1;}
  push(key);
  while(Object.keys(set).length<count&&guard<500){
    guard++;
    var base=useLeet&&Math.random()<0.4?leet(key):key;
    var r=Math.random(),s='';
    if(useFix&&r<0.3)s=rnd(PRE)+sep+base;
    else if(useFix&&r<0.55)s=base+sep+rnd(SUF);
    else if(useNum&&r<0.8)s=base+sep+Math.floor(Math.random()*99+1);
    else if(r<0.9)s=base+sep+rnd(['x','z','yt','gg','pro','max']);
    else s=base.split('').reverse().join('');
    push(s);
  }
  last=Object.keys(set).slice(0,count);
  var html='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:10px">';
  last.forEach(function(u){
    html+='<div class="un-u" style="border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-family:ui-monospace,Menlo,monospace;font-weight:700;cursor:pointer;text-align:center" title="Click to copy">'+u.replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</div>';
  });
  html+='</div>';
  out.innerHTML=html;
  var els=out.querySelectorAll('.un-u');
  for(var i=0;i<els.length;i++)els[i].onclick=function(){
    var t=this.textContent;
    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t);
    this.style.borderColor='var(--accent)';this.style.background='rgba(124,58,237,.08)';
    var el=this;setTimeout(function(){el.style.borderColor='';el.style.background='';},700);
  };
}
document.getElementById('un-go').onclick=gen;
document.getElementById('un-key').addEventListener('keydown',function(e){if(e.key==='Enter')gen();});
document.getElementById('un-copy').onclick=function(){
  if(last.length&&navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(last.join('\n'));
};
})();

(function(){
'use strict';
var inp=document.getElementById('csv-in'),meta=document.getElementById('csv-meta'),
tbl=document.getElementById('csv-table'),status=document.getElementById('csv-status'),rows=[];
document.getElementById('csv-file').addEventListener('change',function(e){
  var f=e.target.files[0];if(!f)return;
  var r=new FileReader();
  r.onload=function(){inp.value=r.result;parse();};
  r.readAsText(f);
});
function detectDelim(t){
  var first=t.split('\n')[0]||'';
  var c={',':0,';':0,'\t':0,'|':0};
  Object.keys(c).forEach(function(d){c[d]=first.split(d).length-1;});
  var best=',',bn=-1;
  Object.keys(c).forEach(function(d){if(c[d]>bn){bn=c[d];best=d;}});
  return best;
}
function parseCSV(t,delim){
  var out=[],row=[],field='',q=false;
  for(var i=0;i<t.length;i++){
    var c=t[i];
    if(q){
      if(c==='"'){if(t[i+1]==='"'){field+='"';i++;}else q=false;}
      else field+=c;
    }else{
      if(c==='"')q=true;
      else if(c===delim){row.push(field);field='';}
      else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;row.push(field);out.push(row);row=[];field='';}
      else field+=c;
    }
  }
  if(field!==''||row.length){row.push(field);out.push(row);}
  return out.filter(function(r){return !(r.length===1&&r[0]==='');});
}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function parse(){
  var t=inp.value;
  if(!t.trim()){meta.textContent='No data parsed yet.';tbl.innerHTML='';return;}
  var d=detectDelim(t);
  rows=parseCSV(t,d);
  var cols=Math.max.apply(null,rows.map(function(r){return r.length;}));
  meta.textContent=rows.length+' rows x '+cols+' columns. Delimiter: '+(d==='\t'?'tab':d)+' ('+rows[0].length+' fields in header).';
  var html='<table style="border-collapse:collapse;min-width:100%;font-size:.85rem">';
  rows.slice(0,20).forEach(function(r,ri){
    html+='<tr>';
    r.forEach(function(c){html+='<'+(ri===0?'th':'td')+' style="border:1px solid var(--line);padding:6px 10px;text-align:left;white-space:nowrap;'+(ri===0?'background:var(--card2,#f6f6f8);':'')+'">'+esc(c||'')+'</'+(ri===0?'th':'td')+'>';});
    html+='</tr>';
  });
  html+='</table>';
  if(rows.length>20)html+='<p class="sub" style="margin-top:6px">Showing first 20 of '+rows.length+' rows. Conversions include all rows.</p>';
  tbl.innerHTML=html;
  status.textContent='Parsed.';
}
function toObjects(){
  if(rows.length<2)return rows;
  var head=rows[0];
  return rows.slice(1).map(function(r){
    var o={};head.forEach(function(h,i){o[h||('col'+(i+1))]=r[i]!==undefined?r[i]:'';});return o;
  });
}
document.getElementById('csv-go').onclick=parse;
document.getElementById('csv-sample').onclick=function(){inp.value='name,age,city\nAlice,30,"Paris, France"\nBob,25,Berlin\n"Carol, Jr.",28,"New York"';parse();};
document.getElementById('csv-clear').onclick=function(){inp.value='';rows=[];meta.textContent='No data parsed yet.';tbl.innerHTML='';status.textContent='';};
function copyText(t,msg){
  if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(function(){status.textContent=msg;});
}
document.getElementById('csv-json').onclick=function(){if(rows.length)copyText(JSON.stringify(toObjects(),null,2),'Copied as JSON.');};
document.getElementById('csv-tsv').onclick=function(){
  if(!rows.length)return;
  copyText(rows.map(function(r){return r.map(function(c){return /[\t\n"]/.test(c)?'"'+c.replace(/"/g,'""')+'"':c;}).join('\t');}).join('\n'),'Copied as TSV.');
};
document.getElementById('csv-dljson').onclick=function(){
  if(!rows.length)return;
  var b=new Blob([JSON.stringify(toObjects(),null,2)],{type:'application/json'});
  var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='data.json';a.click();
};
})();

