}
function num(id){var v=parseFloat($(id).value);return isNaN(v)?0:v;}
function log10(x){return Math.log(x)/Math.LN10;}
function calc(){
  var out=$('bc-out'),sub=$('bc-sub'),g=gender();
  var h=num('bc-height'),w=num('bc-weight');
  try{
    if(!(h>0)||!(w>0))throw new Error('enter');
    var r;
    if(mode==='navy'){
      var waist=num('bc-waist'),neck=num('bc-neck'),hip=num('bc-hip');
      if(!(waist>0)||!(neck>0))throw new Error('enter');
