        if(waist+hip<=neck)throw new Error('Waist + hip must exceed neck.');
        r=163.205*log10(waist+hip-neck)-97.684*log10(h)-78.387;
      }
      if(r<0||r>70)throw new Error('Check measurements — result out of range.');
      out.textContent=(Math.round(r*10)/10)+'%';
      sub.textContent='Fat mass ≈ '+(Math.round(w*r/100*10)/10)+' kg · Lean ≈ '+(Math.round(w*(1-r/100)*10)/10)+' kg';
    }else if(mode==='lbm'){
