    }else if(mode==='ibw'){
      var hin=h/2.54,ibw;
      if(g==='m')ibw=hin<=60?50:50+2.3*(hin-60);
      else ibw=hin<=60?45.5:45.5+2.3*(hin-60);
      out.textContent=(Math.round(ibw*10)/10)+' kg';
      var lo=ibw*0.9,hi=ibw*1.1;
      sub.textContent='Healthy range ≈ '+(Math.round(lo*10)/10)+'–'+(Math.round(hi*10)/10)+' kg';
    }else{
