    }).join('\n\n');
  },
  dart:function(types,map){
    return types.map(function(d){
      var fs=d.fields.map(function(f){return '  final '+map(f.t)+' '+fieldName(f.n,'dart')+';';});
      var cs=d.fields.map(function(f){return 'required this.'+fieldName(f.n,'dart');});
      var js=d.fields.map(function(f){
        var fn=fieldName(f.n,'dart'),t=map(f.t);
