      });
      return 'class '+d.name+' {\n'+fs.join('\n')+'\n\n  const '+d.name+'({'+cs.join(', ')+'});\n\n  factory '+d.name+'.fromJson(Map<String, dynamic> json) => '+d.name+'(\n'+js.join('\n')+'\n  );\n}';
    }).join('\n\n');
