(function(){
var $=function(id){return document.getElementById(id);};
var op='add',size=2;
var tabs=document.querySelectorAll('.mx-tab');
function setOp(o){
  op=o;
  tabs.forEach(function(t){t.classList.toggle('active',t.dataset.op===o);});
  $('mx-b-block').style.display=(o==='add'||o==='multiply')?'':'none';
  $('mx-scalar').textContent='';
  renderOut(null);
}
tabs.forEach(function(t){t.addEventListener('click',function(){setOp(t.dataset.mode||t.dataset.op);});});
function buildGrid(el,n,vals){
  el.innerHTML='';
  el.style.gridTemplateColumns='repeat('+n+', 1fr)';
  for(var i=0;i<n*n;i++){
    var inp=document.createElement('input');
    inp.type='number';inp.step='any';inp.value=vals?vals[i]:'0';
    inp.setAttribute('aria-label','cell '+(i+1));
    el.appendChild(inp);
  }
}
function readGrid(el){
  var vals=[];
  el.querySelectorAll('input').forEach(function(inp){
    var v=parseFloat(inp.value);
    vals.push(isNaN(v)?0:v);
  });
  var m=[];
  for(var r=0;r<size;r++)m.push(vals.slice(r*size,(r+1)*size));
  return m;
}
function renderOut(m){
  var el=$('mx-out');
  el.innerHTML='';
  if(!m){el.style.display='none';return;}
  el.style.display='grid';
  el.style.gridTemplateColumns='repeat('+m.length+', 1fr)';
  m.forEach(function(row){
    row.forEach(function(v){
      var d=document.createElement('div');
      d.className='mx-cell';
      d.textContent=(Math.round(v*10000)/10000).toString();
      el.appendChild(d);
    });
  });
}
function det(m){
  if(m.length===2)return m[0][0]*m[1][1]-m[0][1]*m[1][0];
  var d=0;
  for(var c=0;c<3;c++){
    var sub=[m[1].slice(0,c).concat(m[1].slice(c+1)),m[2].slice(0,c).concat(m[2].slice(c+1))];
    d+=(c%2?-1:1)*m[0][c]*det(sub);
  }
  return d;
}
function adjugate(m){
  var n=m.length,adj=[];
  for(var r=0;r<n;r++){adj.push([]);for(var c=0;c<n;c++)adj[r].push(0);}
  if(n===2){
    adj[0][0]=m[1][1];adj[0][1]=-m[0][1];adj[1][0]=-m[1][0];adj[1][1]=m[0][0];
    return adj;
  }
  for(var r=0;r<3;r++)for(var c=0;c<3;c++){
    var sub=[];
    for(var rr=0;rr<3;rr++){if(rr===r)continue;var row=[];for(var cc=0;cc<3;cc++){if(cc===c)continue;row.push(m[rr][cc]);}sub.push(row);}
    adj[c][r]=((r+c)%2?-1:1)*det(sub);
  }
  return adj;
}
function calculate(){
  var err=$('mx-error');err.textContent='';
  $('mx-scalar').textContent='';
  try{
    var A=readGrid($('mx-a'));
    if(op==='add'||op==='multiply'){
      var B=readGrid($('mx-b'));
      if(op==='add'){
        renderOut(A.map(function(row,r){return row.map(function(v,c){return v+B[r][c];});}));
      }else{
        var C=[];
        for(var r=0;r<size;r++){C.push([]);for(var c=0;c<size;c++){
          var s=0;for(var k=0;k<size;k++)s+=A[r][k]*B[k][c];
          C[r].push(s);
        }}
        renderOut(C);
      }
    }else if(op==='det'){
      var d=det(A);
      renderOut(null);
      $('mx-scalar').textContent='det(A) = '+(Math.round(d*10000)/10000);
    }else{
      var dd=det(A);
      if(Math.abs(dd)<1e-12)throw new Error('Matrix is singular (determinant is 0) — no inverse exists.');
      var adj=adjugate(A);
      renderOut(adj.map(function(row){return row.map(function(v){return v/dd;});}));
    }
  }catch(e){err.textContent=e.message;renderOut(null);}
}
function rebuild(){
  size=parseInt($('mx-size').value,10);
  var defA=size===2?['1','2','3','4']:['1','2','3','4','5','6','7','8','9'];
  var defB=size===2?['5','6','7','8']:['9','8','7','6','5','4','3','2','1'];
  buildGrid($('mx-a'),size,defA);
  buildGrid($('mx-b'),size,defB);
  renderOut(null);
}
$('mx-size').addEventListener('change',rebuild);
$('mx-calc').addEventListener('click',calculate);
rebuild();
})();

