function parseTime(s){
  var p=String(s).trim().split(':').map(function(x){return parseFloat(x);});
  if(p.some(isNaN))throw new Error('Use hh:mm:ss, mm:ss or seconds.');
  var sec=0;
  if(p.length===3)sec=p[0]*3600+p[1]*60+p[2];
  else if(p.length===2)sec=p[0]*60+p[1];
  else if(p.length===1)sec=p[0];
